window.HU_TECH={"sym": "Symmetry and substitution", "tel": "Telescoping", "two": "Counting two ways", "inv": "Invariants", "pig": "Pigeonhole", "mod": "Modular arithmetic", "vie": "Vieta and symmetric functions", "trg": "Trigonometric identities and bounds", "arint": "Integrals as areas or by symmetry", "fint": "Integral reasoning", "root": "Root counting via monotonicity", "ext": "Extremal principle", "col": "Colouring and parity", "game": "Games and losing positions", "log": "Quantifiers, negation and vacuous truth", "prf": "Proof analysis", "ns": "Necessary and sufficient", "ineq": "Inequalities", "circ": "Circle geometry", "ser": "Series and sequences", "poly": "Polynomials", "cnt": "Counting arguments", "exp": "Exponentials and logarithms", "trans": "Graph transformations", "bin": "Binomial expansion", "diff": "Differentiation, tangents and stationary points", "coord": "Coordinate geometry", "quad": "Quadratics, discriminants and parameters"};
window.HU_PAPERS={"B1": "Set B Paper 1", "B2": "Set B Paper 2", "C1": "Set C Paper 1", "C2": "Set C Paper 2", "D1": "Set D Paper 1", "D2": "Set D Paper 2", "E1": "Set E Paper 1", "E2": "Set E Paper 2", "F1": "Set F Paper 1", "F2": "Set F Paper 2"};
window.HU_QUESTIONS=[{"id": "C2-7", "paper": "C2", "n": 7, "q": "<p>A student is asked to prove: <em>for every integer $n$, if $n^3$ is odd then $n$ is odd.<\/em> The student writes:<\/p><p><br> &ldquo;Let $n$ be odd, so $n=2k+1$ for some integer $k$. Then $n^3=8k^3+12k^2+6k+1=2(4k^3+6k^2+3k)+1$, which is odd. This proves the statement.&rdquo;<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The argument proves the converse. The statement is true, but this is not a proof of it.", "The argument is valid and proves the statement.", "The argument proves the contrapositive of the statement, so it is valid.", "The argument contains an algebraic error.", "The argument proves the converse, and the statement is false."], "ans": "A", "sol": "<p>The student assumes $n$ odd and deduces $n^3$ odd, which is the converse: if $n$ is odd then $n^3$ is odd. The statement asked for is nevertheless true, and the right proof is by contrapositive: if $n$ is even, $n=2k$, then $n^3=8k^3$ is even. The contrapositive of &ldquo;$n^3$ odd $\\Rightarrow n$ odd&rdquo; is &ldquo;$n$ even $\\Rightarrow n^3$ even&rdquo;, not &ldquo;$n$ odd $\\Rightarrow n^3$ odd&rdquo;.<\/p><p><\/p>", "tags": ["prf"], "rating": 4.5}, {"id": "B2-7", "paper": "B2", "n": 7, "q": "<p>What is the smallest positive integer $n$ for which $n!$ is divisible by $10^{10}$?<\/p>", "opts": ["$40$", "$45$", "$50$", "$55$", "$60$"], "ans": "B", "sol": "<p>$10^{10} = 2^{10}5^{10}$, and factorials have far more factors of $2$ than of $5$, so only the fives matter. The number of factors of $5$ in $n!$ is $\\lfloor n/5 \\rfloor + \\lfloor n/25 \\rfloor + \\cdots$. For $n = 44$ this is $8 + 1 = 9$; for $n = 45$ it is $9 + 1 = 10$. So $n = 45$. Option C is the answer to &ldquo;ten multiples of $5$&rdquo;, forgetting that $25$ contributes twice.<\/p><p><\/p>", "tags": ["mod", "cnt"], "rating": 4.6}, {"id": "C1-1", "paper": "C1", "n": 1, "q": "<p>Real numbers $a>1$ and $b>1$ satisfy $\\log_a b = 2\\log_b a$. Find the value of $\\log_{ab} a$.<\/p>", "opts": ["$\\dfrac13$", "$\\dfrac12$", "$\\sqrt2-1$", "$2-\\sqrt2$", "$\\dfrac{\\sqrt2}{2}$", "$\\sqrt2+1$"], "ans": "C", "sol": "<p>Let $t=\\log_a b$. Then $\\log_b a=\\frac1t$, so $t=\\frac2t$ and $t^2=2$. Since $a,b>1$, $t>0$ and $t=\\sqrt2$. Now \\[ \\log_{ab}a=\\frac{1}{\\log_a(ab)}=\\frac{1}{1+\\log_a b}=\\frac{1}{1+\\sqrt2}=\\sqrt2-1 . \\] Option D, $2-\\sqrt2$, is $\\log_{ab}b=\\frac{t}{1+t}$: the same computation with the roles of $a$ and $b$ swapped.<\/p><p><\/p>", "tags": ["sym"], "rating": 4.7}, {"id": "B1-12", "paper": "B1", "n": 12, "q": "<p>Find the complete set of real values of $x$ for which the infinite series \\[ 1 + (x-1) + (x-1)^2 + (x-1)^3 + \\cdots \\] converges and has sum equal to $\\dfrac{1}{2-x}$.<\/p>", "opts": ["all real $x$ with $x \\ne 2$", "$x &lt; 2$", "$0 &lt; x &lt; 2$", "$0 \\le x &lt; 2$", "$1 &lt; x &lt; 2$", "$x > 0$"], "ans": "C", "sol": "<p>The series is geometric with ratio $x - 1$; it converges exactly when $|x-1| &lt; 1$, i.e.\\ $0 &lt; x &lt; 2$, and there its sum is $\\dfrac{1}{1-(x-1)} = \\dfrac{1}{2-x}$. Outside that interval the formula $\\tfrac1{2-x}$ still makes sense as a number but the series diverges, which is the trap in option A. At $x = 0$ the terms are $\\pm1$ and the series does not converge, so option D is also wrong.<\/p><p><\/p>", "tags": ["ser", "log"], "rating": 4.8}, {"id": "C1-4", "paper": "C1", "n": 4, "q": "<p>Find the minimum value of $x^2+\\dfrac{16}{x}$ for $x>0$.<\/p>", "opts": ["$6\\sqrt[3]{2}$", "$8$", "$8\\sqrt2$", "$12$", "$16$", "$20$"], "ans": "D", "sol": "<p>Split the $\\frac{16}{x}$ so that the product of the terms is constant: $x^2+\\frac8x+\\frac8x\\ge 3\\sqrt[3]{x^2\\cdot\\frac8x\\cdot\\frac8x}=3\\sqrt[3]{64}=12$, with equality when $x^2=\\frac8x$, that is $x=2$. Calculus agrees: the derivative $2x-\\frac{16}{x^2}$ vanishes at $x=2$, where the value is $4+8=12$. Applying AM--GM to the two terms $x^2$ and $\\frac{16}{x}$ directly gives the bound $8\\sqrt{x}$, which is not a constant and so says nothing about the minimum.<\/p><p><\/p>", "tags": ["ineq"], "rating": 4.8}, {"id": "B1-10", "paper": "B1", "n": 10, "q": "<p>The roots of $x^2 - 2x - 1 = 0$ are $\\alpha$ and $\\beta$. Find the value of \\[ \\frac{1}{\\alpha^5} + \\frac{1}{\\beta^5}. \\]<\/p>", "opts": ["$-82$", "$-41$", "$-\\dfrac{1}{82}$", "$\\dfrac{1}{82}$", "$41$", "$82$"], "ans": "A", "sol": "<p>Since $\\alpha\\beta = -1$, we have $\\tfrac1\\alpha = -\\beta$ and $\\tfrac1\\beta = -\\alpha$, so the required value is $-(\\alpha^5 + \\beta^5)$. Writing $s_n = \\alpha^n + \\beta^n$ and using $s_{n+1} = 2s_n + s_{n-1}$ (from the equation), $s_1 = 2$, $s_2 = 6$, $s_3 = 14$, $s_4 = 34$, $s_5 = 82$. The answer is $-82$. Option F is the sign slip.<\/p><p><\/p>", "tags": ["vie"], "rating": 4.9}, {"id": "C2-10", "paper": "C2", "n": 10, "q": "<p>Which of the following statements are true for every real $x$? <ol class=\"stmts\" type=\"I\"><li>$\\sin x+\\cos x\\le\\sqrt2$<\/li><li>$\\sin x\\cos x\\le\\tfrac12$<\/li><li>$\\sin^4x+\\cos^4x\\ge\\tfrac12$<\/li><li>$\\sin x+\\cos x\\ge -1$<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I, II and III only", "I, II and IV only", "II and III only", "I, II, III and IV"], "ans": "C", "sol": "<p>I: $\\sin x+\\cos x=\\sqrt2\\sin(x+\\frac\\pi4)\\le\\sqrt2$. II: $\\sin x\\cos x=\\frac12\\sin2x\\le\\frac12$. III: $\\sin^4x+\\cos^4x=(\\sin^2x+\\cos^2x)^2-2\\sin^2x\\cos^2x=1-\\frac12\\sin^22x\\ge\\frac12$. IV fails at $x=\\frac{5\\pi}4$, where the sum is $-\\sqrt2$. The lower bound matching I is $\\ge-\\sqrt2$, not $-1$.<\/p><p><\/p>", "tags": ["trg", "ineq"], "rating": 4.9}, {"id": "C1-5", "paper": "C1", "n": 5, "q": "<p>The set of values of $x$ with $0&lt;x&lt;\\dfrac{\\pi}{2}$ for which \\[ \\tan x+\\cot x&lt;4 \\] is an interval. Find its length.<\/p>", "opts": ["$\\dfrac{\\pi}{24}$", "$\\dfrac{\\pi}{12}$", "$\\dfrac{\\pi}{8}$", "$\\dfrac{\\pi}{6}$", "$\\dfrac{\\pi}{4}$", "$\\dfrac{\\pi}{3}$"], "ans": "F", "sol": "<p>$\\tan x+\\cot x=\\frac{\\sin^2x+\\cos^2x}{\\sin x\\cos x}=\\frac{2}{\\sin 2x}$. For $0&lt;x&lt;\\frac\\pi2$, $\\sin 2x>0$, so the inequality is $\\sin2x>\\frac12$, that is $\\frac\\pi6&lt;2x&lt;\\frac{5\\pi}6$, or $\\frac{\\pi}{12}&lt;x&lt;\\frac{5\\pi}{12}$. The length is $\\frac{\\pi}{3}$. The identity is the whole question; clearing denominators directly leads to a quadratic in $\\tan x$ that gets to the same place more slowly.<\/p><p><\/p>", "tags": ["trg"], "rating": 5.0}, {"id": "D2-1", "paper": "D2", "n": 1, "q": "<p>Which of the following is the negation of the statement <div class=\"c\">&ldquo;In every class, some student has solved every problem.&rdquo;<\/div><\/p>", "opts": ["In every class, no student has solved every problem.", "In some class, some student has not solved any problem.", "In some class, every student has failed to solve at least one problem.", "In every class, every student has failed to solve at least one problem.", "In some class, no student has solved any problem.", "In some class, some student has failed to solve at least one problem."], "ans": "C", "sol": "<p>The statement has three layers: for every class, there exists a student, such that for every problem, the student solved it. Negating swaps each quantifier and negates the innermost claim: there is a class such that for every student there is a problem the student did not solve. That is option C. Option F negates only the middle layer, and option D keeps &ldquo;every class&rdquo; unchanged.<\/p>", "tags": ["log"], "rating": 5.0}, {"id": "E2-1", "paper": "E2", "n": 1, "q": "<p>The statement &ldquo;if a quadrilateral is a rhombus, then its diagonals are perpendicular&rdquo; is true. Which of the following is a counterexample to its <em>converse<\/em>?<\/p>", "opts": ["a square", "a rectangle that is not a square", "a kite that is not a rhombus", "a parallelogram that is not a rhombus", "a rhombus that is not a square", "there is none: the converse is also true"], "ans": "C", "sol": "<p>The converse says: if the diagonals are perpendicular, then the quadrilateral is a rhombus. A counterexample needs perpendicular diagonals but must not be a rhombus. A kite that is not a rhombus is exactly that. Options B and D fail the hypothesis, since their diagonals are not perpendicular, and options A and E are rhombuses, so they satisfy the conclusion.<\/p>", "tags": ["log"], "rating": 5.0}, {"id": "B1-17", "paper": "B1", "n": 17, "q": "<p>Evaluate \\[ \\int_{-2}^{2} (x+2)\\sqrt{4-x^2}\\,dx . \\]<\/p>", "opts": ["$0$", "$8$", "$2\\pi$", "$4\\pi$", "$8\\pi$", "$16$"], "ans": "D", "sol": "<p>Split the integrand. The function $x\\sqrt{4-x^2}$ is odd, so its integral over $[-2,2]$ is $0$. What remains is \\[ 2\\int_{-2}^{2}\\sqrt{4-x^2}\\,dx, \\] and $y = \\sqrt{4-x^2}$ is the upper half of the circle of radius $2$, so the integral is the area of that semicircle, $2\\pi$. The answer is $4\\pi$. There is no need for an antiderivative of $\\sqrt{4-x^2}$; recognising a definite integral as an area is the method. Option E takes the whole circle, option A forgets the even part.<\/p><p><\/p>", "tags": ["arint", "sym"], "rating": 5.1}, {"id": "C2-9", "paper": "C2", "n": 9, "q": "<p>For a real number $x$, the condition <div class=\"c\"> $\\sin x>\\tfrac12$ <\/div> is <span class=\"blank\">________<\/span> for $\\cos 2x&lt;\\tfrac12$.<\/p>", "opts": ["necessary but not sufficient", "sufficient but not necessary", "necessary and sufficient", "neither necessary nor sufficient"], "ans": "B", "sol": "<p>$\\cos2x&lt;\\frac12$ is $1-2\\sin^2x&lt;\\frac12$, that is $\\sin^2x>\\frac14$, or $|\\sin x|>\\frac12$. So $\\sin x>\\frac12$ implies it, and is sufficient. It is not necessary: $x=-\\frac\\pi2$ has $\\cos2x=-1&lt;\\frac12$ but $\\sin x=-1$.<\/p><p><\/p>", "tags": ["ns", "trg"], "rating": 5.1}, {"id": "C2-1", "paper": "C2", "n": 1, "q": "<p>Consider the statement <div class=\"c\"> &ldquo;The train will be on time unless it snows.&rdquo; <\/div> Here &ldquo;$A$ unless $B$&rdquo; means &ldquo;if not $B$, then $A$&rdquo;. Which one of the following is the negation of the statement?<\/p>", "opts": ["It snows and the train is on time.", "It snows and the train is not on time.", "If it snows, then the train will not be on time.", "If the train is not on time, then it snowed.", "It does not snow and the train is not on time.", "It does not snow or the train is not on time."], "ans": "E", "sol": "<p>The statement is &ldquo;if it does not snow, the train is on time&rdquo;. An implication is false in exactly one situation: its hypothesis holds and its conclusion fails. So the negation is &ldquo;it does not snow and the train is not on time&rdquo;. Option D is the contrapositive, which is equivalent to the original, not its negation. Option F is &ldquo;not(not snow) or not on time&rdquo; with the first negation dropped, and in any case the negation of an implication is never an &ldquo;or&rdquo;.<\/p><p><\/p>", "tags": ["log"], "rating": 5.2}, {"id": "D2-2", "paper": "D2", "n": 2, "q": "<p>Consider the statement: <em>if $f'(a)=0$, then the curve $y=f(x)$ has a turning point at $x=a$.<\/em> Which of the following is a counterexample to the statement?<\/p>", "opts": ["$f(x)=x^2$, $a=0$", "$f(x)=x^3$, $a=0$", "$f(x)=x^4$, $a=0$", "$f(x)=x^3-3x$, $a=1$", "$f(x)=x$, $a=0$", "$f(x)=x^4-2x^2$, $a=0$"], "ans": "B", "sol": "<p>A counterexample must make the hypothesis true and the conclusion false. For $x^3$ at $0$ the gradient is zero but the curve keeps increasing through the origin: a point of inflection, not a turning point. Options A, C, D and F have $f'(a)=0$ and a genuine turning point, and option E has $f'(0)=1\\neq0$, so its hypothesis is false and it cannot be a counterexample.<\/p>", "tags": ["log", "diff"], "rating": 5.2}, {"id": "E1-1", "paper": "E1", "n": 1, "q": "<p>Real numbers $x$ and $y$ satisfy $x+y=4$ and $x^3+y^3=40$. Find the value of $x^4+y^4$.<\/p>", "opts": ["$120$", "$128$", "$136$", "$144$", "$152$", "$160$"], "ans": "C", "sol": "<p>Work with the symmetric quantities rather than solving. $x^3+y^3=(x+y)^3-3xy(x+y)$ gives $40=64-12xy$, so $xy=2$. Then $x^2+y^2=16-4=12$, and $x^4+y^4=(x^2+y^2)^2-2x^2y^2=144-8=136$. (The numbers are $2\\pm\\sqrt2$, which are real, so the data are consistent.)<\/p>", "tags": ["sym", "quad"], "rating": 5.2}, {"id": "B1-6", "paper": "B1", "n": 6, "q": "<p>Let $M$ and $m$ be the maximum and minimum values of \\[ (\\sin x + 2\\cos x)(2\\sin x + \\cos x) \\] over all real $x$. Find $Mm$.<\/p>", "opts": ["$-\\dfrac94$", "$-\\dfrac52$", "$-1$", "$0$", "$\\dfrac94$", "$\\dfrac{81}{4}$"], "ans": "A", "sol": "<p>Expanding, \\[ (\\sin x + 2\\cos x)(2\\sin x + \\cos x) = 2\\sin^2 x + 5\\sin x\\cos x + 2\\cos^2 x = 2 + 5\\sin x\\cos x. \\] Now $\\sin x\\cos x$ ranges over $[-\\tfrac12,\\tfrac12]$ (it equals $\\tfrac12\\sin 2x$; or note $(\\sin x \\pm \\cos x)^2 \\ge 0$ gives $|\\sin x\\cos x| \\le \\tfrac12$ with both ends attained). So $M = \\tfrac92$, $m = -\\tfrac12$ and $Mm = -\\tfrac94$.<\/p><p><\/p>", "tags": ["trg"], "rating": 5.3}, {"id": "B2-3", "paper": "B2", "n": 3, "q": "<p>How many positive integers less than $1000$ have the property that their digits, read from left to right, are strictly increasing? (For example $137$ has this property; $370$, $33$ and $71$ do not.)<\/p>", "opts": ["$84$", "$120$", "$129$", "$130$", "$165$", "$512$"], "ans": "C", "sol": "<p>A number with strictly increasing digits cannot contain $0$ (it would have to be the leading digit), and it is determined completely by the set of its digits, which is any non-empty subset of $\\{1, \\dots, 9\\}$ of size at most $3$. So the count is $\\binom91 + \\binom92 + \\binom93 = 9 + 36 + 84 = 129$. Option A counts only the three-digit numbers; option F is all subsets of the nine digits, size unrestricted.<\/p><p><\/p>", "tags": ["cnt"], "rating": 5.3}, {"id": "C1-3", "paper": "C1", "n": 3, "q": "<p>How many integers $x$ satisfy \\[ \\bigl|\\,x^2-5|x|+4\\,\\bigr|&lt;2\\,? \\]<\/p>", "opts": ["$4$", "$5$", "$6$", "$7$", "$8$", "infinitely many"], "ans": "A", "sol": "<p>Put $t=|x|\\ge0$. The inequality is $-2&lt;t^2-5t+4&lt;2$. The left half is $t^2-5t+6>0$, so $t&lt;2$ or $t>3$; the right half is $t^2-5t+2&lt;0$, so $\\frac{5-\\sqrt{17}}{2}&lt;t&lt;\\frac{5+\\sqrt{17}}{2}$, roughly $0.44&lt;t&lt;4.56$. Among non-negative integers this leaves $t=1$ and $t=4$. The boundary values $t=2$ and $t=3$ give $|t^2-5t+4|=2$ exactly and are excluded by the strict inequality, and $t=0$ gives $4$. So $x\\in\\{\\pm1,\\pm4\\}$: four integers. With $\\le$ instead of $&lt;$ the answer would be $8$.<\/p><p><\/p>", "tags": ["root"], "rating": 5.3}, {"id": "C2-2", "paper": "C2", "n": 2, "q": "<p>$P$ and $Q$ are statements, and the statement &ldquo;if $P$ then $Q$&rdquo; is false. Consider: <ol class=\"stmts\" type=\"I\"><li>if not $P$, then $Q$<\/li><li>if $Q$, then not $P$<\/li><li>if $P$, then not $Q$<\/li><li>if not $Q$, then not $P$<\/li><\/ol> Which of these must be true?<\/p>", "opts": ["I only", "II only", "I and II only", "I, II and III only", "IV only", "I, II, III and IV"], "ans": "D", "sol": "<p>&ldquo;If $P$ then $Q$&rdquo; is false only when $P$ is true and $Q$ is false. Then I has a false hypothesis (not $P$), so it is true. II has a false hypothesis ($Q$), so it is true. III has a true hypothesis and a true conclusion (not $Q$), so it is true. IV is the contrapositive of the original, and has the same truth value: false. The single fact to hold on to is that $P\\Rightarrow Q$ is equivalent to (not $P$) or $Q$, so its negation is $P$ and (not $Q$).<\/p><p><\/p>", "tags": ["log"], "rating": 5.3}, {"id": "D1-1", "paper": "D1", "n": 1, "q": "<p>Real numbers $a$, $b$ and $c$ satisfy \\[4^a=9,\\qquad 27^b=25,\\qquad 125^c=64 .\\] Find the value of $abc$.<\/p>", "opts": ["$\\dfrac23$", "$1$", "$\\dfrac43$", "$\\dfrac32$", "$2$", "$\\dfrac83$"], "ans": "C", "sol": "<p>Write each as a logarithm and pull the powers out. $a=\\log_4 9=\\log_2 3$, $b=\\log_{27}25=\\tfrac23\\log_3 5$ and $c=\\log_{125}64=\\tfrac{6}{3}\\log_5 2=2\\log_5 2$. So \\[abc=\\tfrac43\\,\\log_2 3\\cdot\\log_3 5\\cdot\\log_5 2=\\tfrac43,\\] because the chain $\\log_2 3\\cdot\\log_3 5\\cdot\\log_5 2$ is $\\frac{\\ln 3}{\\ln 2}\\cdot\\frac{\\ln5}{\\ln3}\\cdot\\frac{\\ln2}{\\ln5}=1$. The only work is keeping track of the factors $\\tfrac23$ and $2$.<\/p>", "tags": ["exp"], "rating": 5.3}, {"id": "B2-2", "paper": "B2", "n": 2, "q": "<p>Let $N = 2^{2026}$. Consider: <ol class=\"stmts\" type=\"I\"><li>$N - 1$ is divisible by $3$.<\/li><li>$N + 1$ is divisible by $5$.<\/li><li>$N - 1$ is divisible by $7$.<\/li><\/ol> Which of these statements are true?<\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "II and III only", "I, II and III"], "ans": "C", "sol": "<p>Work with remainders of powers of $2$. Modulo $3$ the powers go $2, 1, 2, 1, \\dots$, so $2^{\\text{even}} \\equiv 1$ and I holds. Modulo $5$ the cycle is $2, 4, 3, 1$ of length $4$; $2026 \\equiv 2 \\pmod 4$, so $N \\equiv 4$ and $N + 1 \\equiv 0$: II holds. Modulo $7$ the cycle is $2, 4, 1$ of length $3$; $2026 \\equiv 1 \\pmod 3$, so $N \\equiv 2$ and $N - 1 \\equiv 1 \\ne 0$: III fails. The trap in III is assuming that because $2^3 \\equiv 1$ and $2026$ is even, something nice happens; the exponent has to be read modulo the cycle length $3$, not $2$.<\/p><p><\/p>", "tags": ["mod"], "rating": 5.4}, {"id": "D1-2", "paper": "D1", "n": 2, "q": "<p>The curve $y=f(x)$ has exactly two stationary points: a local minimum at $(2,-3)$ and a local maximum at $(-1,4)$. Which of the following is a local maximum point of the curve \\[y=3-2f(4-2x)\\,?\\]<\/p>", "opts": ["$\\left(\\tfrac52,-5\\right)$", "$(1,9)$", "$(1,-3)$", "$(-1,9)$", "$\\left(\\tfrac52,11\\right)$", "$(3,9)$"], "ans": "B", "sol": "<p>Stationary points of $y=3-2f(4-2x)$ occur where $4-2x$ is $2$ or $-1$, that is at $x=1$ and $x=\\tfrac52$. The inner map $x\\mapsto4-2x$ reverses direction, but a reflection in a vertical line never turns a maximum into a minimum; the factor $-2$ outside does. So the minimum of $f$ becomes a maximum: at $x=1$, $y=3-2(-3)=9$. The maximum of $f$ becomes the minimum $\\left(\\tfrac52,-5\\right)$. The answer is $(1,9)$.<\/p>", "tags": ["trans"], "rating": 5.4}, {"id": "D2-3", "paper": "D2", "n": 3, "q": "<p>For a positive integer $n$, the condition &ldquo;$n$ is divisible by 4&rdquo; is <span class=\"blank\">________<\/span> for &ldquo;$n^2+3n$ is divisible by 4&rdquo;.<\/p>", "opts": ["necessary but not sufficient", "sufficient but not necessary", "necessary and sufficient", "neither necessary nor sufficient"], "ans": "B", "sol": "<p>If $4\\mid n$ then $4\\mid n(n+3)=n^2+3n$, so the condition is sufficient. It is not necessary: $n=1$ gives $n^2+3n=4$, divisible by 4, although $4\\nmid 1$. In general $n(n+3)$ is divisible by 4 when $n\\equiv0$ or $1\\pmod 4$.<\/p>", "tags": ["ns", "mod"], "rating": 5.4}, {"id": "E2-2", "paper": "E2", "n": 2, "q": "<p>Which of the following statements about real numbers are true? <ol class=\"stmts\" type=\"I\"><li>For every $x$ there is a $y$ with $y>x$.<\/li><li>There is a $y$ such that $y>x$ for every $x$.<\/li><li>For every $x$ there is a $y$ with $y^2=x$.<\/li><li>There is an $x$ such that $xy=x$ for every $y$.<\/li><\/ol><\/p>", "opts": ["I only", "I and IV only", "I, II and IV only", "IV only", "I and III only", "I, III and IV only"], "ans": "B", "sol": "<p>I is true: take $y=x+1$. II swaps the quantifiers and is false: no single $y$ exceeds every $x$, since it would have to exceed itself. III fails for negative $x$. IV is true with $x=0$. So I and IV. The pair I and II is the whole point: &ldquo;for every, there is&rdquo; and &ldquo;there is, for every&rdquo; are different claims.<\/p>", "tags": ["log"], "rating": 5.4}, {"id": "F1-1", "paper": "F1", "n": 1, "q": "<p>Given that $a=\\log_2 3$ and $b=\\log_3 5$, express $\\log_{15}20$ in terms of $a$ and $b$.<\/p>", "opts": ["$\\dfrac{2+ab}{a+b}$", "$\\dfrac{2+ab}{a(1+b)}$", "$\\dfrac{2+b}{a+ab}$", "$\\dfrac{1+2ab}{a(1+b)}$", "$\\dfrac{2a+b}{a+b}$", "$\\dfrac{2+a}{1+ab}$"], "ans": "B", "sol": "<p>Convert everything to base $2$. $\\log_2 5=\\log_23\\cdot\\log_35=ab$. Then \\[\\log_{15}20=\\frac{\\log_2 20}{\\log_2 15}=\\frac{2+\\log_25}{\\log_23+\\log_25}=\\frac{2+ab}{a+ab}=\\frac{2+ab}{a(1+b)} .\\] Option A treats $\\log_25$ as $b$, forgetting that $b$ is a base-3 logarithm.<\/p>", "tags": ["exp"], "rating": 5.4}, {"id": "B2-16", "paper": "B2", "n": 16, "q": "<p>A student is asked to prove the following claim: <em>if $a$ and $b$ are positive integers and $a^2 + b^2$ is divisible by $3$, then both $a$ and $b$ are divisible by $3$.<\/em> The student writes:<\/p><p><br> &ldquo;Every square leaves remainder $0$ or $1$ on division by $3$. If neither $a$ nor $b$ were divisible by $3$, then $a^2 + b^2$ would leave remainder $1 + 1 = 2$, so it would not be divisible by $3$. Hence at least one of $a$, $b$ is divisible by $3$, and the claim is proved.&rdquo;<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The claim is false: $a = 1$, $b = 2$ is a counterexample.", "The claim is true and the argument proves it.", "The claim is true, but the argument proves only that at least one of $a$, $b$ is divisible by $3$; the case in which exactly one of them is divisible by $3$ still has to be ruled out.", "The claim is true, but the argument is invalid because a square can leave remainder $2$ on division by $3$.", "The claim is false: $a = b = 3$ is a counterexample."], "ans": "C", "sol": "<p>The claim is true, but the argument does not reach it. What has been shown is that $a$ and $b$ cannot both be non-multiples of $3$; that leaves open the case where exactly one of them is, and the argument never mentions it. That case is easy to close (the remainders are then $0 + 1 = 1$, again not divisible by $3$), but it has to be closed, and a proof that omits a case proves only the cases it treats. Options A and E are not counterexamples: $1 + 4 = 5$ is not divisible by $3$, and $a = b = 3$ satisfies the conclusion. Option D is false since squares are $0$ or $1$ modulo $3$. The point of the question is the difference between &ldquo;at least one&rdquo; and &ldquo;both&rdquo;, which the student's final sentence quietly glosses over.<\/p><p><\/p>", "tags": ["prf"], "rating": 5.5}, {"id": "D2-4", "paper": "D2", "n": 4, "q": "<p>Each of six cards has a whole number on one side and a shape on the other. The visible faces are \\[4,\\qquad 7,\\qquad \\text{triangle},\\qquad \\text{circle},\\qquad 10,\\qquad \\text{square}.\\] The rule is: <em>if a card has an even number on one side, then it has a triangle on the other side.<\/em> Which cards must be turned over to check whether the rule holds for all six cards?<\/p>", "opts": ["4 and 10 only", "4, 10 and the triangle", "4, 7 and 10", "4, 10, the circle and the square", "the circle and the square only", "all six cards"], "ans": "D", "sol": "<p>The rule fails only on a card with an even number and a non-triangle. So check the even numbers, $4$ and $10$, in case a non-triangle is behind them, and the non-triangles, the circle and the square, in case an even number is behind them. The $7$ cannot break the rule whatever is behind it, and nor can the triangle: the rule does not say that triangles only go with even numbers. Turning the triangle is the classic error of testing the converse.<\/p>", "tags": ["log"], "rating": 5.5}, {"id": "B1-13", "paper": "B1", "n": 13, "q": "<p>How many chords of the circle $x^2 + y^2 = 25$ have length $6$ and pass through the point $(3,1)$?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$", "infinitely many"], "ans": "A", "sol": "<p>A chord of length $6$ in a circle of radius $5$ sits at distance $\\sqrt{25 - 9} = 4$ from the centre. Any line through $(3,1)$ has distance at most $|OP| = \\sqrt{10} &lt; 4$ from the origin, since the perpendicular distance to a line through $P$ cannot exceed the distance to $P$ itself. So no such chord exists. The instinct to answer $2$ works for chords of length $8$, which need distance $3 &lt; \\sqrt{10}$.<\/p><p><\/p>", "tags": ["circ"], "rating": 5.6}, {"id": "C2-12", "paper": "C2", "n": 12, "q": "<p>Which of the following statements are true for every $x$ with $0&lt;x&lt;\\dfrac{\\pi}{2}$? <ol class=\"stmts\" type=\"I\"><li>$\\sin x+\\cos x>1$<\/li><li>$\\sin 2x&lt;2\\sin x$<\/li><li>$\\cos 2x>\\cos x$<\/li><li>$\\tan x>\\sin x$<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I, II and III only", "II and IV only", "I, II, III and IV", "I, II and IV only"], "ans": "F", "sol": "<p>I: $(\\sin x+\\cos x)^2=1+\\sin2x>1$ on this interval, and the sum is positive. II: $\\sin2x=2\\sin x\\cos x&lt;2\\sin x$ since $0&lt;\\cos x&lt;1$ and $\\sin x>0$. III: $\\cos2x-\\cos x=2\\cos^2x-\\cos x-1=(2\\cos x+1)(\\cos x-1)&lt;0$ here, so III is false for every such $x$. IV: $\\tan x=\\frac{\\sin x}{\\cos x}>\\sin x$ since $0&lt;\\cos x&lt;1$. So I, II and IV.<\/p><p><\/p>", "tags": ["trg", "ineq"], "rating": 5.6}, {"id": "D1-3", "paper": "D1", "n": 3, "q": "<p>Find the coefficient of $x^4$ in the expansion of \\[(2+x)^6\\left(1-\\tfrac{x}{2}\\right)^6 .\\]<\/p>", "opts": ["$0$", "$15$", "$30$", "$60$", "$120$", "$240$"], "ans": "D", "sol": "<p>Multiply the brackets before expanding: $(2+x)\\left(1-\\tfrac x2\\right)=2-x+x-\\tfrac{x^2}{2}=2-\\tfrac{x^2}{2}$. So the product is $\\left(2-\\tfrac{x^2}{2}\\right)^6$, which contains only even powers. The $x^4$ term comes from choosing $-\\tfrac{x^2}{2}$ twice: \\[\\binom62\\,2^4\\left(-\\tfrac12\\right)^2=15\\cdot16\\cdot\\tfrac14=60 .\\] Expanding the two sixth powers separately and convolving the coefficients also works, but takes five products and invites sign errors.<\/p>", "tags": ["bin"], "rating": 5.6}, {"id": "E1-2", "paper": "E1", "n": 2, "q": "<p>Find the product of all the real solutions of \\[2\\log_x 4-\\log_2 x=1 .\\]<\/p>", "opts": ["$\\dfrac14$", "$\\dfrac12$", "$1$", "$2$", "$4$", "$\\sqrt2$"], "ans": "B", "sol": "<p>With $t=\\log_2x$, we have $\\log_x4=\\frac2t$, so $\\frac4t-t=1$, that is $t^2+t-4=0$. Both roots are real and non-zero, giving two valid $x$ (positive, and not equal to $1$). The product of the solutions is $2^{t_1}\\cdot2^{t_2}=2^{t_1+t_2}=2^{-1}=\\tfrac12$ by Vieta, without finding either root.<\/p>", "tags": ["exp", "vie"], "rating": 5.6}, {"id": "E1-3", "paper": "E1", "n": 3, "q": "<p>The point $(1,2)$ is reflected in the line $y=2x-3$. Find the coordinates of its image.<\/p>", "opts": ["$\\left(\\tfrac{17}{5},\\tfrac45\\right)$", "$(3,1)$", "$\\left(\\tfrac{11}{5},\\tfrac25\\right)$", "$(-1,3)$", "$\\left(\\tfrac{13}{5},\\tfrac65\\right)$", "$\\left(\\tfrac{17}{5},-\\tfrac45\\right)$"], "ans": "A", "sol": "<p>The perpendicular through $(1,2)$ has gradient $-\\tfrac12$: $y=-\\tfrac12x+\\tfrac52$. It meets $y=2x-3$ where $\\tfrac52x=\\tfrac{11}{2}$, at $\\left(\\tfrac{11}{5},\\tfrac75\\right)$, the midpoint of the point and its image. So the image is $\\left(2\\cdot\\tfrac{11}{5}-1,\\ 2\\cdot\\tfrac75-2\\right)=\\left(\\tfrac{17}{5},\\tfrac45\\right)$. Option C is the foot of the perpendicular, a common place to stop.<\/p>", "tags": ["coord"], "rating": 5.6}, {"id": "E2-3", "paper": "E2", "n": 3, "q": "<p>For a quadratic function $f$, the condition &ldquo;$f(1)$ and $f(3)$ have opposite signs&rdquo; is <span class=\"blank\">________<\/span> for &ldquo;$f(x)=0$ has at least one root strictly between $1$ and $3$&rdquo;.<\/p>", "opts": ["necessary but not sufficient", "sufficient but not necessary", "necessary and sufficient", "neither necessary nor sufficient"], "ans": "B", "sol": "<p>If $f(1)$ and $f(3)$ have opposite signs, the continuous function $f$ must cross zero between them: sufficient. It is not necessary, because both roots may lie between $1$ and $3$: $f(x)=(x-1.5)(x-2.5)$ has $f(1)$ and $f(3)$ both positive.<\/p>", "tags": ["ns", "quad"], "rating": 5.6}, {"id": "F1-2", "paper": "F1", "n": 2, "q": "<p>Which of the following single transformations map the curve $y=4^x$ onto the curve $y=2^{2x+3}$? <ol class=\"stmts\" type=\"I\"><li>A translation by $\\tfrac32$ in the negative $x$-direction.<\/li><li>A stretch parallel to the $y$-axis with scale factor $8$.<\/li><li>A stretch parallel to the $x$-axis with scale factor $\\tfrac12$.<\/li><li>A translation by $3$ in the positive $y$-direction.<\/li><\/ol><\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "II and IV only", "I, II and III only"], "ans": "C", "sol": "<p>$2^{2x+3}=4^{x+3/2}$, which is $y=4^x$ translated $\\tfrac32$ to the left: I works. Also $2^{2x+3}=8\\cdot4^x$: II works. III gives $4^{2x}=16^x$, and IV gives $4^x+3$; neither is right. For exponential curves a horizontal translation and a vertical stretch are the same transformation, which is why two options succeed.<\/p>", "tags": ["trans", "exp"], "rating": 5.6}, {"id": "F1-3", "paper": "F1", "n": 3, "q": "<p>The geometric series $3+6+12+24+\\cdots$ is summed term by term. What is the smallest number of terms for which the sum exceeds $1\\,000\\,000$?<\/p>", "opts": ["$17$", "$18$", "$19$", "$20$", "$21$", "$22$"], "ans": "C", "sol": "<p>The sum of $n$ terms is $3(2^n-1)$. We need $2^n-1>333\\,333.\\overline{3}$, so $2^n\\ge333\\,335$. Since $2^{18}=262\\,144$ is too small and $2^{19}=524\\,288$ is enough, $n=19$. Using $2^{10}\\approx10^3$ carelessly gives $2^{20}\\approx10^6$, off by one in the wrong direction.<\/p>", "tags": ["ser", "exp"], "rating": 5.6}, {"id": "F2-1", "paper": "F2", "n": 1, "q": "<p>$A$, $B$ and $C$ are statements. You are told: <div class=\"c\">&ldquo;$A$ only if $B$&rdquo;, \\quad &ldquo;$C$ if $B$&rdquo;, \\quad &ldquo;not $C$ unless $A$&rdquo;.<\/div> Which of the following follows?<\/p>", "opts": ["$A$ and $B$ are equivalent, but $C$ need not be equivalent to either.", "$A$ implies $C$, but not conversely.", "$A$, $B$ and $C$ are all equivalent.", "$C$ implies $A$, and nothing else follows.", "No two of $A$, $B$, $C$ need be equivalent.", "$B$ and $C$ are equivalent, but $A$ need not be equivalent to either."], "ans": "C", "sol": "<p>Translate each clause. &ldquo;$A$ only if $B$&rdquo; is $A\\Rightarrow B$. &ldquo;$C$ if $B$&rdquo; is $B\\Rightarrow C$. &ldquo;Not $C$ unless $A$&rdquo; means &ldquo;if not $A$ then not $C$&rdquo;, whose contrapositive is $C\\Rightarrow A$. The implications form a cycle $A\\Rightarrow B\\Rightarrow C\\Rightarrow A$, so all three are equivalent.<\/p>", "tags": ["log", "ns"], "rating": 5.6}, {"id": "F2-2", "paper": "F2", "n": 2, "q": "<p>Which of the following statements are true? <ol class=\"stmts\" type=\"I\"><li>$2^{2024}$ ends in the digit $6$.<\/li><li>$3^{2026}$ ends in the digit $9$.<\/li><li>$7^{2025}$ ends in the digit $7$.<\/li><li>$4^{2025}$ ends in the digit $6$.<\/li><\/ol><\/p>", "opts": ["I and II only", "I, II, III and IV", "I, II and III only", "II and III only", "I and IV only", "III only"], "ans": "C", "sol": "<p>Last digits repeat with period $4$ (or $2$ for $4$). Powers of $2$ end in $2,4,8,6$, and $2024\\equiv0\\pmod4$ gives $6$: true. Powers of $3$ end in $3,9,7,1$, and $2026\\equiv2$ gives $9$: true. Powers of $7$ end in $7,9,3,1$, and $2025\\equiv1$ gives $7$: true. Powers of $4$ end in $4,6$ alternately, and $2025$ is odd, giving $4$: false.<\/p>", "tags": ["mod"], "rating": 5.6}, {"id": "B2-12", "paper": "B2", "n": 12, "q": "<p>A sequence is defined by $a_1 = 4$ and $a_{n+1} = a_n^2 - 2$ for $n \\ge 1$. Consider: <ol class=\"stmts\" type=\"I\"><li>No term of the sequence is divisible by $3$.<\/li><li>For every $n \\ge 2$, $a_n$ leaves remainder $2$ on division by $12$.<\/li><li>Every term of the sequence ends in the digit $4$.<\/li><li>Some term of the sequence is divisible by $5$.<\/li><\/ol> How many of these statements are true?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$"], "ans": "D", "sol": "<p>Each statement is a claim about remainders, and the recursion $a \\mapsto a^2 - 2$ acts on remainders. Modulo $3$: $4 \\equiv 1$, then $1^2 - 2 \\equiv 2$, then $2^2 - 2 = 2$, and the remainder stays $2$ forever; no term is divisible by $3$, so I holds. Modulo $12$: $a_2 = 14 \\equiv 2$, and $2^2 - 2 = 2$, so every later term is $2 \\pmod{12}$; II holds. Modulo $10$: $4 \\mapsto 16 - 2 = 14 \\equiv 4$, so every term ends in $4$; III holds. Modulo $5$: the remainder is $4$ forever, so no term is divisible by $5$; IV fails. Three of the four are true. The first four terms $4, 14, 194, 37634$ confirm all of this, but the remainder argument is what makes it a proof rather than a pattern.<\/p><p><\/p>", "tags": ["mod", "ser"], "rating": 5.7}, {"id": "B1-8", "paper": "B1", "n": 8, "q": "<p>Find the sum of all solutions of \\[ \\sin x \\cos x = \\sin x + \\cos x - 1 \\] in the range $0^\\circ \\le x \\le 360^\\circ$.<\/p>", "opts": ["$90^\\circ$", "$180^\\circ$", "$450^\\circ$", "$540^\\circ$", "$720^\\circ$", "$900^\\circ$"], "ans": "C", "sol": "<p>Let $s = \\sin x + \\cos x$, so $\\sin x\\cos x = \\tfrac12(s^2-1)$. The equation becomes $s^2 - 1 = 2s - 2$, i.e.\\ $(s-1)^2 = 0$, so $\\sin x + \\cos x = 1$. Squaring, $\\sin x\\cos x = 0$, which gives the candidates $0^\\circ, 90^\\circ, 180^\\circ, 270^\\circ, 360^\\circ$; but squaring is not reversible, and checking in $\\sin x + \\cos x = 1$ kills $180^\\circ$ and $270^\\circ$. The solutions are $0^\\circ, 90^\\circ, 360^\\circ$ with sum $450^\\circ$. Option F is the unchecked sum $900^\\circ$; option A forgets the endpoints.<\/p><p><\/p>", "tags": ["trg", "prf"], "rating": 5.8}, {"id": "B2-1", "paper": "B2", "n": 1, "q": "<p>The twenty numbers $1, \\tfrac12, \\tfrac13, \\dots, \\tfrac{1}{20}$ are written on a board. A move consists of choosing two numbers $a$ and $b$ on the board, erasing them, and writing the single number \\[ \\frac{ab}{a+b} \\] in their place. After $19$ moves exactly one number remains. Which of the following is true?<\/p>", "opts": ["The final number is always $\\dfrac{1}{20}$.", "The final number is always $\\dfrac{1}{21}$.", "The final number is always $\\dfrac{1}{210}$.", "The final number is always $20$.", "The final number is always $210$.", "The final number depends on the order in which the moves are made."], "ans": "C", "sol": "<p>Look for a quantity a move does not change. Since $\\dfrac{1}{ab/(a+b)} = \\dfrac1a + \\dfrac1b$, the sum of the reciprocals of the numbers on the board is invariant. Initially it is $1 + 2 + \\cdots + 20 = 210$, so the final number has reciprocal $210$, whatever order the moves are made in. The answer is $\\tfrac{1}{210}$. Option F is the answer for someone who tries a couple of orders, gets messy fractions, and gives up.<\/p><p><\/p>", "tags": ["inv"], "rating": 5.8}, {"id": "C2-5", "paper": "C2", "n": 5, "q": "<p>A student wants to prove the following statement by contradiction: <div class=\"c\"> for every real $x$, if $x^2-3x+2&lt;0$ then $1&lt;x&lt;2$. <\/div> Which of the following is a correct first line for such a proof?<\/p>", "opts": ["Suppose that for every real $x$, $x^2-3x+2\\ge 0$ and ($x\\le1$ or $x\\ge2$).", "Suppose there is a real $x$ with $x^2-3x+2&lt;0$ and ($x\\le1$ or $x\\ge2$).", "Suppose there is a real $x$ with $x^2-3x+2&lt;0$ and $x\\le1$ and $x\\ge2$.", "Suppose there is a real $x$ with $x^2-3x+2\\ge0$ and $1&lt;x&lt;2$.", "Suppose there is a real $x$ with $x^2-3x+2\\ge0$ or $1&lt;x&lt;2$.", "Suppose there is a real $x$ such that, if $x^2-3x+2&lt;0$ then ($x\\le1$ or $x\\ge2$)."], "ans": "B", "sol": "<p>A proof by contradiction of &ldquo;for all $x$, if $A(x)$ then $B(x)$&rdquo; starts from its negation: there is an $x$ with $A(x)$ and not $B(x)$. Here $B(x)$ is $1&lt;x&lt;2$, meaning $x>1$ and $x&lt;2$, and its negation is $x\\le1$ or $x\\ge2$. Option C negates the conclusion incorrectly: no $x$ satisfies both $x\\le1$ and $x\\ge2$, so that assumption leads to a contradiction for a trivial reason and proves nothing about the statement.<\/p><p><\/p>", "tags": ["log", "prf"], "rating": 5.8}, {"id": "D1-4", "paper": "D1", "n": 4, "q": "<p>An arithmetic progression has first term $a$ and non-zero common difference $d$. Its 1st, 4th and 13th terms, in that order, are the first three terms of a geometric progression, and the sum of the first 20 terms of the arithmetic progression is 440. Find the sum of the first five terms of the geometric progression.<\/p>", "opts": ["$121$", "$186$", "$242$", "$324$", "$363$", "$484$"], "ans": "E", "sol": "<p>The geometric condition is $(a+3d)^2=a(a+12d)$, which gives $9d^2=6ad$, so $a=\\tfrac32d$ since $d\\neq0$. Then $S_{20}=10(2a+19d)=220d=440$, so $d=2$ and $a=3$. The terms are $3$, $9$, $27$: ratio $3$. The first five terms sum to $3+9+27+81+243=363$. Notice that the ratio is $3$ whatever $d$ is; the sum of 440 is needed only to fix the scale.<\/p>", "tags": ["ser"], "rating": 5.8}, {"id": "E1-4", "paper": "E1", "n": 4, "q": "<p>Evaluate \\[\\sum_{k=1}^{48}\\frac{1}{\\sqrt{k}+\\sqrt{k+2}} .\\]<\/p>", "opts": ["$2\\sqrt2$", "$3+\\sqrt2$", "$6$", "$3+2\\sqrt2$", "$4+2\\sqrt2$", "$7-\\sqrt2$"], "ans": "D", "sol": "<p>Rationalise: $\\frac{1}{\\sqrt k+\\sqrt{k+2}}=\\frac{\\sqrt{k+2}-\\sqrt k}{2}$. The sum telescopes with a gap of two, so two terms survive at each end: \\[\\tfrac12\\left(\\sqrt{50}+\\sqrt{49}-\\sqrt1-\\sqrt2\\right)=\\tfrac12\\left(5\\sqrt2+7-1-\\sqrt2\\right)=3+2\\sqrt2 .\\] Keeping only one surviving term at each end, as for a gap of one, gives the wrong answer.<\/p>", "tags": ["sym"], "rating": 5.8}, {"id": "E2-4", "paper": "E2", "n": 4, "q": "<p>Call a positive integer <em>neat<\/em> if it can be written as the difference of the squares of two integers. Which of the following statements are true? <ol class=\"stmts\" type=\"I\"><li>Every odd positive integer is neat.<\/li><li>The product of two neat numbers is neat.<\/li><li>The sum of two neat numbers is neat.<\/li><li>If $n$ is neat, then $2n$ is neat.<\/li><\/ol><\/p>", "opts": ["I only", "II only", "I and II only", "I, II and III only", "I and IV only", "I, II, III and IV"], "ans": "C", "sol": "<p>I: $2m+1=(m+1)^2-m^2$. Next, $a^2-b^2=(a-b)(a+b)$, and the two factors have the same parity, so the difference is odd or a multiple of $4$; it is never $2\\pmod4$. Conversely $4m=(m+1)^2-(m-1)^2$. So the neat numbers are exactly those not congruent to $2\\pmod 4$. II: a product of two such numbers is odd or a multiple of $4$. III fails: $1+1=2$. IV fails: $n=1$ gives $2$. So I and II.<\/p>", "tags": ["log", "mod"], "rating": 5.8}, {"id": "E2-5", "paper": "E2", "n": 5, "q": "<p>A student solves \\[\\frac{x^2-4}{x-2}=x^2-2x+4\\] as follows: &ldquo;The left-hand side simplifies to $x+2$, so $x+2=x^2-2x+4$, giving $x^2-3x+2=0$ and $x=1$ or $x=2$.&rdquo; Which of the following is correct?<\/p>", "opts": ["The working and the answer are both correct.", "The simplification is invalid, and in fact there are no solutions.", "The quadratic was solved incorrectly.", "$x=2$ must be rejected, so the only solution is $x=1$.", "$x=1$ must be rejected, so the only solution is $x=2$.", "There are three solutions: $1$, $2$ and $-2$."], "ans": "D", "sol": "<p>The simplification $\\frac{x^2-4}{x-2}=x+2$ is valid only when $x\\neq2$, since the original left-hand side is undefined at $x=2$. So the root $x=2$ of the quadratic must be discarded, and $x=1$ is the only solution. Check: at $x=1$ both sides equal $3$.<\/p>", "tags": ["prf", "ineq"], "rating": 5.8}, {"id": "E2-6", "paper": "E2", "n": 6, "q": "<p>What is the largest positive integer $d$ with the property that, for every integer $n$, if $n^2$ is divisible by $12$ then $n$ is divisible by $d$?<\/p>", "opts": ["$2$", "$3$", "$4$", "$6$", "$12$", "$24$"], "ans": "D", "sol": "<p>If $12\\mid n^2$ then $3\\mid n^2$, so $3\\mid n$ (as $3$ is prime), and $4\\mid n^2$, so $n$ is even. Hence $6\\mid n$. Nothing more is forced: $n=6$ has $n^2=36$ divisible by $12$, and $6$ is not divisible by $4$ or $12$. So $d=6$. The tempting answer $12$ assumes that $12\\mid n^2$ implies $12\\mid n$, which fails because $12$ has a square factor.<\/p>", "tags": ["mod"], "rating": 5.8}, {"id": "F1-4", "paper": "F1", "n": 4, "q": "<p>Find the coefficient of $x^3$ in the expansion of $(1+x+x^2)^5$.<\/p>", "opts": ["$10$", "$15$", "$20$", "$25$", "$30$", "$35$"], "ans": "E", "sol": "<p>Write $1+x+x^2=(1+x)+x^2$ and expand by the binomial theorem: $\\sum_{j}\\binom5j(1+x)^{5-j}x^{2j}$. An $x^3$ term needs $2j\\le3$. For $j=0$, take the $x^3$ coefficient of $(1+x)^5$, which is $10$. For $j=1$, take $5$ times the $x$ coefficient of $(1+x)^4$, which is $5\\cdot4=20$. The total is $30$.<\/p>", "tags": ["bin"], "rating": 5.8}, {"id": "F2-3", "paper": "F2", "n": 3, "q": "<p>A student proves that $\\left|x+\\dfrac1x\\right|\\ge2$ for every non-zero real $x$.<\/p><p><br> (I) If $x>0$: $(x-1)^2\\ge0$, so $x^2+1\\ge2x$; dividing by $x>0$ gives $x+\\dfrac1x\\ge2$.<br> (II) If $x&lt;0$: $(x+1)^2\\ge0$, so $x^2+1\\ge-2x$; dividing by $x&lt;0$ reverses the inequality, giving $x+\\dfrac1x\\le-2$.<br> (III) In either case, $\\left|x+\\dfrac1x\\right|\\ge2$.<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The proof is valid.", "Line II is wrong: the inequality should not be reversed.", "Line III does not follow from lines I and II.", "Line I is wrong: it needs $x\\ge1$.", "The claim is false for $-1&lt;x&lt;0$.", "Line II uses the wrong square."], "ans": "A", "sol": "<p>I is correct. II divides $x^2+1\\ge-2x$ by the negative number $x$ and correctly reverses it: $x+\\frac1x\\le-2$. III combines the two cases. The proof is valid. Using $(x-1)^2$ in case II would only give $x+\\frac1x\\le2$, which is true but too weak; choosing $(x+1)^2$ is what makes it work.<\/p>", "tags": ["prf", "ineq"], "rating": 5.8}, {"id": "B1-2", "paper": "B1", "n": 2, "q": "<p>Evaluate \\[ \\int_{-1}^{5} \\bigl|\\,x^3 - 6x^2 + 12x - 9\\,\\bigr| \\,dx. \\]<\/p>", "opts": ["$-6$", "$6$", "$24$", "$36$", "$42$", "$48$"], "ans": "E", "sol": "<p>The cubic is $(x-2)^3 - 1$, so put $u = x - 2$; the limits become $-3$ and $3$ and the integrand is $|u^3 - 1|$, which changes sign at $u = 1$. Then \\[ \\int_{-3}^{1} (1 - u^3)\\,du + \\int_{1}^{3} (u^3 - 1)\\,du = 24 + 18 = 42. \\] Ignoring the modulus gives $\\int_{-3}^{3}(u^3-1)\\,du = -6$, option A, which is negative and therefore impossible for the integral of a non-negative function. A negative answer to a modulus integral is always a signal to look again.<\/p><p><\/p>", "tags": ["vie"], "rating": 5.9}, {"id": "B2-4", "paper": "B2", "n": 4, "q": "<p>Let $a$, $b$, $c$ be real numbers. Exactly two of the following three statements are true: \\[ a &lt; b, \\qquad b &lt; c, \\qquad a &lt; c . \\] Which of the following must be true?<\/p>", "opts": ["$a &lt; b$", "$b &lt; c$", "$a &lt; c$", "$b$ is the largest of the three numbers", "$a$ is the smallest of the three numbers"], "ans": "C", "sol": "<p>Which statement is the false one? It cannot be $a &lt; c$: if $a &lt; c$ were false then $c \\le a$, but the other two statements would then be true, giving $a &lt; b &lt; c \\le a$, impossible. So $a &lt; c$ is always among the two true statements, and must be true. Either of the other two can be the false one: $(a,b,c) = (1,3,2)$ makes $b &lt; c$ false, and $(2,1,3)$ makes $a &lt; b$ false. Those two examples also dispose of D and E.<\/p><p><\/p>", "tags": ["log"], "rating": 5.9}, {"id": "C1-12", "paper": "C1", "n": 12, "q": "<p>The function $f$ is continuous and satisfies $f(x+3)=f(x)$ for all real $x$, and $\\displaystyle\\int_0^3 f(x)\\,dx=2$. Find \\[ \\int_0^{675} f(3x+1)\\,dx . \\]<\/p>", "opts": ["$150$", "$225$", "$450$", "$900$", "$1350$", "it cannot be determined from the information given"], "ans": "C", "sol": "<p>Substitute $u=3x+1$: $dx=\\frac13du$, and the limits become $1$ and $2026$, so the integral is $\\frac13\\int_1^{2026}f(u)\\,du$. The interval $[1,2026]$ has length $2025=3\\times675$, exactly $675$ periods, and the integral of a periodic function over any interval of one period is the same, here $2$. So the integral is $\\frac13\\cdot675\\cdot2=450$. Option E forgets the $\\frac13$ from $dx$.<\/p><p><\/p>", "tags": ["sym", "arint"], "rating": 5.9}, {"id": "C2-19", "paper": "C2", "n": 19, "q": "<p>The function $f$ is continuous on the real numbers and satisfies $f(-x)=-f(x)$ for every $x$. Let $a>0$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$\\displaystyle\\int_{-a}^{a} f(x)\\,dx=0$<\/li><li>$\\displaystyle\\int_0^{a} f(x)\\,dx=\\int_0^{a} f(a-x)\\,dx$<\/li><li>$\\displaystyle\\int_{-a}^{a} x f(x)\\,dx=0$<\/li><li>$\\displaystyle\\int_0^{2a} f(x-a)\\,dx=0$<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I and IV only", "I, II and IV only", "I, II, III and IV", "II and III only"], "ans": "D", "sol": "<p>I: $f$ is odd. II: the substitution $x\\mapsto a-x$ works for any $f$. IV: with $u=x-a$ the integral is $\\int_{-a}^{a}f(u)\\,du=0$. III fails: $xf(x)$ is even, not odd, and $f(x)=x$ gives $\\int_{-a}^a x^2\\,dx>0$. So I, II and IV.<\/p><p><\/p>", "tags": ["fint", "sym"], "rating": 5.9}, {"id": "C1-2", "paper": "C1", "n": 2, "q": "<p>When the polynomial $p(x)$ is divided by $(x-1)^2$ the remainder is $2x+1$, and when $p(x)$ is divided by $x+1$ the remainder is $-3$. Let $r(x)$ be the remainder when $p(x)$ is divided by $(x-1)^2(x+1)$. Find $r(3)$.<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$\\dfrac{15}{2}$"], "ans": "E", "sol": "<p>The remainder has degree at most $2$. Since dividing $r(x)$ by $(x-1)^2$ must leave the same remainder as dividing $p(x)$ by $(x-1)^2$, we can write $r(x)=c(x-1)^2+2x+1$ for some constant $c$. The second condition says $r(-1)=p(-1)=-3$, so $4c-1=-3$ and $c=-\\frac12$. Then \\[ r(3)=-\\tfrac12\\cdot 4+7=5 . \\] The whole question is the choice of form for $r$: writing $r(x)=\\alpha x^2+\\beta x+\\gamma$ and using the derivative condition at $x=1$ also works, but takes three equations instead of one. Option F comes from expanding $-\\frac12(x-1)^2$ with a sign slip.<\/p><p><\/p>", "tags": ["poly"], "rating": 6.0}, {"id": "C2-14", "paper": "C2", "n": 14, "q": "<p>For a positive integer $n$, consider \\[ A:\\ 4\\mid n,\\qquad B:\\ 6\\mid n,\\qquad C:\\ 8\\mid n^2,\\qquad D:\\ 12\\mid n^2 . \\] Which one of the following is true?<\/p>", "opts": ["$A$ is equivalent to $C$, and $B$ is equivalent to $D$.", "$A$ is equivalent to $C$, but $B$ is not equivalent to $D$.", "$B$ is equivalent to $D$, but $A$ is not equivalent to $C$.", "Neither $A$ is equivalent to $C$, nor $B$ to $D$.", "$A$ is equivalent to $D$, and $B$ is equivalent to $C$."], "ans": "A", "sol": "<p>$C$: $8\\mid n^2$ forces $n$ even; writing $n=2m$, $8\\mid4m^2$ means $m$ is even, so $4\\mid n$. Conversely $4\\mid n$ gives $16\\mid n^2$. So $A\\Leftrightarrow C$. $D$: $12\\mid n^2$ means $4\\mid n^2$ and $3\\mid n^2$, that is $2\\mid n$ and $3\\mid n$, so $6\\mid n$; conversely $6\\mid n$ gives $36\\mid n^2$. So $B\\Leftrightarrow D$.<\/p><p><\/p>", "tags": ["ns", "mod"], "rating": 6.0}, {"id": "D1-5", "paper": "D1", "n": 5, "q": "<p>For how many real values of $a$ does the equation \\[x^3-(a+1)x^2+(a+1)x-1=0\\] have a repeated root?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "no values"], "ans": "B", "sol": "<p>The coefficients sum to zero, so $x=1$ is always a root, and $x^3-(a+1)x^2+(a+1)x-1=(x-1)(x^2-ax+1)$. A repeated root arises in two ways: the quadratic has a repeated root, which needs $a^2=4$, so $a=\\pm2$; or the quadratic has $1$ as a root, which needs $2-a=0$, so $a=2$ again. The two routes overlap, leaving exactly two values, $a=2$ and $a=-2$. Counting three is the trap.<\/p>", "tags": ["poly"], "rating": 6.0}, {"id": "D1-6", "paper": "D1", "n": 6, "q": "<p>How many solutions does the equation \\[\\tan x=2\\sin x\\] have in the interval $-360^\\circ\\le x\\le 360^\\circ$?<\/p>", "opts": ["$4$", "$5$", "$7$", "$8$", "$9$", "$11$"], "ans": "E", "sol": "<p>Write $\\tan x=\\frac{\\sin x}{\\cos x}$ (so $\\cos x\\neq0$) and factorise rather than divide: $\\sin x\\left(\\frac{1}{\\cos x}-2\\right)=0$. Either $\\sin x=0$, giving $x=-360^\\circ,-180^\\circ,0^\\circ,180^\\circ,360^\\circ$, or $\\cos x=\\tfrac12$, giving $x=\\pm60^\\circ,\\pm300^\\circ$. That is $5+4=9$ solutions, none with $\\cos x=0$. Dividing both sides by $\\sin x$ at the start loses five of them.<\/p>", "tags": ["trg"], "rating": 6.0}, {"id": "D2-5", "paper": "D2", "n": 5, "q": "<p>Which of the following statements are true for every integer $n$? <ol class=\"stmts\" type=\"I\"><li>$n^3-n$ is divisible by $6$<\/li><li>$n^5-n$ is divisible by $30$<\/li><li>$n^2+n+1$ is odd<\/li><li>$n^2-1$ is divisible by $8$<\/li><\/ol><\/p>", "opts": ["I only", "I and III only", "II and III only", "I, II and IV only", "I, II and III only", "I, II, III and IV"], "ans": "E", "sol": "<p>I: $n^3-n=(n-1)n(n+1)$ is a product of three consecutive integers, so divisible by $2$ and $3$. II: $n^5-n=n(n-1)(n+1)(n^2+1)$ contains $(n-1)n(n+1)$, so it is divisible by $6$; for $5$, check residues: if $n\\equiv0,\\pm1\\pmod5$ one of the first three factors is a multiple of $5$, and if $n\\equiv\\pm2$ then $n^2+1\\equiv5\\equiv0$. III: $n^2+n=n(n+1)$ is even, so $n^2+n+1$ is odd. IV fails for even $n$: $n=2$ gives $3$.<\/p>", "tags": ["mod"], "rating": 6.0}, {"id": "D2-6", "paper": "D2", "n": 6, "q": "<p>Real numbers $a$ and $b$ satisfy $a>b$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$a^2>b^2$<\/li><li>$a^3>b^3$<\/li><li>$\\dfrac1a&lt;\\dfrac1b$, provided $a$ and $b$ are non-zero<\/li><li>$2^a>2^b$<\/li><li>$a|a|>b|b|$<\/li><\/ol><\/p>", "opts": ["II only", "II and IV only", "II, IV and V only", "I, II and IV only", "II, III, IV and V", "all five"], "ans": "C", "sol": "<p>II, IV and V hold because $x^3$, $2^x$ and $x|x|$ are all increasing on the whole real line; $x|x|$ is $x^2$ for $x\\ge0$ and $-x^2$ for $x&lt;0$, and both pieces increase. I fails for $a=1$, $b=-2$. III fails for $a=1$, $b=-1$: then $\\tfrac1a=1$ is not less than $\\tfrac1b=-1$. Taking reciprocals reverses an inequality only when both numbers have the same sign.<\/p>", "tags": ["ineq"], "rating": 6.0}, {"id": "D2-7", "paper": "D2", "n": 7, "q": "<p>Which of the following are true for every $x$ with $0^\\circ&lt;x&lt;90^\\circ$? <ol class=\"stmts\" type=\"I\"><li>$\\sin x+\\cos x>1$<\/li><li>$\\sin^2x&lt;\\sin x$<\/li><li>$\\tan x>1$<\/li><li>$\\cos x&lt;\\dfrac{1}{\\cos x}$<\/li><\/ol><\/p>", "opts": ["I and II only", "II and IV only", "I and IV only", "I, III and IV only", "I, II, III and IV", "I, II and IV only"], "ans": "F", "sol": "<p>On this interval $0&lt;\\sin x&lt;1$ and $0&lt;\\cos x&lt;1$. I: $(\\sin x+\\cos x)^2=1+2\\sin x\\cos x>1$ and the sum is positive. II: multiply $\\sin x&lt;1$ by the positive number $\\sin x$. IV: multiply $\\cos x&lt;1$ by the positive number $\\frac{1}{\\cos x}$. III fails for any $x&lt;45^\\circ$.<\/p>", "tags": ["trg", "ineq"], "rating": 6.0}, {"id": "E1-5", "paper": "E1", "n": 5, "q": "<p>In the expansion of $(2+3x)^{10}$ in ascending powers of $x$, the coefficient of $x^k$ is greatest when $k$ equals<\/p>", "opts": ["$2$", "$3$", "$4$", "$5$", "$6$", "$7$"], "ans": "E", "sol": "<p>Let $c_k=\\binom{10}{k}2^{10-k}3^k$. Then $\\frac{c_{k+1}}{c_k}=\\frac{10-k}{k+1}\\cdot\\frac32$, which is at least $1$ exactly when $3(10-k)\\ge2(k+1)$, that is $k\\le5.6$. So the coefficients increase up to $c_6$ and decrease after it: the greatest is at $k=6$. The middle of the expansion, $k=5$, is where $\\binom{10}{k}$ peaks, but the factor $\\tfrac32$ pushes the peak one place right.<\/p>", "tags": ["bin"], "rating": 6.0}, {"id": "E1-6", "paper": "E1", "n": 6, "q": "<p>How many real solutions does the equation $2^x=3-x^2$ have?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$"], "ans": "B", "sol": "<p>Let $g(x)=2^x+x^2-3$. Then $g(1)=0$ exactly, $g(-1)=-\\tfrac32&lt;0$ and $g(-2)=\\tfrac54>0$, so there is a second root in $(-2,-1)$. There are no more, because $g$ is the sum of $2^x$ and $x^2$, both of which curve upwards, so the graph of $g$ is a single valley and crosses any horizontal line at most twice. Exactly two solutions. The root $x=1$ is easy to spot; the negative one is the one people miss.<\/p>", "tags": ["root", "exp"], "rating": 6.0}, {"id": "E2-7", "paper": "E2", "n": 7, "q": "<p>A function $f$ satisfies $f'(x)=(x-1)^2(x-3)$ for all $x$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$f$ has exactly one local minimum.<\/li><li>$f(0)>f(2)$<\/li><li>$f$ has a local maximum at $x=1$.<\/li><li>$f(4)>f(3)$<\/li><\/ol><\/p>", "opts": ["I only", "I and IV only", "I, II and IV only", "I, II, III and IV", "II and III only", "I and III only"], "ans": "C", "sol": "<p>$(x-1)^2\\ge0$, so $f'$ has the sign of $x-3$, except that it is zero at $x=1$. So $f$ decreases on $(-\\infty,3]$, pausing at $x=1$ without turning, and increases on $[3,\\infty)$. I: the only turning point is the minimum at $x=3$. II: $f$ decreases from $0$ to $2$. III is false: $x=1$ is a stationary point of inflection. IV: $f$ increases after $3$.<\/p>", "tags": ["diff"], "rating": 6.0}, {"id": "E2-8", "paper": "E2", "n": 8, "q": "<p>A student proves: <em>for all real $x$ and $y$, if $x>y$ then $x^2>y^2$<\/em>.<\/p><p><br> (I) Multiplying $x>y$ by $x$ gives $x^2>xy$.<br> (II) Multiplying $x>y$ by $y$ gives $xy>y^2$.<br> (III) Combining, $x^2>xy>y^2$.<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The proof is valid.", "Only line II is invalid, and the claim is true.", "Only line III is invalid.", "Lines I and II are invalid, but the claim is true.", "Line I needs $x>0$ and line II needs $y>0$; the claim is false.", "The proof is valid when $x,y\\ge0$, and the claim is true for all real $x,y$."], "ans": "E", "sol": "<p>Multiplying an inequality by a number keeps its direction only if that number is positive, so line I needs $x>0$ and line II needs $y>0$. The claim is false: $x=1$, $y=-2$ gives $1&lt;4$. The argument does prove the claim for positive $x$ and $y$, but that is not what was asserted.<\/p>", "tags": ["prf", "ineq"], "rating": 6.0}, {"id": "F1-5", "paper": "F1", "n": 5, "q": "<p>Let $r(x)$ be the remainder when $x^{100}$ is divided by $x^2-3x+2$. Find $r(0)$.<\/p>", "opts": ["$2^{100}-2$", "$1$", "$2^{100}-1$", "$2-2^{100}$", "$0$", "$2^{99}$"], "ans": "D", "sol": "<p>$x^{100}=(x-1)(x-2)q(x)+ax+b$. Putting $x=1$ and $x=2$ gives $a+b=1$ and $2a+b=2^{100}$, so $a=2^{100}-1$ and $b=2-2^{100}$. Then $r(0)=b=2-2^{100}$. The divisor's roots do all the work; long division is hopeless here.<\/p>", "tags": ["poly"], "rating": 6.0}, {"id": "F1-6", "paper": "F1", "n": 6, "q": "<p>For how many real values of $k$ does the equation $x^3-3x^2=k$ have exactly two distinct real solutions?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$", "infinitely many"], "ans": "C", "sol": "<p>The graph of $y=x^3-3x^2$ has a local maximum at $(0,0)$ and a local minimum at $(2,-4)$. A horizontal line $y=k$ meets it in exactly two points only when it is tangent at a turning point, that is $k=0$ (roots $0,0,3$) or $k=-4$ (roots $2,2,-1$). For $-4&lt;k&lt;0$ there are three solutions, and otherwise one. So two values of $k$.<\/p>", "tags": ["root", "poly"], "rating": 6.0}, {"id": "F2-4", "paper": "F2", "n": 4, "q": "<p>Let $S$ be the statement &ldquo;if $n$ is divisible by $4$, then $n^2$ is divisible by $8$&rdquo;, where $n$ is a positive integer. How many of the following are true: $S$, its converse, its inverse, and its contrapositive?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$"], "ans": "E", "sol": "<p>$S$ is true, since $4\\mid n$ gives $16\\mid n^2$, and so is its contrapositive. The converse, &ldquo;if $8\\mid n^2$ then $4\\mid n$&rdquo;, is also true: $8\\mid n^2$ forces $n$ even, and writing $n=2m$, $8\\mid4m^2$ forces $m$ even. The inverse is the contrapositive of the converse, so it is true as well. All four hold. The instinct that &ldquo;the converse is usually false&rdquo; is exactly what this question tests.<\/p>", "tags": ["log", "mod"], "rating": 6.0}, {"id": "F2-5", "paper": "F2", "n": 5, "q": "<p>Which of the following conditions on the real number $x$ are sufficient for $x^3&lt;x$? <ol class=\"stmts\" type=\"I\"><li>$0&lt;x&lt;1$<\/li><li>$x&lt;1$<\/li><li>$x^2&lt;1$<\/li><li>$x&lt;-1$<\/li><\/ol><\/p>", "opts": ["I only", "I and III only", "IV only", "I and IV only", "I, III and IV only", "II only"], "ans": "D", "sol": "<p>$x^3-x=x(x-1)(x+1)&lt;0$ exactly when $x&lt;-1$ or $0&lt;x&lt;1$. So I and IV are sufficient. II and III both allow $-1&lt;x&lt;0$, where for instance $x=-\\tfrac12$ gives $x^3=-\\tfrac18>-\\tfrac12$.<\/p>", "tags": ["ns", "ineq"], "rating": 6.0}, {"id": "B1-16", "paper": "B1", "n": 16, "q": "<p>The curve $y = x^4 - 4x^3 + ax^2$, where $a$ is a real constant, has exactly one stationary point. Find the complete set of possible values of $a$.<\/p>", "opts": ["$a > \\dfrac92$", "$a \\ge \\dfrac92$", "$a &lt; \\dfrac92$", "$0 &lt; a &lt; \\dfrac92$", "$a > 0$", "$a \\ge 0$"], "ans": "A", "sol": "<p>$y' = 4x^3 - 12x^2 + 2ax = 2x(2x^2 - 6x + a)$. There is always the stationary point $x = 0$, so we need $2x^2 - 6x + a = 0$ to have no real roots: $36 - 8a &lt; 0$, i.e.\\ $a > \\tfrac92$. The boundary case $a = \\tfrac92$ gives the double root $x = \\tfrac32$, which is still a second stationary point (a stationary point of inflection), so option B is wrong. The factor $2x$ is the other trap: $x = 0$ is a stationary point for every $a$, so \"no real roots\" applies to the quadratic factor only.<\/p><p><\/p>", "tags": ["root"], "rating": 6.1}, {"id": "C2-8", "paper": "C2", "n": 8, "q": "<p>For a real number $x$, how many of the following statements are true for every real $x$? <ol class=\"stmts\" type=\"I\"><li>$x>2$ if $x^2>4$.<\/li><li>$x>2$ only if $x^2>4$.<\/li><li>$x^2>4$ if and only if $|x|>2$.<\/li><li>$x^3>8$ only if $x>2$.<\/li><li>$x^2>4$ if $x^3>8$.<\/li><li>$x^2>4$ only if $x^3>8$.<\/li><\/ol><\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "D", "sol": "<p>&ldquo;$A$ if $B$&rdquo; means $B\\Rightarrow A$; &ldquo;$A$ only if $B$&rdquo; means $A\\Rightarrow B$. I is $x^2>4\\Rightarrow x>2$: false at $x=-3$. II is $x>2\\Rightarrow x^2>4$: true. III is true. IV is $x^3>8\\Rightarrow x>2$: true, since cubing is increasing. V is $x^3>8\\Rightarrow x^2>4$: true, via $x>2$. VI is $x^2>4\\Rightarrow x^3>8$: false at $x=-3$. Four are true.<\/p><p><\/p>", "tags": ["log", "ns"], "rating": 6.1}, {"id": "B1-14", "paper": "B1", "n": 14, "q": "<p>A sequence is defined by $a_1 = 3$ and \\[ a_{n+1} = \\frac{a_n - 1}{a_n + 1} \\qquad (n \\ge 1). \\] Find the value of the product $a_1 a_2 a_3 \\cdots a_{2026}$.<\/p>", "opts": ["$-2$", "$-\\dfrac12$", "$1$", "$\\dfrac32$", "$3$", "$\\dfrac94$"], "ans": "D", "sol": "<p>Compute a few terms: $a_1 = 3$, $a_2 = \\tfrac12$, $a_3 = -\\tfrac13$, $a_4 = -2$, $a_5 = 3$. The sequence has period $4$. (Structurally, if $g(x) = \\tfrac{x-1}{x+1}$ then $g(g(x)) = -\\tfrac1x$, so $g$ has order $4$.) The product over one period is $3\\cdot\\tfrac12\\cdot(-\\tfrac13)\\cdot(-2) = 1$. Since $2026 = 4\\cdot 506 + 2$, the product is $a_1 a_2 = \\tfrac32$.<\/p><p><\/p>", "tags": ["ser", "inv"], "rating": 6.2}, {"id": "C1-16", "paper": "C1", "n": 16, "q": "<p>The continuous function $f$ satisfies \\[ f(x)=x^2+x\\int_0^1 t\\,f(t)\\,dt\\qquad\\text{for all } x . \\] Find $\\displaystyle\\int_0^1 f(x)\\,dx$.<\/p>", "opts": ["$\\dfrac{11}{24}$", "$\\dfrac{25}{48}$", "$\\dfrac{13}{24}$", "$\\dfrac{7}{12}$", "$\\dfrac58$", "$\\dfrac23$"], "ans": "B", "sol": "<p>The integral $\\int_0^1 tf(t)\\,dt$ is just a number; call it $B$. Then $f(x)=x^2+Bx$, and substituting back, \\[ B=\\int_0^1 t(t^2+Bt)\\,dt=\\tfrac14+\\tfrac B3, \\] so $B=\\frac38$. Hence $\\int_0^1 f=\\frac13+\\frac B2=\\frac13+\\frac3{16}=\\frac{25}{48}$. Option A comes from stopping at $B=\\frac14$, having dropped the self-referential term.<\/p><p><\/p>", "tags": ["fint"], "rating": 6.2}, {"id": "C2-4", "paper": "C2", "n": 4, "q": "<p>A function $f$ from the real numbers to the real numbers is called <em>increasing<\/em> if, for all real $x$ and $y$, if $x&lt;y$ then $f(x)&lt;f(y)$. Which one of the following is equivalent to &ldquo;$f$ is not increasing&rdquo;?<\/p>", "opts": ["For all real $x$ and $y$, if $x&lt;y$ then $f(x)\\ge f(y)$.", "There exist real $x$ and $y$ such that, if $x&lt;y$ then $f(x)\\ge f(y)$.", "There exist real $x$ and $y$ with $x\\ge y$ and $f(x)\\ge f(y)$.", "For all real $x$ and $y$, $x\\ge y$ or $f(x)\\ge f(y)$.", "There exist real $x$ and $y$ with $x&lt;y$ or $f(x)\\ge f(y)$.", "There exist real $x$ and $y$ with $x&lt;y$ and $f(x)\\ge f(y)$."], "ans": "F", "sol": "<p>&ldquo;Increasing&rdquo; is: for all $x,y$, (if $x&lt;y$ then $f(x)&lt;f(y)$). Negating swaps the quantifier and negates the implication, and the negation of &ldquo;if $A$ then $B$&rdquo; is &ldquo;$A$ and not $B$&rdquo;: there exist $x,y$ with $x&lt;y$ and $f(x)\\ge f(y)$. Option B is the classic mistake of negating only the conclusion. It is true for every function whatsoever, since choosing $x=y$ makes the hypothesis $x&lt;y$ false and the implication vacuously true.<\/p><p><\/p>", "tags": ["log"], "rating": 6.2}, {"id": "D2-8", "paper": "D2", "n": 8, "q": "<p>Five integers have the property that the sum of any three of them is even. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>All five integers are even.<\/li><li>The sum of all five integers is even.<\/li><li>The sum of any two of the integers is even.<\/li><li>Each of the integers is divisible by 4.<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "II and III only", "I, II and III only", "I, II, III and IV", "none of them"], "ans": "D", "sol": "<p>Take any two of the numbers, $p$ and $q$, and two others $r$ and $s$. Both $p+r+s$ and $q+r+s$ are even, so their difference $p-q$ is even: all five have the same parity. If all were odd, three of them would have an odd sum. So all five are even, and I, II and III follow. IV fails: $2,2,2,2,2$ has the property.<\/p>", "tags": ["mod"], "rating": 6.2}, {"id": "E1-7", "paper": "E1", "n": 7, "q": "<p>A geometric series has sum to infinity $12$, and the series formed by squaring each of its terms has sum to infinity $48$. Find the sum to infinity of the series formed by cubing each term.<\/p>", "opts": ["$144$", "$216$", "$288$", "$432$", "$\\dfrac{1728}{5}$", "$\\dfrac{1728}{7}$"], "ans": "F", "sol": "<p>$\\frac{a}{1-r}=12$ and $\\frac{a^2}{1-r^2}=48$. Divide the second by the first: $\\frac{a}{1+r}=4$. So $a=12(1-r)=4(1+r)$, giving $r=\\tfrac12$ and $a=6$. The cubes form a geometric series with first term $216$ and ratio $\\tfrac18$, with sum $\\frac{216}{7/8}=\\frac{1728}{7}$. Option E comes from using $1-r^3=\\tfrac58$.<\/p>", "tags": ["ser"], "rating": 6.2}, {"id": "E2-10", "paper": "E2", "n": 10, "q": "<p>How many of the following statements about integers $n$ are true? <ol class=\"stmts\" type=\"I\"><li>$n$ is even only if $n^2$ is even.<\/li><li>$n^2$ is divisible by $9$ unless $n$ is not divisible by $3$.<\/li><li>$n$ is prime only if $n$ is odd.<\/li><li>$n$ is odd if $n^2+1$ is even.<\/li><\/ol><\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$"], "ans": "D", "sol": "<p>I: if $n$ is even then $n^2$ is even; true. II: &ldquo;$P$ unless $Q$&rdquo; means &ldquo;if not $Q$ then $P$&rdquo;, so this reads: if $n$ is divisible by $3$ then $9\\mid n^2$; true. III: if $n$ is prime then $n$ is odd; false for $n=2$. IV: if $n^2+1$ is even then $n^2$ is odd, so $n$ is odd; true. Three are true.<\/p>", "tags": ["log", "mod"], "rating": 6.2}, {"id": "E2-9", "paper": "E2", "n": 9, "q": "<p>A student proves that $\\log_2 3$ is irrational.<\/p><p><br> (I) Suppose $\\log_2 3=\\dfrac pq$, where $p$ and $q$ are integers and $q\\neq0$.<br> (II) Since $\\log_23>0$, we may take $p$ and $q$ to be positive.<br> (III) Then $2^{p/q}=3$, so $2^p=3^q$.<br> (IV) But $2^p$ is even and $3^q$ is odd, a contradiction.<\/p><p><br> If line II were deleted, which line would no longer be justified?<\/p>", "opts": ["I", "III", "IV", "none: line II is unnecessary", "both III and IV"], "ans": "C", "sol": "<p>Line III is fine for any integers: raise $2^{p/q}=3$ to the power $q$. Line IV uses that $2^p$ is an even integer and $3^q$ an odd integer, which needs $p\\ge1$ and $q\\ge1$. With negative exponents they are fractions, and &ldquo;even&rdquo; and &ldquo;odd&rdquo; mean nothing. Line II is what licenses line IV.<\/p>", "tags": ["prf", "exp"], "rating": 6.2}, {"id": "F1-7", "paper": "F1", "n": 7, "q": "<p>Find the total measure, in degrees, of the set of $x$ in $0^\\circ\\le x\\le360^\\circ$ for which \\[2\\cos^2x>3\\sin x .\\]<\/p>", "opts": ["$60^\\circ$", "$120^\\circ$", "$180^\\circ$", "$240^\\circ$", "$300^\\circ$", "$330^\\circ$"], "ans": "D", "sol": "<p>With $s=\\sin x$: $2-2s^2>3s$, that is $2s^2+3s-2&lt;0$, or $(2s-1)(s+2)&lt;0$. Since $s+2>0$ always, this is $\\sin x&lt;\\tfrac12$. That fails only on $[30^\\circ,150^\\circ]$, of measure $120^\\circ$, so the solution set has measure $360^\\circ-120^\\circ=240^\\circ$.<\/p>", "tags": ["trg", "ineq"], "rating": 6.2}, {"id": "F2-6", "paper": "F2", "n": 6, "q": "<p>Call a pair $(a,b)$ of positive integers <em>friendly<\/em> if $a+b$ divides $ab$. Which of the following statements are true? <ol class=\"stmts\" type=\"I\"><li>If $(a,b)$ is friendly, then so is $(ka,kb)$ for every positive integer $k$.<\/li><li>$(a,a)$ is friendly if and only if $a$ is even.<\/li><li>$(1,b)$ is never friendly.<\/li><li>If $(a,b)$ is friendly, then one of $a$ and $b$ divides the other.<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I, II, III and IV", "I, II and III only", "II and III only", "I and IV only"], "ans": "D", "sol": "<p>I: $\\frac{k^2ab}{k(a+b)}=k\\cdot\\frac{ab}{a+b}$ is an integer. II: $2a\\mid a^2$ exactly when $2\\mid a$. III: $b+1\\mid b$ is impossible for positive $b$, since $b+1>b$. IV fails: $(10,15)$ has $25\\mid150$, but neither number divides the other.<\/p>", "tags": ["mod"], "rating": 6.2}, {"id": "F2-7", "paper": "F2", "n": 7, "q": "<p>A student proves that there are infinitely many primes: &ldquo;Suppose there are finitely many, $p_1,p_2,\\dots,p_k$. Let $N=p_1p_2\\cdots p_k+1$. None of the $p_i$ divides $N$. Hence $N$ is prime; but $N$ is larger than every $p_i$, a contradiction.&rdquo; Which of the following is correct?<\/p>", "opts": ["The proof is correct as written.", "$N$ need not be prime, but it has a prime factor not in the list, so the proof is repaired by changing that step.", "$N$ need not be prime, and the argument cannot be repaired.", "The error is that some $p_i$ may divide $N$.", "The argument shows only that there are more than $k$ primes for one particular $k$.", "The assumption that the primes can be listed is itself invalid."], "ans": "B", "sol": "<p>&ldquo;Hence $N$ is prime&rdquo; does not follow: $2\\cdot3\\cdot5\\cdot7\\cdot11\\cdot13+1=30031=59\\cdot509$. What is true is that $N>1$ has some prime factor, and no $p_i$ divides $N$, so that factor is a prime missing from the list. That still contradicts the assumption, so the proof survives once that one step is corrected.<\/p>", "tags": ["prf", "mod"], "rating": 6.2}, {"id": "B2-5", "paper": "B2", "n": 5, "q": "<p>For which positive integers $n$ is it possible to fill an $n \\times n$ grid with integers so that the sum of the entries in every row is odd and the sum of the entries in every column is even?<\/p>", "opts": ["Every $n \\ge 1$", "Even $n$ only", "Odd $n$ only", "No $n$", "Every $n \\ge 2$"], "ans": "B", "sol": "<p>Add up every entry in the grid in two ways. Summing the rows gives a sum of $n$ odd numbers, which is odd exactly when $n$ is odd; summing the columns gives a sum of $n$ even numbers, which is always even. So $n$ odd is impossible. For $n$ even, put $1$ in every cell of the first column and $0$ everywhere else: every row sums to $1$ and the columns sum to $n$ (even) and $0$. The answer is even $n$ only. Counting one quantity two ways is the whole method.<\/p><p><\/p>", "tags": ["col", "two"], "rating": 6.3}, {"id": "C1-19", "paper": "C1", "n": 19, "q": "<p>The tangent to the curve $y=x^3$ at the point $P(1,1)$ meets the curve again at $Q$. Find the area of the region enclosed between the curve and the line segment $PQ$.<\/p>", "opts": ["$\\dfrac94$", "$\\dfrac{27}{8}$", "$\\dfrac{27}{4}$", "$8$", "$\\dfrac{27}{2}$", "$\\dfrac{81}{4}$"], "ans": "C", "sol": "<p>The tangent at $P$ is $y=3x-2$, and $x^3-(3x-2)=x^3-3x+2=(x-1)^2(x+2)$, where the double factor is forced by tangency. So $Q$ has $x=-2$, and the curve lies above the tangent on $(-2,1)$. With $u=x-1$, \\[ \\int_{-2}^{1}(x-1)^2(x+2)\\,dx=\\int_{-3}^{0}(u^3+3u^2)\\,du=0-\\left(\\tfrac{81}4-27\\right)=\\tfrac{27}{4} . \\] Knowing that the factorisation must contain $(x-1)^2$ saves the polynomial division, and the shift $u=x-1$ saves expanding.<\/p><p><\/p>", "tags": ["arint", "poly"], "rating": 6.3}, {"id": "D1-7", "paper": "D1", "n": 7, "q": "<p>Find the complete set of real values of $x$ for which \\[\\log_2 x+\\log_x 16&lt;5 .\\]<\/p>", "opts": ["$0&lt;x&lt;1$ or $2&lt;x&lt;16$", "$2&lt;x&lt;16$", "$x&lt;1$ or $2&lt;x&lt;16$", "$1&lt;x&lt;16$", "$0&lt;x&lt;2$ or $x>16$", "$0&lt;x&lt;\\tfrac12$ or $2&lt;x&lt;16$"], "ans": "A", "sol": "<p>We need $x>0$ and $x\\neq1$. Put $t=\\log_2x$, so $\\log_x16=\\frac{4}{t}$ and the inequality is $t+\\frac4t&lt;5$. Do not multiply through by $t$ without its sign. If $t>0$, it becomes $t^2-5t+4&lt;0$, so $1&lt;t&lt;4$, that is $2&lt;x&lt;16$. If $t&lt;0$, multiplying reverses it: $t^2-5t+4>0$, which holds for every negative $t$, so every $0&lt;x&lt;1$ works. The solution set is $0&lt;x&lt;1$ or $2&lt;x&lt;16$.<\/p>", "tags": ["exp", "ineq"], "rating": 6.3}, {"id": "D1-8", "paper": "D1", "n": 8, "q": "<p>Find the complete set of real values of $x$ for which \\[\\frac{2x}{x-1}\\ge x .\\]<\/p>", "opts": ["$0\\le x\\le 3$", "$1&lt;x\\le3$", "$x\\le0$ or $x\\ge3$", "$x\\le0$ or $1\\le x\\le3$", "$x&lt;1$ or $x\\ge3$", "$x\\le0$ or $1&lt;x\\le3$"], "ans": "F", "sol": "<p>Move everything to one side instead of multiplying by $x-1$, whose sign is unknown: \\[\\frac{2x}{x-1}-x=\\frac{3x-x^2}{x-1}=\\frac{x(3-x)}{x-1}\\ge0 .\\] The critical values are $0$, $1$ and $3$. The expression is positive for $x&lt;0$, negative on $(0,1)$, positive on $(1,3)$ and negative for $x>3$; it is zero at $x=0$ and $x=3$ and undefined at $x=1$. So the solution set is $x\\le0$ or $1&lt;x\\le3$.<\/p>", "tags": ["ineq"], "rating": 6.3}, {"id": "D2-9", "paper": "D2", "n": 9, "q": "<p>Consider the statement: <em>if $f$ and $g$ are both decreasing on the real line, then the product $fg$ is increasing on the real line.<\/em> How many of the following pairs are counterexamples to this statement? <ol class=\"stmts\" type=\"I\"><li>$f(x)=e^{-x}$, $g(x)=e^{-x}$<\/li><li>$f(x)=-e^{x}$, $g(x)=-e^{x}$<\/li><li>$f(x)=-x$, $g(x)=-x$<\/li><li>$f(x)=-x^3$, $g(x)=-e^{x}$<\/li><\/ol><\/p>", "opts": ["$1$", "$2$", "$3$", "$4$"], "ans": "C", "sol": "<p>Every pair consists of decreasing functions, so each is a counterexample exactly when $fg$ is not increasing. I: $e^{-2x}$ decreases, so it is a counterexample. II: $e^{2x}$ increases, so it is not. III: $x^2$ decreases for $x&lt;0$, so it is a counterexample. IV: $x^3e^x$ has derivative $x^2(x+3)e^x$, negative for $x&lt;-3$, so it is a counterexample. That makes three.<\/p>", "tags": ["log"], "rating": 6.3}, {"id": "E2-11", "paper": "E2", "n": 11, "q": "<p>Which of the following is the largest? (All angles are in radians.)<\/p>", "opts": ["$\\sin1$", "$\\sin2$", "$\\sin3$", "$\\cos1$", "$\\cos2$"], "ans": "B", "sol": "<p>$\\cos2&lt;0$, since $2>\\frac\\pi2$. $\\sin3=\\sin(\\pi-3)$, which is the sine of a small angle, about $0.14$. $\\cos1=\\sin\\left(\\frac\\pi2-1\\right)$, about $\\sin0.57$. $\\sin2=\\sin(\\pi-2)$, about $\\sin1.14$. Sine is increasing on $\\left[0,\\frac\\pi2\\right]$ and $1.14>1>0.57>0.14$, so $\\sin2$ is the largest. Reflecting every angle into $\\left[0,\\frac\\pi2\\right]$ turns the comparison into one of angles.<\/p>", "tags": ["trg", "ineq"], "rating": 6.3}, {"id": "B1-19", "paper": "B1", "n": 19, "q": "<p>A function $f$ satisfies \\[ \\int_0^2 f(2x)\\,dx = 3, \\qquad \\int_1^3 f(x+1)\\,dx = 5, \\qquad \\int_0^1 f(3-3x)\\,dx = 2. \\] Find the value of $\\displaystyle\\int_3^4 f(x)\\,dx$.<\/p>", "opts": ["$-1$", "$0$", "$1$", "$2$", "$5$", "$6$", "cannot be determined from the information given"], "ans": "B", "sol": "<p>Substitute in each integral. In the first, $u = 2x$ gives $\\tfrac12\\int_0^4 f = 3$, so $\\int_0^4 f = 6$. In the second, $u = x+1$ gives $\\int_2^4 f = 5$. In the third, $u = 3 - 3x$ reverses the limits and contributes a factor $\\tfrac13$, giving $\\tfrac13\\int_0^3 f = 2$, so $\\int_0^3 f = 6$. Then \\[ \\int_3^4 f = \\int_0^4 f - \\int_0^3 f = 6 - 6 = 0. \\] The information is enough, so option G is wrong; the value $5$ in option E is $\\int_2^4 f$, read off carelessly.<\/p><p><\/p>", "tags": ["arint", "sym"], "rating": 6.4}, {"id": "C1-10", "paper": "C1", "n": 10, "q": "<p>The two tangents from the origin to the circle $(x-4)^2+(y-3)^2=4$ meet at an acute angle $\\theta$. Find $\\tan\\theta$.<\/p>", "opts": ["$\\dfrac25$", "$\\dfrac{2}{\\sqrt{21}}$", "$\\dfrac{12}{17}$", "$\\dfrac{4\\sqrt{21}}{21}$", "$\\dfrac{4\\sqrt{21}}{17}$", "$\\dfrac{\\sqrt{21}}{2}$"], "ans": "E", "sol": "<p>The centre $C=(4,3)$ is at distance $5$ from the origin $O$ and the radius is $2$. Each tangent makes an angle $\\alpha$ with $OC$ where $\\sin\\alpha=\\frac25$, so $\\tan\\alpha=\\frac{2}{\\sqrt{21}}$, and the angle between the tangents is $\\theta=2\\alpha$, which is acute since $\\alpha&lt;\\frac\\pi4$. Then \\[ \\tan\\theta=\\frac{2\\tan\\alpha}{1-\\tan^2\\alpha}=\\frac{4/\\sqrt{21}}{17/21}=\\frac{4\\sqrt{21}}{17} . \\] The coordinate route, requiring $y=mx$ to be at distance $2$ from $C$, gives $12m^2-24m+5=0$ and reaches the same value through $\\frac{m_1-m_2}{1+m_1m_2}$, with more work. Option B is $\\tan\\alpha$, the half-angle.<\/p><p><\/p>", "tags": ["circ", "trg"], "rating": 6.4}, {"id": "C2-11", "paper": "C2", "n": 11, "q": "<p>A student solves the inequality $\\sin x\\cos x>\\cos^2x$ for $0\\le x&lt;2\\pi$ as follows.<\/p><p><br> &ldquo;When $\\cos x=0$, both sides are $0$, so the inequality fails. Otherwise $\\cos^2x>0$, so I can divide by it without changing the direction of the inequality, giving $\\tan x>1$. Hence the solution set is $\\tfrac{\\pi}{4}&lt;x&lt;\\tfrac{\\pi}{2}$ together with $\\tfrac{5\\pi}{4}&lt;x&lt;\\tfrac{3\\pi}{2}$.&rdquo;<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The final answer is correct and the argument is valid.", "The final answer is wrong, because dividing by $\\cos^2x$ may reverse the inequality.", "The final answer is wrong, because solutions with $\\cos x&lt;0$ have been lost.", "The final answer is wrong, because it includes values where $\\cos x=0$.", "The final answer is correct, but the argument is invalid.", "The final answer is wrong; the solution set is $\\tfrac{\\pi}{4}&lt;x&lt;\\tfrac{5\\pi}{4}$."], "ans": "A", "sol": "<p>The student handles $\\cos x=0$ separately, where the inequality reads $0>0$ and fails, and elsewhere divides by $\\cos^2x>0$, which is legitimate and preserves the direction. So the original inequality is equivalent to $\\tan x>1$ with $\\cos x\\ne0$, whose solution set in $[0,2\\pi)$ is exactly the one given. Compare this with dividing $\\sin x>\\cos x$ by $\\cos x$, where the sign of $\\cos x$ matters: the difference is that $\\cos^2x$ is never negative.<\/p><p><\/p>", "tags": ["prf", "trg"], "rating": 6.4}, {"id": "D1-9", "paper": "D1", "n": 9, "q": "<p>A triangle has sides of length $x$, $x+1$ and $x+2$, and one of its angles is $120^\\circ$. Find its area.<\/p>", "opts": ["$\\dfrac{15\\sqrt3}{16}$", "$\\dfrac{15\\sqrt3}{8}$", "$\\dfrac{3\\sqrt3}{4}$", "$\\dfrac{15}{8}$", "$\\dfrac{35\\sqrt3}{16}$", "$\\dfrac{5\\sqrt3}{4}$"], "ans": "A", "sol": "<p>The $120^\\circ$ angle is the largest angle, so it faces the longest side $x+2$. The cosine rule gives \\[(x+2)^2=x^2+(x+1)^2-2x(x+1)\\cos120^\\circ=3x^2+3x+1,\\] so $2x^2-x-3=0$ and $x=\\tfrac32$. The area is $\\tfrac12\\cdot\\tfrac32\\cdot\\tfrac52\\cdot\\sin120^\\circ=\\frac{15\\sqrt3}{16}$.<\/p>", "tags": ["trg"], "rating": 6.4}, {"id": "D2-10", "paper": "D2", "n": 10, "q": "<p>A triangle has sides $a\\le b\\le c$, with the angle $C$ opposite $c$. Which of the following conditions is sufficient for the triangle to be acute-angled? <ol class=\"stmts\" type=\"I\"><li>$C&lt;90^\\circ$<\/li><li>$a^2+b^2>c^2$<\/li><li>$a=b=c$<\/li><li>$b^2+c^2>a^2$<\/li><\/ol><\/p>", "opts": ["I, II and III only", "I and II only", "III only", "II and IV only", "I, II, III and IV", "II only"], "ans": "A", "sol": "<p>Since $c$ is the longest side, $C$ is the largest angle, so the triangle is acute exactly when $C&lt;90^\\circ$, which by the cosine rule is exactly $a^2+b^2>c^2$. So I and II are sufficient, and so is III, since an equilateral triangle is acute. IV holds for every triangle with $a$ as the shortest side, including obtuse ones such as sides $3,4,6$, so it is not sufficient.<\/p>", "tags": ["ns", "trg"], "rating": 6.4}, {"id": "E1-8", "paper": "E1", "n": 8, "q": "<p>An angle $x$ satisfies $0^\\circ&lt;x&lt;90^\\circ$ and $\\sin x+\\cos x=\\tfrac75$. Find the sum of all possible values of $\\tan x$.<\/p>", "opts": ["$\\dfrac34$", "$\\dfrac43$", "$\\dfrac{25}{12}$", "$\\dfrac75$", "$\\dfrac{12}{7}$", "$\\dfrac{24}{7}$"], "ans": "C", "sol": "<p>Squaring gives $1+2\\sin x\\cos x=\\tfrac{49}{25}$, so $\\sin x\\cos x=\\tfrac{12}{25}$. Then $\\sin x$ and $\\cos x$ are the roots of $t^2-\\tfrac75t+\\tfrac{12}{25}=0$, namely $\\tfrac35$ and $\\tfrac45$, in either order. Both orders give angles in the first quadrant, so $\\tan x=\\tfrac34$ or $\\tfrac43$, and the sum is $\\tfrac{25}{12}$. The trap is to find one value and stop.<\/p>", "tags": ["trg", "vie"], "rating": 6.4}, {"id": "E1-9", "paper": "E1", "n": 9, "q": "<p>Find the total area of the regions enclosed between the curves $y=x^3$ and $y=4x$.<\/p>", "opts": ["$2$", "$4$", "$6$", "$8$", "$16$", "$32$"], "ans": "D", "sol": "<p>The curves meet where $x^3=4x$, at $x=-2,0,2$. By the odd symmetry of both curves the two regions have equal area, and the one for $0\\le x\\le2$ is $\\int_0^2(4x-x^3)\\,dx=8-4=4$. The total is $8$. Integrating $4x-x^3$ from $-2$ to $2$ gives $0$, the signed cancellation that the word &ldquo;total&rdquo; warns against.<\/p>", "tags": ["arint"], "rating": 6.4}, {"id": "E2-12", "paper": "E2", "n": 12, "q": "<p>In triangle $ABC$, which of the following conditions guarantee that the triangle is isosceles? <ol class=\"stmts\" type=\"I\"><li>$\\sin A=\\sin B$<\/li><li>$\\cos A=\\cos B$<\/li><li>$\\tan A=\\tan B$<\/li><li>$\\sin 2A=\\sin 2B$<\/li><\/ol><\/p>", "opts": ["I only", "II only", "I and II only", "I, II and III only", "I, II, III and IV", "II and III only"], "ans": "D", "sol": "<p>I: $\\sin A=\\sin B$ means $A=B$ or $A+B=180^\\circ$, and the second is impossible in a triangle, so $A=B$. II: cosine is one-to-one on $(0^\\circ,180^\\circ)$. III: $\\tan A=\\tan B$ means $A=B$ or they differ by $180^\\circ$, which is impossible. IV allows $2A+2B=180^\\circ$, a right angle at $C$ with $A\\neq B$: the $3,4,5$ triangle satisfies it and is not isosceles.<\/p>", "tags": ["trg"], "rating": 6.4}, {"id": "F1-8", "paper": "F1", "n": 8, "q": "<p>The equation $x^2+(k-3)x+k=0$ has real roots $\\alpha$ and $\\beta$ with $\\alpha^2+\\beta^2=7$. Find all possible values of $k$.<\/p>", "opts": ["$k=4-\\sqrt{14}$ only", "$k=4+\\sqrt{14}$ only", "$k=4\\pm\\sqrt{14}$", "$k=1$ or $k=9$", "there are no such $k$", "$k=4-\\sqrt7$ only"], "ans": "A", "sol": "<p>$\\alpha^2+\\beta^2=(\\alpha+\\beta)^2-2\\alpha\\beta=(3-k)^2-2k=7$ gives $k^2-8k+2=0$, so $k=4\\pm\\sqrt{14}$. But the roots must be real: $(k-3)^2-4k\\ge0$, that is $k\\le1$ or $k\\ge9$. Now $4-\\sqrt{14}\\approx0.26$ qualifies and $4+\\sqrt{14}\\approx7.74$ does not; there the formula still gives $7$, but for a pair of complex roots. So $k=4-\\sqrt{14}$ only.<\/p>", "tags": ["quad", "vie"], "rating": 6.4}, {"id": "F1-9", "paper": "F1", "n": 9, "q": "<p>Find the complete set of real values of $x$ for which \\[\\log_{1/2}\\left(x^2-3x\\right)>-2 .\\]<\/p>", "opts": ["$-1&lt;x&lt;4$", "$x&lt;-1$ or $x>4$", "$-1&lt;x&lt;0$ or $3&lt;x&lt;4$", "$0&lt;x&lt;3$", "$x&lt;0$ or $x>3$", "$3&lt;x&lt;4$"], "ans": "C", "sol": "<p>The logarithm needs $x^2-3x>0$, that is $x&lt;0$ or $x>3$. Since the base $\\tfrac12$ is less than $1$, $\\log_{1/2}$ is decreasing, so the inequality reverses: $x^2-3x&lt;\\left(\\tfrac12\\right)^{-2}=4$, giving $-1&lt;x&lt;4$. Intersecting with the domain gives $-1&lt;x&lt;0$ or $3&lt;x&lt;4$. Forgetting the domain gives A, and forgetting the reversal gives B.<\/p>", "tags": ["exp", "ineq"], "rating": 6.4}, {"id": "F2-8", "paper": "F2", "n": 8, "q": "<p>Positive integers $a$ and $b$ have highest common factor $1$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$\\gcd(a+b,\\,ab)=1$<\/li><li>$\\gcd(a+b,\\,a-b)$ is $1$ or $2$ (when $a\\neq b$)<\/li><li>$\\gcd(a^2,\\,b^2)=1$<\/li><li>$\\gcd(a+b,\\,a^2+b^2)=1$<\/li><\/ol><\/p>", "opts": ["I, II and III only", "I and III only", "I, II, III and IV", "II and III only", "I only", "III only"], "ans": "A", "sol": "<p>I: a prime dividing $ab$ divides $a$ or $b$, and if it also divides $a+b$ it divides both, which is impossible. II: a common divisor of $a+b$ and $a-b$ divides their sum $2a$ and difference $2b$, hence divides $2\\gcd(a,b)=2$. III: $a^2$ and $b^2$ have the same prime factors as $a$ and $b$. IV fails for $a=b=1$, since $\\gcd(2,2)=2$; in general $a^2+b^2=(a+b)^2-2ab$, so the common divisor divides $2ab$ and can be $2$.<\/p>", "tags": ["mod"], "rating": 6.4}, {"id": "F2-9", "paper": "F2", "n": 9, "q": "<p>Which of the following statements are true? <ol class=\"stmts\" type=\"I\"><li>If $a$ is rational and $b$ is irrational, then $a+b$ is irrational.<\/li><li>If $a$ is rational and $b$ is irrational, then $ab$ is irrational.<\/li><li>If $x$ and $y$ are irrational, then $x+y$ is irrational.<\/li><li>If $x^2$ is irrational, then $x$ is irrational.<\/li><\/ol><\/p>", "opts": ["I only", "I, II and IV only", "IV only", "I, II, III and IV", "I and II only", "I and IV only"], "ans": "F", "sol": "<p>I: if $a+b$ were rational, then $b=(a+b)-a$ would be rational. II fails for $a=0$. III fails for $x=\\sqrt2$, $y=-\\sqrt2$. IV is the contrapositive of &ldquo;if $x$ is rational then $x^2$ is rational&rdquo;, which is true. So I and IV.<\/p>", "tags": ["prf"], "rating": 6.4}, {"id": "B1-20", "paper": "B1", "n": 20, "q": "<p>Let $f(x) = x^3 + x$, and let $f^{-1}$ denote the inverse function of $f$. Find the value of \\[ \\int_0^{10} f^{-1}(x)\\,dx. \\]<\/p>", "opts": ["$6$", "$10$", "$14$", "$16$", "$20$", "$34$"], "ans": "C", "sol": "<p>Do not try to invert $f$. Since $f$ is increasing and $f(2) = 10$, the graph of $f^{-1}$ on $[0,10]$ is the reflection of the graph of $f$ on $[0,2]$ in the line $y = x$, and together the two regions fill the $2\\times 10$ rectangle: \\[ \\int_0^{10} f^{-1}(x)\\,dx = 2\\cdot 10 - \\int_0^2 (x^3 + x)\\,dx = 20 - (4 + 2) = 14. \\] Option A is $\\int_0^2 f$, the wrong piece of the rectangle.<\/p><p><\/p>", "tags": ["arint", "sym"], "rating": 6.5}, {"id": "B2-14", "paper": "B2", "n": 14, "q": "<p>Let $A$, $B$, $C$ be the angles of a triangle. Consider: <ol class=\"stmts\" type=\"I\"><li>$\\sin A + \\sin B > \\sin C$<\/li><li>$\\cos A + \\cos B > 0$<\/li><li>$\\sin A \\sin B > \\cos C$<\/li><\/ol> Which of these statements must be true for every triangle?<\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "II and III only", "I, II and III"], "ans": "C", "sol": "<p>I: by the sine rule the sides are proportional to the sines of the opposite angles, so $\\sin A + \\sin B > \\sin C$ is the triangle inequality $a + b > c$ in disguise. True. II: since $A + B &lt; \\pi$, we have $B &lt; \\pi - A$, and cosine is decreasing on $(0,\\pi)$, so $\\cos B > \\cos(\\pi - A) = -\\cos A$. True. III: $\\cos C = -\\cos(A + B) = \\sin A \\sin B - \\cos A \\cos B$, so $\\sin A \\sin B > \\cos C$ is equivalent to $\\cos A \\cos B > 0$, which fails whenever one of $A$, $B$ is obtuse. For instance $A = 120^\\circ$, $B = C = 30^\\circ$ gives $\\sin A \\sin B = \\tfrac{\\sqrt3}{4} &lt; \\tfrac{\\sqrt3}{2} = \\cos C$. False. The answer is I and II. Each statement is a triangle fact wearing trigonometric clothing: the triangle inequality, the angle sum, and the sign of $\\cos A \\cos B$.<\/p><p><\/p>", "tags": ["trg"], "rating": 6.5}, {"id": "B2-20", "paper": "B2", "n": 20, "q": "<p>A pile contains $2026$ stones. Two players move alternately; a move consists of removing either $2$ or $3$ stones from the pile. A player who cannot move loses. With best play by both sides, which of the following is true?<\/p>", "opts": ["The second player wins.", "The first player wins, and removing $2$ stones is their only winning first move.", "The first player wins, and removing $3$ stones is their only winning first move.", "The first player wins, and removing either $2$ or $3$ stones is a winning first move.", "The result depends on choices made later in the game."], "ans": "A", "sol": "<p>Classify pile sizes as losing (L, the player to move loses) or winning (W). $0$ and $1$ are L, since no move is possible. Then $2 \\to 0$ and $3 \\to 1$ are W; $4 \\to 1$ is W; $5$ can only reach $3$ and $2$, both W, so $5$ is L; $6$ reaches $4$ and $3$, both W, so L; $7 \\to 5$ is W; $8 \\to 6$ is W; $9 \\to 6$ is W; $10$ reaches $8$ and $7$, both W, so L; $11$ reaches $9$ and $8$, so L. The pattern is periodic with period $5$: the losing sizes are those leaving remainder $0$ or $1$ on division by $5$. Since $2026 = 5 \\cdot 405 + 1$, the starting position is losing for the player to move: the second player wins. Options B to D assume the first player has a good move; option E misunderstands what best play means.<\/p><p><\/p>", "tags": ["game"], "rating": 6.5}, {"id": "C1-14", "paper": "C1", "n": 14, "q": "<p>Let $f(x)=x^3+3x$, and let $f^{-1}$ be the inverse function of $f$. Find \\[ \\int_4^{14} f^{-1}(x)\\,dx . \\]<\/p>", "opts": ["$\\dfrac{33}{4}$", "$\\dfrac{63}{4}$", "$\\dfrac{79}{4}$", "$\\dfrac{95}{4}$", "$\\dfrac{111}{4}$", "$\\dfrac{129}{4}$"], "ans": "B", "sol": "<p>$f$ is increasing with $f(1)=4$ and $f(2)=14$. On $[4,14]$, the graph of $f^{-1}$ is the reflection of the graph of $f$ on $[1,2]$, and the two areas fill the $L$-shaped region between the rectangles $[0,2]\\times[0,14]$ and $[0,1]\\times[0,4]$: \\[ \\int_4^{14}f^{-1}(x)\\,dx=2\\cdot14-1\\cdot4-\\int_1^2(x^3+3x)\\,dx=24-\\left(\\tfrac{15}{4}+\\tfrac92\\right)=24-\\tfrac{33}{4}=\\tfrac{63}{4} . \\] Option C forgets to subtract the small rectangle $1\\cdot4$: the formula is $bf(b)-af(a)-\\int_a^bf$, and the $af(a)$ term is only zero when $a=0$.<\/p><p><\/p>", "tags": ["arint", "sym"], "rating": 6.5}, {"id": "C2-6", "paper": "C2", "n": 6, "q": "<p>Consider the statement <div class=\"c\"> for all real $x$, if $\\sin x>0$ or $\\cos x>0$, then $\\sin x+\\cos x>0$. <\/div> How many of the following values of $x$ are counterexamples to this statement? \\[ \\frac{\\pi}{6},\\qquad \\frac{2\\pi}{3},\\qquad \\frac{5\\pi}{6},\\qquad \\frac{7\\pi}{6},\\qquad \\frac{5\\pi}{3},\\qquad \\frac{7\\pi}{4} \\]<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "C", "sol": "<p>A counterexample needs the hypothesis true and the conclusion false. At $\\frac\\pi6$ and $\\frac{2\\pi}3$ the hypothesis holds and $\\sin x+\\cos x>0$. At $\\frac{5\\pi}6$ the hypothesis holds ($\\sin x=\\frac12$) and $\\sin x+\\cos x=\\frac{1-\\sqrt3}{2}&lt;0$: a counterexample. At $\\frac{7\\pi}6$ both are negative, so the hypothesis fails and this is not a counterexample, however negative the sum. At $\\frac{5\\pi}3$, $\\cos x=\\frac12>0$ and the sum is $\\frac{1-\\sqrt3}{2}&lt;0$: a counterexample. At $\\frac{7\\pi}4$, $\\cos x>0$ and the sum is exactly $0$, which is not $>0$: a counterexample. Three in total.<\/p><p><\/p>", "tags": ["log", "trg"], "rating": 6.5}, {"id": "D1-10", "paper": "D1", "n": 10, "q": "<p>Find the complete set of real values of $k$ for which the equation \\[9^x-(k+1)\\,3^x+k=0\\] has exactly one real solution.<\/p>", "opts": ["$k=1$", "$k\\le0$", "$k\\le 0$ or $k=1$", "$k&lt;0$ or $k=1$", "$k\\ge1$", "$0&lt;k\\le1$"], "ans": "C", "sol": "<p>With $u=3^x>0$ the equation is $u^2-(k+1)u+k=(u-1)(u-k)=0$. The root $u=1$ always gives $x=0$. The root $u=k$ gives a second value of $x$ exactly when $k>0$ and $k\\neq1$. So there is exactly one solution when $k\\le0$ or $k=1$. Excluding $k=0$ is the usual slip: then $u=0$ is simply not available, and $x=0$ is still the only solution.<\/p>", "tags": ["exp", "quad"], "rating": 6.5}, {"id": "D2-11", "paper": "D2", "n": 11, "q": "<p>An integer $N$ with $1\\le N\\le30$ is the subject of five statements: \\[\\text{A: $N$ is prime.}\\quad\\text{B: $N$ is even.}\\quad\\text{C: $N$ is a perfect square.}\\quad\\text{D: $N>10$.}\\quad\\text{E: $N$ is a multiple of 3.}\\] Exactly three of the five statements are true, and statement C is one of them. Find $N$.<\/p>", "opts": ["$4$", "$9$", "$12$", "$16$", "$25$", "there is no such $N$"], "ans": "D", "sol": "<p>C is true, so $N$ is one of $1,4,9,16,25$, and a perfect square above $1$ is never prime, so A is false. We need exactly two of B, D, E. $1$: none. $4$: B only. $9$: E only. $16$: B and D. $25$: D only. So $N=16$. Option C, $12$, makes exactly three statements true (B, D, E), but not with C among them.<\/p>", "tags": ["log"], "rating": 6.5}, {"id": "E1-10", "paper": "E1", "n": 10, "q": "<p>The tangents from $P(7,1)$ to the circle $x^2+y^2-2x-4y-4=0$ touch the circle at $A$ and $B$. Find the area of the quadrilateral $PACB$, where $C$ is the centre of the circle.<\/p>", "opts": ["$3\\sqrt7$", "$6\\sqrt7$", "$9$", "$12$", "$3\\sqrt{37}$", "$\\sqrt{37}$"], "ans": "B", "sol": "<p>Completing the square, $C=(1,2)$ and the radius is $3$. $CP^2=36+1=37$, so each tangent has length $\\sqrt{37-9}=2\\sqrt7$. The quadrilateral consists of two right-angled triangles $CAP$ and $CBP$, each of area $\\tfrac12\\cdot3\\cdot2\\sqrt7$, so the total is $6\\sqrt7$.<\/p>", "tags": ["coord", "circ"], "rating": 6.5}, {"id": "E2-13", "paper": "E2", "n": 13, "q": "<p>An odd integer $N$ with $1\\le N\\le50$ is the subject of four statements: \\[\\text{(1) $N$ is divisible by 4.}\\quad\\text{(2) $N$ is divisible by 6.}\\quad\\text{(3) $N$ is a perfect square.}\\quad\\text{(4) $N>40$.}\\] Exactly two of the four statements are true. Find $N$.<\/p>", "opts": ["$9$", "$25$", "$36$", "$45$", "$49$", "there is no such $N$"], "ans": "E", "sol": "<p>$N$ is odd, so statements (1) and (2) are false, and both (3) and (4) must be true: $N$ is an odd perfect square greater than $40$ and at most $50$. That is $49$. Option C, $36$, satisfies (1), (2) and (3) but is even.<\/p>", "tags": ["log", "mod"], "rating": 6.5}, {"id": "F1-10", "paper": "F1", "n": 10, "q": "<p>How many solutions does the equation $\\tan 3x=\\tan x$ have in the interval $0^\\circ\\le x\\le360^\\circ$?<\/p>", "opts": ["$1$", "$3$", "$4$", "$5$", "$7$", "$9$"], "ans": "B", "sol": "<p>$\\tan$ has period $180^\\circ$, so $\\tan3x=\\tan x$ requires $3x=x+180^\\circ n$, that is $x=90^\\circ n$: the candidates are $0^\\circ,90^\\circ,180^\\circ,270^\\circ,360^\\circ$. But at $90^\\circ$ and $270^\\circ$ both $\\tan x$ and $\\tan3x$ are undefined, so these are not solutions. That leaves $0^\\circ$, $180^\\circ$ and $360^\\circ$: three solutions.<\/p>", "tags": ["trg"], "rating": 6.5}, {"id": "B2-9", "paper": "B2", "n": 9, "q": "<p>How many ordered triples $(x, y, z)$ of integers satisfy $x^2 + y^2 + z^2 = 2023$?<\/p>", "opts": ["$0$", "$8$", "$24$", "$48$", "$96$", "Infinitely many"], "ans": "A", "sol": "<p>A square leaves remainder $0$, $1$ or $4$ on division by $8$. Adding three such remainders can give $0, 1, 2, 3, 4, 5, 6$ but never $7$ (the largest available combinations are $4+4+4 \\equiv 4$, $4+4+1 \\equiv 1$, $4+1+1 = 6$, $1+1+1 = 3$). Since $2023 = 8 \\cdot 252 + 7$, there are no solutions at all. No searching is needed, which is the point: the options B to E are the counts one gets after finding one solution and multiplying by sign and permutation symmetries, and there is no solution to start from.<\/p><p><\/p>", "tags": ["mod"], "rating": 6.6}, {"id": "C1-6", "paper": "C1", "n": 6, "q": "<p>For a real number $k$, say that the equation \\[ \\sum_{n=0}^{\\infty}(2\\sin x)^n=k \\] is <em>solvable<\/em> if there is a real $x$ for which the series converges and its sum is $k$. For how many of the values $k=\\tfrac13,\\ \\tfrac12,\\ \\tfrac23,\\ 2,\\ 4$ is the equation solvable?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$"], "ans": "C", "sol": "<p>The series is geometric with ratio $2\\sin x$, so it converges only when $|2\\sin x|&lt;1$, and then its sum is $\\frac{1}{1-2\\sin x}$. Setting this equal to $k$ gives $2\\sin x=1-\\frac1k$, and convergence requires $\\left|1-\\frac1k\\right|&lt;1$, that is $0&lt;\\frac1k&lt;2$, or $k>\\frac12$. Any such $k$ gives $|\\sin x|&lt;\\frac12$, so a real $x$ exists. Hence $k=\\frac23,2,4$ work and $k=\\frac13,\\frac12$ do not: three values. The trap is $k=\\frac13$, where solving the formula gives $\\sin x=-1$, a perfectly good value of sine at which the series diverges.<\/p><p><\/p>", "tags": ["ser", "trg"], "rating": 6.6}, {"id": "C2-17", "paper": "C2", "n": 17, "q": "<p>For real numbers $a$ and $b$, consider the four conditions \\[ (1)\\ a+b>0,\\qquad (2)\\ ab>0,\\qquad (3)\\ a>0,\\qquad (4)\\ b>0 . \\] How many of the six pairs of these conditions are such that the two conditions together are equivalent to all four conditions holding?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$", "$5$"], "ans": "E", "sol": "<p>All four together are equivalent to $a>0$ and $b>0$. Test the six pairs: (1)(2): $ab>0$ means same sign, and a positive sum makes both positive; equivalent. (3)(4): trivially equivalent. (2)(3): $a>0$ and $ab>0$ give $b>0$; equivalent. (2)(4): likewise. (1)(3): $a=5$, $b=-1$ satisfies both but not (4). (1)(4): symmetric. So four pairs. Every single condition is also individually removable here, which shows that &ldquo;removable one at a time&rdquo; and &ldquo;which small subsets suffice&rdquo; are different questions.<\/p><p><\/p>", "tags": ["ns", "ineq"], "rating": 6.6}, {"id": "D1-11", "paper": "D1", "n": 11, "q": "<p>Find the complete set of real values of $m$ for which the line $y=mx$ meets the curve $y=x^3-3x^2+2x$ at exactly three distinct points.<\/p>", "opts": ["$m>-\\tfrac14$", "$m\\ge-\\tfrac14$", "$m>-\\tfrac14$ and $m\\neq0$", "$m>-\\tfrac14$ and $m\\neq2$", "$m>2$", "$m&lt;-\\tfrac14$"], "ans": "D", "sol": "<p>The intersections satisfy $x\\left(x^2-3x+2-m\\right)=0$. The origin is always one; we need the quadratic to have two distinct roots, neither of them $0$. Distinct roots need $9-4(2-m)>0$, that is $m>-\\tfrac14$. A root at $0$ happens when $2-m=0$: for $m=2$ the quadratic is $x^2-3x$, whose root $x=0$ duplicates the origin, leaving only two points. So the answer is $m>-\\tfrac14$ with $m\\neq2$. At $m=0$ the roots are $1$ and $2$, which is fine.<\/p>", "tags": ["root", "poly"], "rating": 6.6}, {"id": "D2-12", "paper": "D2", "n": 12, "q": "<p>A student proves: <em>if $a>0$, $b>0$ and $a+b=2$, then $ab\\le1$<\/em>.<\/p><p><br> (I) Suppose, for contradiction, that $ab>1$.<br> (II) Then $b>\\dfrac1a$.<br> (III) So $a+b>a+\\dfrac1a$.<br> (IV) But $a+\\dfrac1a\\ge2$ for every $a>0$.<br> (V) Hence $a+b>2$, which contradicts $a+b=2$.<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The proof is valid.", "Line II is wrong: dividing by $a$ may reverse the inequality.", "Line IV is false for some $a>0$.", "Line V is wrong: from lines III and IV we may only conclude $a+b\\ge2$.", "The argument proves the converse of the claim.", "The claim itself is false."], "ans": "A", "sol": "<p>Every step holds. Line II divides by $a$, which is positive. Line IV is true, since $a+\\frac1a-2=\\frac{(a-1)^2}{a}\\ge0$. Line V combines a strict inequality with a non-strict one, $a+b>a+\\frac1a\\ge2$, and the result is strict. The contradiction is genuine, so the proof is valid. Questions like this test whether you can confirm a correct argument rather than hunt for a mistake that is not there.<\/p>", "tags": ["prf", "ineq"], "rating": 6.6}, {"id": "E1-11", "paper": "E1", "n": 11, "q": "<p>Find the complete set of real values of $k$ for which \\[(k-1)x^2+2kx+k+3\\ge0\\qquad\\text{for every real }x .\\]<\/p>", "opts": ["$k\\ge\\tfrac32$", "$k>\\tfrac32$", "$k>1$", "$k\\ge1$", "$1&lt;k\\le\\tfrac32$", "$k\\le\\tfrac32$"], "ans": "A", "sol": "<p>If $k=1$ the expression is $2x+4$, which is negative for $x&lt;-2$, so $k=1$ fails. Otherwise we need a positive leading coefficient, $k>1$, and a non-positive discriminant: $4k^2-4(k-1)(k+3)=12-8k\\le0$, that is $k\\ge\\tfrac32$. So $k\\ge\\tfrac32$, and the boundary is included, since a zero discriminant still satisfies $\\ge0$.<\/p>", "tags": ["quad", "ineq"], "rating": 6.6}, {"id": "E1-12", "paper": "E1", "n": 12, "q": "<p>Positive real numbers $x$ and $y$ satisfy $x^2y=32$. Find the minimum value of $x+2y$.<\/p>", "opts": ["$6$", "$4\\sqrt[3]{4}$", "$6\\sqrt[3]{2}$", "$8$", "$8\\sqrt2$", "$12$"], "ans": "C", "sol": "<p>Eliminate $y=\\frac{32}{x^2}$ and minimise $g(x)=x+\\frac{64}{x^2}$ for $x>0$. $g'(x)=1-\\frac{128}{x^3}=0$ at $x^3=128$, so $x=4\\sqrt[3]2$, and this is a minimum since $g\\to\\infty$ at both ends. Then $\\frac{64}{x^2}=\\frac{64}{16\\sqrt[3]4}=\\frac{4}{\\sqrt[3]4}=2\\sqrt[3]2$, so the minimum is $4\\sqrt[3]2+2\\sqrt[3]2=6\\sqrt[3]2$. At the minimum $x=4y$, the same balance a three-term AM-GM with $\\frac x2+\\frac x2+2y$ would predict.<\/p>", "tags": ["ineq", "diff"], "rating": 6.6}, {"id": "E1-13", "paper": "E1", "n": 13, "q": "<p>Find the complete set of real values of $k$ for which the equation $\\cos^2x-\\sin x=k$ has at least one real solution $x$.<\/p>", "opts": ["$-1\\le k\\le1$", "$0\\le k\\le\\tfrac54$", "$-\\tfrac54\\le k\\le1$", "$-1\\le k\\le2$", "$-1\\le k\\le\\tfrac54$", "$k\\le\\tfrac54$"], "ans": "E", "sol": "<p>With $s=\\sin x\\in[-1,1]$, the equation is $k=1-s^2-s=\\tfrac54-\\left(s+\\tfrac12\\right)^2$. On $[-1,1]$ this takes its maximum $\\tfrac54$ at $s=-\\tfrac12$ and its minimum $-1$ at $s=1$, and every value in between. So $-1\\le k\\le\\tfrac54$. Allowing all real $s$ gives F; forgetting the vertex gives A.<\/p>", "tags": ["trg", "quad"], "rating": 6.6}, {"id": "E1-14", "paper": "E1", "n": 14, "q": "<p>The triangle with vertices $(0,0)$, $(4,1)$ and $(k,5)$ has area $10$. Find the sum of all possible values of $k$.<\/p>", "opts": ["$0$", "$10$", "$20$", "$30$", "$35$", "$40$"], "ans": "F", "sol": "<p>The area is $\\tfrac12|4\\cdot5-1\\cdot k|=\\tfrac12|20-k|$. Setting it equal to $10$ gives $20-k=\\pm20$, so $k=0$ or $k=40$, and the sum is $40$. For $k=0$ the third vertex is $(0,5)$, with base $5$ on the $y$-axis and height $4$: area $10$, as required. Missing the modulus finds only one value.<\/p>", "tags": ["coord"], "rating": 6.6}, {"id": "E2-14", "paper": "E2", "n": 14, "q": "<p>The sequence $x_1,x_2,\\dots$ is defined by $x_1=a$ and $x_{n+1}=x_n^{\\,2}-2$. For how many of the values $a=2,\\ 0,\\ 3,\\ -2.5,\\ 1,\\ -2$ is the sequence bounded?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "D", "sol": "<p>Compute: $a=2$ gives $2,2,\\dots$; $a=0$ gives $0,-2,2,2,\\dots$; $a=1$ gives $1,-1,-1,\\dots$; $a=-2$ gives $-2,2,2,\\dots$. All four are bounded. $a=3$ gives $3,7,47,\\dots$ and $a=-2.5$ gives $4.25,\\dots$, both unbounded, since once $|x_n|>2$ we have $x_{n+1}-2=x_n^2-4>0$ and the excess over $2$ grows. So four. The rule is that the sequence is bounded exactly when $|a|\\le2$.<\/p>", "tags": ["ser"], "rating": 6.6}, {"id": "F1-11", "paper": "F1", "n": 11, "q": "<p>A circle lies in the first quadrant, touches both coordinate axes, and also touches the line $3x+4y=12$. Find the sum of all possible radii.<\/p>", "opts": ["$1$", "$2$", "$3$", "$5$", "$6$", "$7$"], "ans": "F", "sol": "<p>Touching both axes in the first quadrant means centre $(r,r)$ and radius $r$. Tangency to the line requires $\\frac{|3r+4r-12|}{5}=r$, that is $|7r-12|=5r$, giving $r=6$ or $r=1$. Both work: the circle of radius $1$ is the incircle of the triangle cut off by the line, and the circle of radius $6$ lies beyond the line. The sum is $7$.<\/p>", "tags": ["coord", "circ"], "rating": 6.6}, {"id": "F1-12", "paper": "F1", "n": 12, "q": "<p>In triangle $ABC$, $AB=5$ and $AC=7$, and the median from $A$ to the midpoint $M$ of $BC$ has length $4$. Find $BC$.<\/p>", "opts": ["$\\sqrt{21}$", "$2\\sqrt{21}$", "$2\\sqrt{10}$", "$6$", "$\\sqrt{74}$", "$8$"], "ans": "B", "sol": "<p>Let $BM=MC=m$ and $\\theta=\\angle AMB$, so $\\angle AMC=180^\\circ-\\theta$ and $\\cos\\angle AMC=-\\cos\\theta$. The cosine rule in the two halves gives $25=16+m^2-8m\\cos\\theta$ and $49=16+m^2+8m\\cos\\theta$. Adding eliminates $\\theta$: $74=32+2m^2$, so $m^2=21$ and $BC=2m=2\\sqrt{21}$. Option A is $m$ itself.<\/p>", "tags": ["trg"], "rating": 6.6}, {"id": "F1-13", "paper": "F1", "n": 13, "q": "<p>How many real values of $k$ are there for which the region enclosed by the curve $y=x^2$ and the line $y=kx$ has area $36$?<\/p>", "opts": ["none", "exactly one", "infinitely many", "exactly two", "exactly three", "exactly four"], "ans": "D", "sol": "<p>The curve and line meet at $x=0$ and $x=k$, and the enclosed area is $\\left|\\int_0^k(kx-x^2)\\,dx\\right|=\\frac{|k|^3}{6}$. Setting this equal to $36$ gives $|k|=6$, so $k=6$ or $k=-6$. The two regions are mirror images in the $y$-axis. Writing $\\int_0^k$ without the modulus finds only $k=6$.<\/p>", "tags": ["arint"], "rating": 6.6}, {"id": "F2-10", "paper": "F2", "n": 10, "q": "<p>On an island, knights always tell the truth and knaves always lie. Three islanders make these statements:<\/p><p><br> A: &ldquo;B is a knave.&rdquo;<br> B: &ldquo;Exactly one of us three is a knight.&rdquo;<br> C: &ldquo;B and I are different types.&rdquo;<\/p><p><br> What are A, B and C?<\/p>", "opts": ["All three are knights.", "A and C are knights; B is a knave.", "Only A is a knight.", "Only C is a knight.", "A and B are knights; C is a knave.", "No assignment is consistent."], "ans": "B", "sol": "<p>A and B are of opposite types, since A's statement is true exactly when B is a knave. Suppose B is a knight. Then A is a knave, and exactly one knight (B) means C is a knave; but C's claim that B and C differ would then be true, which a knave cannot say. So B is a knave and A is a knight. B's statement is false, so the number of knights is not one; with A a knight, C must be a knight too. Check C: B and C do differ, so C tells the truth.<\/p>", "tags": ["log"], "rating": 6.6}, {"id": "F2-11", "paper": "F2", "n": 11, "q": "<p>Call a function $f$, defined for $x\\ge0$, <em>subadditive<\/em> if $f(x+y)\\le f(x)+f(y)$ for all $x,y\\ge0$. Which of the following functions are subadditive? <ol class=\"stmts\" type=\"I\"><li>$f(x)=\\sqrt x$<\/li><li>$f(x)=x^2$<\/li><li>$f(x)=x+1$<\/li><li>$f(x)=2^x$<\/li><li>$f(x)=3x$<\/li><\/ol><\/p>", "opts": ["I and III only", "I, III and V only", "I only", "III and V only", "I, II and V only", "I, II, III, IV and V"], "ans": "B", "sol": "<p>I: squaring shows $\\sqrt{x+y}\\le\\sqrt x+\\sqrt y\\iff x+y\\le x+y+2\\sqrt{xy}$, which is true. III: $x+y+1\\le x+y+2$. V gives equality, which is allowed. II fails at $x=y=1$ ($4>2$), and IV fails at $x=y=2$ ($16>8$). So I, III and V.<\/p>", "tags": ["log", "ineq"], "rating": 6.6}, {"id": "B2-11", "paper": "B2", "n": 11, "q": "<p>For a convex quadrilateral, the condition <div class=\"c\"> &ldquo;the midpoints of the four sides are the vertices of a square&rdquo; <\/div> is <span class=\"blank\">________<\/span> for the quadrilateral to be a square.<\/p>", "opts": ["necessary but not sufficient", "sufficient but not necessary", "necessary and sufficient", "neither necessary nor sufficient"], "ans": "A", "sol": "<p>The midpoints of the sides of any quadrilateral form a parallelogram whose sides are parallel to the diagonals and half their length. That parallelogram is a square exactly when the diagonals are equal in length and perpendicular. A square has such diagonals, so the condition is necessary. It is not sufficient: the quadrilateral with vertices $(-2,0)$, $(0,1)$, $(2,0)$, $(0,-3)$ is convex, has perpendicular diagonals both of length $4$, and is a kite, not a square. The condition is necessary but not sufficient.<\/p><p><\/p>", "tags": ["ns", "circ"], "rating": 6.7}, {"id": "C2-3", "paper": "C2", "n": 3, "q": "<p>Which of the following statements are logically equivalent to &ldquo;if $P$, then $Q$ or $R$&rdquo;? <ol class=\"stmts\" type=\"I\"><li>If $P$ and not $Q$, then $R$.<\/li><li>If not $Q$ and not $R$, then not $P$.<\/li><li>Either &ldquo;if $P$ then $Q$&rdquo; is true, or &ldquo;if $P$ then $R$&rdquo; is true (or both).<\/li><li>&ldquo;If $P$ then $Q$&rdquo; and &ldquo;if $P$ then $R$&rdquo; are both true.<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I, II and III only", "II and III only", "I and III only", "I, II, III and IV"], "ans": "C", "sol": "<p>Write each as a disjunction. The original is (not $P$) or $Q$ or $R$. I is not$(P$ and not $Q)$ or $R$, which is (not $P$) or $Q$ or $R$: equivalent. II is the contrapositive of the original: equivalent. III is ((not $P$) or $Q$) or ((not $P$) or $R$), which simplifies to (not $P$) or $Q$ or $R$: equivalent. IV is ((not $P$) or $Q$) and ((not $P$) or $R$), which is (not $P$) or ($Q$ and $R$): stronger, and false when $P$ and $Q$ are true and $R$ is false.<\/p><p><\/p>", "tags": ["log"], "rating": 6.7}, {"id": "B1-11", "paper": "B1", "n": 11, "q": "<p>There are exactly two straight lines that are tangent to both of the curves \\[ y = x^2 \\qquad\\text{and}\\qquad y = -x^2 + 6x - 10. \\] Find the product of the gradients of these two lines.<\/p>", "opts": ["$-4$", "$-2$", "$-1$", "$1$", "$2$", "$4$"], "ans": "B", "sol": "<p>The tangent to $y = x^2$ at $x = a$ is $y = 2ax - a^2$; the tangent to the second curve at $x = b$ is $y = (6-2b)x + b^2 - 10$. Matching gradients and intercepts, $a = 3 - b$ and $-(3-b)^2 = b^2 - 10$, which reduces to $2b^2 - 6b - 1 = 0$. The two common tangents correspond to the two roots $b_1, b_2$, with gradients $6 - 2b_i$, so \\[ (6-2b_1)(6-2b_2) = 36 - 12(b_1+b_2) + 4b_1b_2 = 36 - 36 - 2 = -2 \\] by Vieta, without solving for $b$ at all. (The gradients are $3 \\pm \\sqrt{11}$.)<\/p><p><\/p>", "tags": ["vie", "poly"], "rating": 6.8}, {"id": "C1-9", "paper": "C1", "n": 9, "q": "<p>Find the complete set of real values of $a$ for which the equation \\[ x^3-3ax^2+4=0 \\] has exactly one real solution.<\/p>", "opts": ["$a&lt;1$", "$a&lt;1$ and $a\\ne0$", "$0&lt;a&lt;1$", "$a>1$", "$a\\ne1$", "$a&lt;-1$"], "ans": "A", "sol": "<p>Let $g(x)=x^3-3ax^2+4$, so $g'(x)=3x(x-2a)$. If $a=0$, $g$ is increasing and has exactly one root. Otherwise the stationary values are $g(0)=4$ and $g(2a)=4-4a^3$, and there is exactly one real root precisely when these have the same sign, that is $4-4a^3>0$, or $a&lt;1$. At $a=1$, $g(x)=(x-2)^2(x+1)$ has two distinct roots, so $a=1$ is excluded. Hence $a&lt;1$, including $a=0$. Option B is the answer to a different question, the one that also demands two stationary points.<\/p><p><\/p>", "tags": ["root"], "rating": 6.8}, {"id": "C2-13", "paper": "C2", "n": 13, "q": "<p>For a positive integer $n$, consider the four statements \\[ (1)\\ 4\\mid n,\\qquad (2)\\ 6\\mid n,\\qquad (3)\\ 12\\mid n,\\qquad (4)\\ 8\\mid n . \\] Let $T$ be the set of positive integers satisfying all four. A statement is called <em>removable<\/em> if deleting it from the list does not change the set of integers satisfying all the remaining statements. Which of the following is true?<\/p>", "opts": ["Each of the four statements is removable.", "Only statement (4) is not removable.", "Only statement (1) is not removable.", "Only statements (3) and (4) are not removable.", "No statement is removable.", "Only statements (2) and (4) are not removable."], "ans": "B", "sol": "<p>All four together mean $8\\mid n$ and $3\\mid n$, that is $24\\mid n$. Remove (1): $6,12,8\\mid n$ still gives $24\\mid n$. Remove (2): $4,12,8$ gives $24$. Remove (3): $\\operatorname{lcm}(4,6,8)=24$. Remove (4): $\\operatorname{lcm}(4,6,12)=12$, so $n=12$ now slips in. Only (4) is not removable. Note that removability is about one statement at a time: (1), (2) and (3) are each removable, but not all three together.<\/p><p><\/p>", "tags": ["log", "mod"], "rating": 6.8}, {"id": "D1-12", "paper": "D1", "n": 12, "q": "<p>The circle $C$ has centre $(3,4)$ and passes through the origin $O$. How many lines through $O$ meet $C$ again at a point $P$ with $OP=8$?<\/p>", "opts": ["$0$", "$1$", "$2$", "$3$", "$4$", "infinitely many"], "ans": "C", "sol": "<p>The radius is $5$. A chord of length $8$ lies at distance $3$ from the centre, so we need lines through $O$ at distance $3$ from $(3,4)$. The line $x=0$ is at distance $3$: it meets the circle at $(0,0)$ and $(0,8)$. For $y=kx$ the distance is $\\frac{|3k-4|}{\\sqrt{1+k^2}}=3$, giving $24k=7$, so $k=\\tfrac{7}{24}$. That is two lines. Writing every line through $O$ as $y=kx$ silently discards the vertical one and gives the tempting answer $1$.<\/p>", "tags": ["coord", "circ"], "rating": 6.8}, {"id": "D1-13", "paper": "D1", "n": 13, "q": "<p>Find the total area of the regions enclosed between the curve $y=x^3-4x$ and the $x$-axis for $-2\\le x\\le 3$.<\/p>", "opts": ["$\\dfrac{25}{4}$", "$\\dfrac{33}{4}$", "$\\dfrac{41}{4}$", "$\\dfrac{49}{4}$", "$\\dfrac{57}{4}$", "$\\dfrac{65}{4}$"], "ans": "E", "sol": "<p>The curve crosses the axis at $0$ and $2$ inside the interval, so split there. With $F(x)=\\tfrac{x^4}{4}-2x^2$: $\\int_{-2}^0=F(0)-F(-2)=4$, $\\int_0^2=F(2)-F(0)=-4$, and $\\int_2^3=F(3)-F(2)=\\tfrac94+4=\\tfrac{25}{4}$. The total area is $4+4+\\tfrac{25}{4}=\\tfrac{57}{4}$. Integrating straight across from $-2$ to $3$ gives $\\tfrac{25}{4}$, because the first two pieces cancel.<\/p>", "tags": ["arint"], "rating": 6.8}, {"id": "D2-13", "paper": "D2", "n": 13, "q": "<p>A student adapts the standard proof that $\\sqrt2$ is irrational to &ldquo;prove&rdquo; that $\\sqrt4$ is irrational.<\/p><p><br> (I) Suppose $\\sqrt4=\\dfrac pq$, where $p$ and $q$ are positive integers with no common factor.<br> (II) Then $p^2=4q^2$, so $p^2$ is even and hence $p$ is even.<br> (III) Write $p=2k$. Then $4k^2=4q^2$, so $k^2=q^2$.<br> (IV) Hence $q^2$ is even, so $q$ is even.<br> (V) So $p$ and $q$ are both even, a contradiction. Hence $\\sqrt4$ is irrational.<\/p><p><br> In which line does the first error occur?<\/p>", "opts": ["I", "II", "III", "IV", "V", "there is no error"], "ans": "D", "sol": "<p>Lines I to III are correct. In the $\\sqrt2$ proof the corresponding step reads $2k^2=q^2$, which forces $q^2$ to be even. Here the equation is $k^2=q^2$, which says nothing about parity: indeed $p=2$, $q=1$, $k=1$. Line IV is the first false step.<\/p>", "tags": ["prf"], "rating": 6.8}, {"id": "E1-15", "paper": "E1", "n": 15, "q": "<p>Two circles of radius $1$ have their centres a distance $1$ apart. Find the area of the region inside both circles.<\/p>", "opts": ["$\\dfrac{\\pi}{3}-\\dfrac{\\sqrt3}{4}$", "$\\dfrac{\\pi}{3}$", "$\\dfrac{2\\pi}{3}-\\sqrt3$", "$\\dfrac{2\\pi}{3}-\\dfrac{\\sqrt3}{2}$", "$\\dfrac{\\pi}{2}-\\dfrac{\\sqrt3}{4}$", "$\\dfrac{4\\pi}{3}-\\sqrt3$"], "ans": "D", "sol": "<p>The two centres and either intersection point form an equilateral triangle, so each centre sees the common chord at an angle of $\\tfrac{2\\pi}{3}$. The lens is two circular segments, each a sector of area $\\tfrac12\\cdot\\tfrac{2\\pi}3=\\tfrac\\pi3$ minus a triangle of area $\\tfrac12\\sin\\tfrac{2\\pi}{3}=\\tfrac{\\sqrt3}{4}$. The total is $2\\left(\\tfrac\\pi3-\\tfrac{\\sqrt3}4\\right)=\\tfrac{2\\pi}{3}-\\tfrac{\\sqrt3}{2}$. Option A is one segment only.<\/p>", "tags": ["circ", "trg"], "rating": 6.8}, {"id": "E1-16", "paper": "E1", "n": 16, "q": "<p>The normal to the curve $y=x^2$ at the point $P(1,1)$ meets the curve again at $Q$. Find the length $PQ$.<\/p>", "opts": ["$\\dfrac52$", "$\\dfrac94$", "$\\dfrac{5\\sqrt2}{2}$", "$\\dfrac{3\\sqrt5}{2}$", "$\\dfrac{5\\sqrt5}{4}$", "$\\dfrac{5\\sqrt3}{2}$"], "ans": "E", "sol": "<p>The tangent gradient at $P$ is $2$, so the normal is $y-1=-\\tfrac12(x-1)$. Substituting into $y=x^2$ gives $2x^2+x-3=0$, that is $(x-1)(2x+3)=0$, so $Q=\\left(-\\tfrac32,\\tfrac94\\right)$. Then $PQ=\\sqrt{\\left(\\tfrac52\\right)^2+\\left(\\tfrac54\\right)^2}=\\tfrac54\\sqrt{4+1}=\\tfrac{5\\sqrt5}{4}$.<\/p>", "tags": ["diff", "coord"], "rating": 6.8}, {"id": "E2-15", "paper": "E2", "n": 15, "q": "<p>The polynomial $p(x)$ has integer coefficients, and $p(0)$ and $p(1)$ are both odd. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$p$ has no integer roots.<\/li><li>$p$ has no rational roots.<\/li><li>$p(2)$ is odd.<\/li><li>$p(x)\\neq0$ for every real $x$.<\/li><\/ol><\/p>", "opts": ["I and III only", "I only", "I, II and III only", "III only", "I, III and IV only", "I, II, III and IV"], "ans": "A", "sol": "<p>For an integer $n$, $p(n)-p(0)$ is a sum of multiples of $n$, and $p(n)-p(1)$ is a sum of terms $a_k(n^k-1)$, each a multiple of $n-1$. For even $n$, $p(n)$ has the parity of $p(0)$; for odd $n$, that of $p(1)$. Either way $p(n)$ is odd, never $0$: I and III hold. II and IV fail for $p(x)=2x-1$, with $p(0)=-1$ and $p(1)=1$, whose root is $\\tfrac12$.<\/p>", "tags": ["poly", "mod"], "rating": 6.8}, {"id": "F1-14", "paper": "F1", "n": 14, "q": "<p>The curve $y=x^3+px^2+qx$ has a stationary point at $(1,-4)$. Find the $y$-coordinate of its other stationary point.<\/p>", "opts": ["$-4$", "$\\dfrac{44}{27}$", "$13$", "$\\dfrac{49}{3}$", "$\\dfrac{392}{27}$", "$-\\dfrac{392}{27}$"], "ans": "E", "sol": "<p>From $y(1)=-4$: $1+p+q=-4$. From $y'(1)=0$: $3+2p+q=0$. Subtracting gives $p=2$ and $q=-7$. Then $y'=3x^2+4x-7=(3x+7)(x-1)$, so the other stationary point is at $x=-\\tfrac73$, where \\[y=-\\tfrac{343}{27}+2\\cdot\\tfrac{49}{9}+\\tfrac{49}{3}=\\tfrac{-343+294+441}{27}=\\tfrac{392}{27} .\\]<\/p>", "tags": ["diff"], "rating": 6.8}, {"id": "F1-15", "paper": "F1", "n": 15, "q": "<p>Find the area of the region of points $(x,y)$ satisfying all three of \\[y\\ge x^2,\\qquad y\\le 2x+3,\\qquad x\\ge0 .\\]<\/p>", "opts": ["$\\dfrac53$", "$\\dfrac{16}{3}$", "$7$", "$8$", "$9$", "$\\dfrac{32}{3}$"], "ans": "E", "sol": "<p>The parabola and line meet where $x^2=2x+3$, at $x=-1$ and $x=3$. With $x\\ge0$ the region runs from $0$ to $3$, and its area is $\\int_0^3(2x+3-x^2)\\,dx=9+9-9=9$. Option F is the whole segment from $-1$ to $3$, before the condition $x\\ge0$ is applied.<\/p>", "tags": ["arint"], "rating": 6.8}, {"id": "F2-12", "paper": "F2", "n": 12, "q": "<p>Which of the following conditions guarantee that a triangle is equilateral? <ol class=\"stmts\" type=\"I\"><li>Two of its angles are $60^\\circ$.<\/li><li>Its angles form an arithmetic progression.<\/li><li>Its sides form an arithmetic progression and one of its angles is $60^\\circ$.<\/li><li>Its angles form an arithmetic progression and so do its sides.<\/li><\/ol><\/p>", "opts": ["I only", "I and III only", "I, III and IV only", "I and IV only", "I, II, III and IV", "III and IV only"], "ans": "C", "sol": "<p>I: the third angle is also $60^\\circ$. II only forces the middle angle to be $60^\\circ$ (for example $30^\\circ,60^\\circ,90^\\circ$). III: take sides $a-d,a,a+d$. If the $60^\\circ$ angle faces $a$, the cosine rule gives $a^2=a^2+3d^2$; if it faces $a+d$ or $a-d$, it gives $3ad=0$. Either way $d=0$. IV reduces to III, since angles in AP include a $60^\\circ$ angle.<\/p>", "tags": ["trg", "ns"], "rating": 6.8}, {"id": "F2-13", "paper": "F2", "n": 13, "q": "<p>$f$ is a polynomial with $f(x)\\ge0$ for $0\\le x\\le2$ and $\\displaystyle\\int_0^2f(x)\\,dx=0$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$f(1)=0$<\/li><li>$f(x)=0$ for every real $x$.<\/li><li>$\\displaystyle\\int_0^3 f(x)\\,dx=0$<\/li><li>The statements above would still all be true if $f$ were only known to be continuous.<\/li><\/ol><\/p>", "opts": ["I only", "I and III only", "I, II, III and IV", "I and II only", "II and III only", "I, II and III only"], "ans": "F", "sol": "<p>A continuous non-negative function with zero integral over $[0,2]$ must vanish throughout $[0,2]$: if it were positive somewhere, it would be positive on a small interval and the integral would be positive. So I holds. A polynomial with infinitely many roots is the zero polynomial, so II holds, and then III. IV fails for a continuous function that is zero on $[0,2]$ and positive beyond it, such as $\\max(0,x-2)$, which breaks II and III.<\/p>", "tags": ["fint", "poly"], "rating": 6.8}, {"id": "F2-14", "paper": "F2", "n": 14, "q": "<p>A positive integer $n\\le100$ is the subject of five statements: \\[\\text{(1) $n$ is a perfect square.}\\quad\\text{(2) $n$ is a perfect cube.}\\quad\\text{(3) $n$ is even.}\\quad\\text{(4) $n&lt;50$.}\\quad\\text{(5) $n$ is divisible by $9$.}\\] Exactly one of the statements is false. Find $n$.<\/p>", "opts": ["$16$", "$18$", "$27$", "$36$", "$64$", "$81$"], "ans": "D", "sol": "<p>Squares that are also cubes are sixth powers: $1$ and $64$. $64$ fails (4) and (5), and $1$ fails (3) and (5), so neither works with only one false statement. So exactly one of (1) and (2) is false and the other four are true. If (1) is false, $n$ is an even cube below $50$ divisible by $9$: none, since $8\\nmid$ and $27$ is odd. If (2) is false, $n$ is an even square below $50$ divisible by $9$: that is $36$.<\/p>", "tags": ["log"], "rating": 6.8}, {"id": "F2-15", "paper": "F2", "n": 15, "q": "<p>The cubic function $f$ satisfies $f(0)=0$ and $f'(0)>0$, and it has a local maximum at $x=2$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$f$ has a local minimum at some $x>2$.<\/li><li>$f(2)>0$<\/li><li>$f'(1)>0$<\/li><li>$f(x)=0$ has three distinct real roots.<\/li><\/ol><\/p>", "opts": ["II only", "II and III only", "I, II and III only", "I, II, III and IV", "I and II only", "III and IV only"], "ans": "B", "sol": "<p>$f'$ is a quadratic that changes from positive to negative at $x=2$, and $f'(0)>0$. If $f'$ opens upwards, $2$ is its smaller root and the minimum is to the right; if it opens downwards, $2$ is its larger root and the other root is below $0$. Either way $f'>0$ on $[0,2)$, so III holds and $f(2)>f(0)=0$ gives II. I fails in the second case. IV can fail too: $f(x)=x^3-9x^2+24x$ has $f'(x)=3(x-2)(x-4)$, so $f'(0)=24>0$ and a maximum at $2$, but $f(x)=x(x^2-9x+24)$ has only the real root $0$.<\/p>", "tags": ["diff", "root"], "rating": 6.8}, {"id": "B2-8", "paper": "B2", "n": 8, "q": "<p>What is the smallest positive integer $n$ with the following property: among any $n$ integers there are two whose sum or whose difference is divisible by $12$?<\/p>", "opts": ["$6$", "$7$", "$8$", "$12$", "$13$", "$24$"], "ans": "C", "sol": "<p>Two integers have sum or difference divisible by $12$ exactly when their remainders on division by $12$ are equal or add to $12$. Group the remainders into the classes $\\{0\\}$, $\\{6\\}$, $\\{1,11\\}$, $\\{2,10\\}$, $\\{3,9\\}$, $\\{4,8\\}$, $\\{5,7\\}$: seven classes, and two numbers from the same class always work. So $8$ integers force a pair. Seven can avoid it: the remainders $0, 1, 2, 3, 4, 5, 6$ are all distinct and no two of them sum to $12$. The answer is $8$. Option B is the count of classes, one short of the pigeonhole answer.<\/p><p><\/p>", "tags": ["pig", "mod"], "rating": 6.9}, {"id": "C1-15", "paper": "C1", "n": 15, "q": "<p>Let $f(x)=\\tfrac12\\left(x^3+x\\right)$. Find the area of the finite region in the first quadrant bounded by the graphs of $y=f(x)$ and $y=f^{-1}(x)$.<\/p>", "opts": ["$\\dfrac{1}{16}$", "$\\dfrac18$", "$\\dfrac16$", "$\\dfrac14$", "$\\dfrac13$", "$\\dfrac12$"], "ans": "D", "sol": "<p>$f$ is increasing and odd, and $f(x)=x$ exactly when $x^3=x$, so the graphs of $f$ and $f^{-1}$ meet the line $y=x$, and each other, at $0$ and $1$ in the first quadrant. On $(0,1)$, $f(x)&lt;x$. The region between $f$ and $f^{-1}$ is symmetric about $y=x$, so its area is twice the area between $y=x$ and $y=f(x)$: \\[ 2\\int_0^1\\left(x-\\tfrac12(x^3+x)\\right)dx=\\int_0^1(x-x^3)\\,dx=\\tfrac14 . \\] No inverse function needs to be found. Option B is the area between $f$ and the line $y=x$ alone.<\/p><p><\/p>", "tags": ["arint", "sym"], "rating": 6.9}, {"id": "B1-18", "paper": "B1", "n": 18, "q": "<p>The points $A(1,2)$ and $B(5,2)$ are fixed, and $C$ is a point such that $\\angle ACB = 45^\\circ$. Find the maximum possible area of triangle $ABC$.<\/p>", "opts": ["$2 + 2\\sqrt2$", "$4\\sqrt2$", "$4 + 2\\sqrt2$", "$4 + 4\\sqrt2$", "$8$", "$8\\sqrt2$"], "ans": "D", "sol": "<p>The angle at $C$ is fixed, so $C$ lies on an arc of a circle through $A$ and $B$, and the sine rule in the circumcircle gives $2R = \\dfrac{AB}{\\sin 45^\\circ} = \\dfrac{4}{\\sqrt2/2}$, so $R = 2\\sqrt2$. The centre is at distance $\\sqrt{R^2 - 2^2} = 2$ from $AB$. Since $45^\\circ$ is acute, $C$ is on the major arc, on the far side of the centre from $AB$, and the largest height is $2 + 2\\sqrt2$ at the midpoint of that arc. The maximum area is $\\tfrac12\\cdot 4\\cdot(2+2\\sqrt2) = 4 + 4\\sqrt2$. Option A is the height, not the area.<\/p><p><\/p>", "tags": ["circ"], "rating": 7.0}, {"id": "B2-15", "paper": "B2", "n": 15, "q": "<p>Each cell of a $6 \\times 6$ grid is coloured black or white. Consider: <ol class=\"stmts\" type=\"I\"><li>Every row contains more black cells than white cells, and every column contains more white cells than black cells.<\/li><li>Every row contains an odd number of black cells, and every column contains an odd number of black cells.<\/li><li>Every $2 \\times 2$ block of four adjacent cells contains exactly one black cell.<\/li><\/ol> Which of these statements can be true?<\/p>", "opts": ["I only", "II only", "III only", "I and II only", "II and III only", "I, II and III"], "ans": "E", "sol": "<p>I is impossible by counting black cells two ways: each row has at least $4$ black cells, giving at least $24$ in total, while each column has at most $2$, giving at most $12$. II is possible: colour the six cells on a diagonal black, so every row and column has exactly one. III is possible: colour black exactly the cells whose row number and column number are both even; any two consecutive rows contain exactly one even row and any two consecutive columns exactly one even column, so every $2 \\times 2$ block contains exactly one black cell. The answer is II and III. Note that for II the parity check passes (six odd rows and six odd columns both give an even total) but passing a parity check is not a construction; the diagonal is.<\/p><p><\/p>", "tags": ["col", "two"], "rating": 7.0}, {"id": "C1-11", "paper": "C1", "n": 11, "q": "<p>The function $F$ is defined for all real $x$ by \\[ F(x)=\\int_0^x (x-t)\\sin t\\,dt . \\] Find $F(\\pi)$.<\/p>", "opts": ["$0$", "$1$", "$\\pi-2$", "$2$", "$3$", "$\\pi$"], "ans": "F", "sol": "<p>The variable $x$ appears inside the integrand, so take it outside first: \\[ F(x)=x\\int_0^x\\sin t\\,dt-\\int_0^x t\\sin t\\,dt=x(1-\\cos x)-(\\sin x-x\\cos x)=x-\\sin x . \\] So $F(\\pi)=\\pi$. The integration by parts is routine; the step that matters is noticing that $x$ is a constant as far as the $t$-integration is concerned and pulling it out.<\/p><p><\/p>", "tags": ["fint", "sym"], "rating": 7.0}, {"id": "D1-14", "paper": "D1", "n": 14, "q": "<p>In triangle $ABC$, $AB=10$, $BC=6$ and angle $BAC=30^\\circ$. There are two possible triangles. Find the positive difference between their areas.<\/p>", "opts": ["$2\\sqrt{11}$", "$5\\sqrt3$", "$10\\sqrt3$", "$5\\sqrt{11}$", "$10\\sqrt{11}$", "$0$: the triangle is determined"], "ans": "D", "sol": "<p>Let $AC=b$. The cosine rule at $A$ gives $36=100+b^2-20b\\cdot\\tfrac{\\sqrt3}{2}$, that is $b^2-10\\sqrt3\\,b+64=0$. Both roots are positive, and they differ by $\\sqrt{300-256}=2\\sqrt{11}$. The area is $\\tfrac12\\cdot10\\cdot b\\cdot\\sin30^\\circ=\\tfrac52b$, so the areas differ by $\\tfrac52\\cdot2\\sqrt{11}=5\\sqrt{11}$. Treating the cosine rule as a quadratic in the unknown side handles the ambiguous case with no need to find either angle.<\/p>", "tags": ["trg", "vie"], "rating": 7.0}, {"id": "D1-15", "paper": "D1", "n": 15, "q": "<p>How many tangents to the curve $y=x^3-3x$ pass through the point $(2,2)$?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "B", "sol": "<p>The tangent at $x=t$ is $y=(3t^2-3)(x-t)+t^3-3t$. It passes through $(2,2)$ when $2=(3t^2-3)(2-t)+t^3-3t$, which simplifies to $t^3-3t^2+4=0$, that is $(t+1)(t-2)^2=0$. The double root $t=2$ is a single tangent (the point lies on the curve and this is its own tangent), and $t=-1$ gives a second. So there are two tangents. Counting roots with multiplicity gives three.<\/p>", "tags": ["diff"], "rating": 7.0}, {"id": "D2-14", "paper": "D2", "n": 14, "q": "<p>The cubic $f(x)=x^3+bx^2+cx+d$ satisfies $f(0)&lt;0$, $f(1)>0$ and $f(2)&lt;0$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$f$ has three distinct real roots.<\/li><li>$b&lt;-3$<\/li><li>$f$ has a local minimum between $x=1$ and $x=2$.<\/li><li>$d&lt;0$<\/li><\/ol><\/p>", "opts": ["I and IV only", "I, II and IV only", "I, II, III and IV", "II and IV only", "I and III only", "IV only"], "ans": "B", "sol": "<p>There are sign changes on $(0,1)$ and $(1,2)$, and since $f(x)\\to\\infty$ as $x\\to\\infty$ with $f(2)&lt;0$, a third root lies beyond $2$: I is true. The roots are then $r_1\\in(0,1)$, $r_2\\in(1,2)$ and $r_3>2$, so $-b=r_1+r_2+r_3>3$ and II is true. IV is $d=f(0)&lt;0$. III can fail: with roots $0.5$, $1.5$ and $10$ the local minimum is near $x=7$.<\/p>", "tags": ["root", "poly"], "rating": 7.0}, {"id": "D2-15", "paper": "D2", "n": 15, "q": "<p>Which of the following are equal to $\\displaystyle\\int_{-1}^{1}f(x)\\,dx$ for <em>every<\/em> quadratic function $f$? <ol class=\"stmts\" type=\"I\"><li>$\\tfrac13\\left(f(-1)+4f(0)+f(1)\\right)$<\/li><li>$f\\!\\left(-\\tfrac{1}{\\sqrt3}\\right)+f\\!\\left(\\tfrac{1}{\\sqrt3}\\right)$<\/li><li>$2f(0)$<\/li><li>$f(-1)+f(1)$<\/li><\/ol><\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "I, II and III only", "I, II, III and IV"], "ans": "C", "sol": "<p>Take $f(x)=px^2+qx+r$, so the integral is $\\tfrac{2p}{3}+2r$. I: $\\tfrac13\\left((p-q+r)+4r+(p+q+r)\\right)=\\tfrac{2p}{3}+2r$. II: $2\\left(\\tfrac p3+r\\right)=\\tfrac{2p}{3}+2r$. III gives $2r$, correct only when $p=0$, and IV gives $2p+2r$, also correct only when $p=0$. So I and II. It is striking that two well-chosen points do as well as three.<\/p>", "tags": ["fint", "poly"], "rating": 7.0}, {"id": "D2-16", "paper": "D2", "n": 16, "q": "<p>Each of the following statements is either true or false.<\/p><p><br> 1. Exactly one of these three statements is true.<br> 2. Statement 1 is false.<br> 3. Statements 1 and 2 are both false.<\/p><p><br> Which statements are true?<\/p>", "opts": ["statement 1 only", "statement 2 only", "statement 3 only", "statements 2 and 3 only", "no assignment of truth values is consistent", "more than one assignment is consistent"], "ans": "A", "sol": "<p>Statements 1 and 2 contradict each other, so exactly one of them is true, and statement 3 is false. If 1 were false, 2 would be true and 3 false, giving exactly one true statement, which would make 1 true: a contradiction. So 1 is true and 2 is false, and then exactly one statement is true, which is consistent. Only statement 1 is true.<\/p>", "tags": ["log"], "rating": 7.0}, {"id": "E1-17", "paper": "E1", "n": 17, "q": "<p>For which value of $a$ is \\[\\int_a^{a+1}\\left(x^2-4x\\right)dx\\] as small as possible?<\/p>", "opts": ["$1$", "$\\dfrac32$", "$2$", "$\\dfrac52$", "$3$", "$0$"], "ans": "B", "sol": "<p>The integral is the signed area under $y=x^2-4x$ over a window of width $1$, and it is smallest when the window sits where the curve is lowest. The curve is symmetric about its minimum at $x=2$, so the best window is $\\left[\\tfrac32,\\tfrac52\\right]$, giving $a=\\tfrac32$. To confirm, $I(a)=\\tfrac{(a+1)^3-a^3}{3}-2\\left((a+1)^2-a^2\\right)=a^2-3a-\\tfrac53$, which is minimised at $a=\\tfrac32$. Choosing $a=2$ puts the minimum at the edge of the window rather than its centre.<\/p>", "tags": ["arint", "fint"], "rating": 7.0}, {"id": "E2-16", "paper": "E2", "n": 16, "q": "<p>The function $f$ is continuous and satisfies $f(x)+f(1-x)=1$ for every real $x$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$\\displaystyle\\int_0^1 f(x)\\,dx=\\tfrac12$<\/li><li>$f\\!\\left(\\tfrac12\\right)=\\tfrac12$<\/li><li>$f$ is increasing.<\/li><li>$\\displaystyle\\int_0^1 xf(x)\\,dx=\\int_0^1(1-x)\\bigl(1-f(x)\\bigr)\\,dx$<\/li><\/ol><\/p>", "opts": ["I and II only", "II only", "I, II, III and IV", "I and IV only", "II and IV only", "I, II and IV only"], "ans": "F", "sol": "<p>II: put $x=\\tfrac12$. Reflecting $[0,1]$ in $x=\\tfrac12$ shows that $\\int_0^1 f(1-x)\\,dx=\\int_0^1 f(x)\\,dx$, so adding gives $2\\int_0^1 f=\\int_0^1 1=1$, and I holds. For IV, the same reflection turns $\\int_0^1 xf(x)\\,dx$ into $\\int_0^1(1-x)f(1-x)\\,dx=\\int_0^1(1-x)\\bigl(1-f(x)\\bigr)dx$. III fails: $f(x)=\\tfrac12+\\sin\\left(2\\pi\\left(x-\\tfrac12\\right)\\right)$ satisfies the condition but is not increasing.<\/p>", "tags": ["fint", "sym"], "rating": 7.0}, {"id": "F1-16", "paper": "F1", "n": 16, "q": "<p>The curves $y=x^2$ and $y=-(x-3)^2$ have two common tangent lines. Find the point where these two lines meet.<\/p>", "opts": ["$\\left(\\tfrac32,0\\right)$", "$(3,9)$", "$(0,-9)$", "$\\left(\\tfrac32,-\\tfrac92\\right)$", "$(0,0)$", "$(3,0)$"], "ans": "A", "sol": "<p>The tangent to $y=x^2$ at $x=a$ is $y=2ax-a^2$. It touches $y=-(x-3)^2$ when $x^2+(2a-6)x+9-a^2=0$ has a repeated root: $(2a-6)^2-4(9-a^2)=8a^2-24a=0$, so $a=0$ or $a=3$. The common tangents are $y=0$ and $y=6x-9$, meeting at $\\left(\\tfrac32,0\\right)$. By symmetry, the two parabolas are images of each other under a half-turn about $\\left(\\tfrac32,0\\right)$, so the meeting point had to be there.<\/p>", "tags": ["diff", "coord"], "rating": 7.0}, {"id": "F1-17", "paper": "F1", "n": 17, "q": "<p>A cylinder is inscribed in a sphere of radius $3$. Find the greatest possible volume of the cylinder.<\/p>", "opts": ["$12\\sqrt3\\,\\pi$", "$36\\pi$", "$24\\pi$", "$8\\sqrt3\\,\\pi$", "$16\\pi$", "$18\\sqrt2\\,\\pi$"], "ans": "A", "sol": "<p>If the cylinder has height $h$ and radius $\\rho$, then $\\rho^2+\\left(\\tfrac h2\\right)^2=9$, so $V=\\pi\\left(9-\\tfrac{h^2}{4}\\right)h$. Then $V'(h)=\\pi\\left(9-\\tfrac{3h^2}{4}\\right)=0$ at $h=2\\sqrt3$, a maximum. This gives $V=\\pi(9-3)\\cdot2\\sqrt3=12\\sqrt3\\,\\pi$.<\/p>", "tags": ["diff"], "rating": 7.0}, {"id": "F1-18", "paper": "F1", "n": 18, "q": "<p>Find the sum of all the integers from $1$ to $500$ inclusive that are divisible by $3$ or by $7$, but not by both.<\/p>", "opts": ["$5796$", "$36\\,015$", "$41\\,583$", "$47\\,883$", "$53\\,679$", "$59\\,475$"], "ans": "D", "sol": "<p>Multiples of $3$: $3,6,\\dots,498$, which is $166$ terms with sum $3\\cdot\\frac{166\\cdot167}{2}=41\\,583$. Multiples of $7$: $7,\\dots,497$, which is $71$ terms with sum $7\\cdot\\frac{71\\cdot72}{2}=17\\,892$. Multiples of $21$: $21,\\dots,483$, which is $23$ terms with sum $21\\cdot\\frac{23\\cdot24}{2}=5796$. &ldquo;Not both&rdquo; removes the multiples of $21$ from both lists: $41\\,583+17\\,892-2\\cdot5796=47\\,883$. Subtracting $5796$ only once gives the inclusive &ldquo;or&rdquo;, option E.<\/p>", "tags": ["ser", "cnt"], "rating": 7.0}, {"id": "F2-16", "paper": "F2", "n": 16, "q": "<p>Consider the equation $\\tan x=x$, with $x$ in radians. Which of the following are true? <ol class=\"stmts\" type=\"I\"><li>It has exactly one solution in the interval $\\frac\\pi2&lt;x&lt;\\frac{3\\pi}2$.<\/li><li>It has no solution in the interval $0&lt;x&lt;\\frac\\pi2$.<\/li><li>Its solution in $\\frac\\pi2&lt;x&lt;\\frac{3\\pi}2$ is greater than $\\pi$.<\/li><li>Its solution in $\\frac\\pi2&lt;x&lt;\\frac{3\\pi}2$ is less than $\\frac{5\\pi}4$.<\/li><\/ol><\/p>", "opts": ["I, II, III and IV", "I only", "I and III only", "II and IV only", "I, II and III only", "I and II only"], "ans": "E", "sol": "<p>II: on $\\left(0,\\frac\\pi2\\right)$, $\\tan x>x$. On $\\left(\\frac\\pi2,\\pi\\right]$, $\\tan x\\le0&lt;x$, so any solution lies in $\\left(\\pi,\\frac{3\\pi}2\\right)$, where $\\tan x-x$ increases from $-\\pi$ to $+\\infty$: exactly one solution, and it exceeds $\\pi$. So I and III hold. IV fails: at $x=\\frac{5\\pi}4$, $\\tan x=1&lt;\\frac{5\\pi}{4}$, so the crossing comes later (in fact near $4.49$).<\/p>", "tags": ["trg", "root"], "rating": 7.0}, {"id": "F2-17", "paper": "F2", "n": 17, "q": "<p>Let $p=\\log_2 3$, $q=\\log_3 5$ and $r=\\log_5 8$. Which of the following is correct?<\/p>", "opts": ["$r&lt;q<p$", "$p&lt;q&lt;r$", "$q&lt;r<p$", "$r<p&lt;q$", "$q<p&lt;r$", "$p&lt;r&lt;q$"], "ans": "A", "sol": "<p>Compare each with $1.5$ and then refine. $2^{1.5}=2\\sqrt2\\approx2.83&lt;3$, so $p>1.5$. $3^{1.5}=3\\sqrt3\\approx5.20>5$, so $q&lt;1.5$. To separate $q$ and $r$: $5^{1.3}>8$ (since $5^{13}\\approx1.22\\times10^9>8^{10}\\approx1.07\\times10^9$), so $r&lt;1.3$, while $3^{1.4}&lt;5$ (since $3^{14}=4\\,782\\,969&lt;5^{10}=9\\,765\\,625$), so $q>1.4$. Hence $r&lt;q<p$.<\/p>", "tags": ["exp", "ineq"], "rating": 7.0}, {"id": "B1-5", "paper": "B1", "n": 5, "q": "<p>Positive real numbers $x$ and $y$ satisfy $x + y = 1$. Find the minimum value of \\[ \\Bigl(x + \\frac1x\\Bigr)^2 + \\Bigl(y + \\frac1y\\Bigr)^2 . \\]<\/p>", "opts": ["$8$", "$\\dfrac{25}{4}$", "$\\dfrac{25}{2}$", "$13$", "$15$", "$25$"], "ans": "C", "sol": "<p>Put $u = x + \\frac1x$ and $v = y + \\frac1y$. Then $u + v = 1 + \\frac1x + \\frac1y \\ge 1 + \\frac{4}{x+y} = 5$, the inequality being $\\frac1x + \\frac1y \\ge \\frac{4}{x+y}$ (AM--HM, or clear denominators to $(x-y)^2 \\ge 0$). Then \\[ u^2 + v^2 \\ge \\frac{(u+v)^2}{2} \\ge \\frac{25}{2}, \\] with equality throughout at $x = y = \\tfrac12$, where each bracket is $\\tfrac52$. Substituting $y = 1 - x$ and differentiating is possible but ugly, and the two-step inequality is what the question is testing.<\/p><p><\/p>", "tags": ["ineq"], "rating": 7.1}, {"id": "C1-13", "paper": "C1", "n": 13, "q": "<p>Evaluate \\[ \\int_0^4 \\frac{1}{1+2^{\\,x-2}}\\,dx . \\]<\/p>", "opts": ["$2$", "$1$", "$\\dfrac{2}{\\ln 2}$", "$4-\\dfrac{2}{\\ln 2}$", "$\\ln 5$", "$\\dfrac52$"], "ans": "A", "sol": "<p>Let $g(x)=\\frac{1}{1+2^{x-2}}$ and pair $x$ with $4-x$. Writing $t=2^{x-2}$, we have $2^{(4-x)-2}=\\frac1t$, so \\[ g(x)+g(4-x)=\\frac{1}{1+t}+\\frac{1}{1+\\frac1t}=\\frac{1}{1+t}+\\frac{t}{1+t}=1 . \\] Substituting $x\\mapsto4-x$ shows $\\int_0^4g(x)\\,dx=\\int_0^4g(4-x)\\,dx$, so twice the integral is $\\int_0^4 1\\,dx=4$, and the answer is $2$. Integrating directly is possible, via $\\frac{1}{1+t}=1-\\frac{t}{1+t}$, but slower and error-prone.<\/p><p><\/p>", "tags": ["sym", "arint"], "rating": 7.1}, {"id": "C1-7", "paper": "C1", "n": 7, "q": "<p>For how many integers $k$ does the equation \\[ 2\\sin^2x+3\\sin x+k=0 \\] have exactly two solutions with $0\\le x&lt;2\\pi$?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "E", "sol": "<p>Put $s=\\sin x\\in[-1,1]$. A value of $s$ strictly between $-1$ and $1$ gives two values of $x$ in $[0,2\\pi)$; $s=\\pm1$ gives one each. Write the equation as $k=g(s)=-2s^2-3s$. On $[-1,1]$, $g$ rises from $g(-1)=1$ to its maximum $g(-\\frac34)=\\frac98$, then falls to $g(1)=-5$. For an integer $k$ with $-5&lt;k&lt;1$, the horizontal line meets the falling branch exactly once, at some $s$ strictly inside $(-1,1)$, and misses the rising branch: exactly two solutions. At $k=1$ the roots are $s=-1$ and $s=-\\frac12$, giving $1+2=3$ solutions; at $k=-5$ the only admissible root is $s=1$, giving $1$. So $k\\in\\{-4,-3,-2,-1,0\\}$: five integers.<\/p><p><\/p>", "tags": ["trg", "root"], "rating": 7.2}, {"id": "D1-16", "paper": "D1", "n": 16, "q": "<p>Find the complete set of real values of $k$ for which the curve \\[y=x^4-4x^3+kx^2\\] has exactly one stationary point.<\/p>", "opts": ["$k>\\tfrac92$", "$k\\ge\\tfrac92$", "$k>9$", "$k&lt;0$ or $k>\\tfrac92$", "$0&lt;k&lt;\\tfrac92$", "$k\\neq0$"], "ans": "A", "sol": "<p>$\\frac{dy}{dx}=2x\\left(2x^2-6x+k\\right)$, so $x=0$ is always stationary and we need the quadratic to add nothing new. If $k>\\tfrac92$ it has no real roots: exactly one stationary point. If $k=\\tfrac92$ it has the double root $x=\\tfrac32$; the gradient is zero there, so it is a second stationary point, a point of inflection. If $k=0$ its roots are $0$ and $3$, and $3$ is new. So the answer is $k>\\tfrac92$. Including $\\tfrac92$ confuses &ldquo;stationary point&rdquo; with &ldquo;turning point&rdquo;.<\/p>", "tags": ["diff", "quad"], "rating": 7.2}, {"id": "D1-17", "paper": "D1", "n": 17, "q": "<p>$OABC$ is the parallelogram with vertices $O(0,0)$, $A(6,0)$, $B(8,4)$ and $C(2,4)$. The point $M$ lies on $AB$ with $AM:MB=1:2$, and the line $OM$ meets the diagonal $AC$ at $P$. What fraction of the area of the parallelogram is the area of triangle $OPC$?<\/p>", "opts": ["$\\dfrac14$", "$\\dfrac27$", "$\\dfrac13$", "$\\dfrac38$", "$\\dfrac25$", "$\\dfrac12$"], "ans": "D", "sol": "<p>$M=A+\\tfrac13(B-A)=\\left(\\tfrac{20}{3},\\tfrac43\\right)$, so $OM$ is the line $y=\\tfrac15x$, while $AC$ is $x+y=6$. They meet at $P=(5,1)$, three quarters of the way from $O$ to $M$. Triangle $OPC$ has vertices $(0,0)$, $(5,1)$ and $(2,4)$. Enclose it in the rectangle $[0,5]\\times[0,4]$ of area $20$ and remove the three right triangles around it, of areas $\\tfrac52$, $\\tfrac92$ and $4$: the triangle has area $9$. The parallelogram has area $6\\times4=24$, so the fraction is $\\tfrac{9}{24}=\\tfrac38$.<\/p>", "tags": ["coord"], "rating": 7.2}, {"id": "E2-17", "paper": "E2", "n": 17, "q": "<p>Which of the following statements are true? <ol class=\"stmts\" type=\"I\"><li>A parallelogram whose vertices lie on a circle is a rectangle.<\/li><li>A rhombus whose vertices lie on a circle is a square.<\/li><li>A trapezium whose vertices lie on a circle is isosceles.<\/li><li>A kite whose vertices lie on a circle has two right angles.<\/li><li>A quadrilateral whose vertices lie on a circle and whose diagonals are perpendicular is a kite.<\/li><\/ol><\/p>", "opts": ["I, II, III and IV only", "I and II only", "I, II and III only", "I, II, III, IV and V", "I, II and IV only", "III and V only"], "ans": "A", "sol": "<p>Opposite angles of a cyclic quadrilateral sum to $180^\\circ$. I: a parallelogram's opposite angles are equal, so each is $90^\\circ$. II follows from I, since a rectangle that is a rhombus is a square. III: the angles on each parallel side are supplementary to their neighbours and so equal in pairs, which makes the trapezium isosceles. IV: a kite has one pair of equal opposite angles, so each is $90^\\circ$. V fails: many cyclic quadrilaterals have perpendicular diagonals without two pairs of equal adjacent sides.<\/p>", "tags": ["circ", "prf"], "rating": 7.2}, {"id": "E2-18", "paper": "E2", "n": 18, "q": "<p>Three arguments are offered for the claim <em>no positive integer $n$ makes $n^2+n+1$ divisible by $5$<\/em>.<\/p><p><br> <strong>I.<\/strong> For $n=1,2,3,4,5$ the values are $3,7,13,21,31$, none of which is divisible by $5$.<br> <strong>II.<\/strong> Every $n$ is congruent to $0,1,2,3$ or $4$ modulo $5$, and for these $n^2+n+1\\equiv1,3,2,3,1\\pmod5$ respectively.<br> <strong>III.<\/strong> $n^2+n+1=n(n+1)+1$, and the product of two consecutive integers ends in $0$, $2$ or $6$, so $n^2+n+1$ ends in $1$, $3$ or $7$.<\/p><p><br> Which of these are valid proofs of the claim?<\/p>", "opts": ["I only", "II only", "I and II only", "I, II and III", "II and III only", "none of them"], "ans": "E", "sol": "<p>I checks five cases and says nothing about $n=6$ or beyond, so it is not a proof. II covers every integer through its remainder, since $n^2+n+1$ modulo $5$ depends only on $n$ modulo $5$: a complete proof. III is also complete: the last digit of $n(n+1)$ depends only on the last digit of $n$, and the ten cases give only $0$, $2$ and $6$. A last digit of $1$, $3$ or $7$ rules out divisibility by $5$.<\/p>", "tags": ["prf", "mod"], "rating": 7.2}, {"id": "F1-19", "paper": "F1", "n": 19, "q": "<p>Find the minimum value of \\[\\frac{x^2+3}{\\sqrt{x^2+2}}\\] over all real $x$.<\/p>", "opts": ["$\\dfrac32$", "$\\sqrt3$", "$2$", "$\\dfrac{3\\sqrt2}{2}$", "$\\dfrac52$", "$2\\sqrt2$"], "ans": "D", "sol": "<p>Put $u=\\sqrt{x^2+2}\\ge\\sqrt2$. The expression is $\\frac{u^2+1}{u}=u+\\frac1u$. The inequality $u+\\frac1u\\ge2$ is useless here: equality needs $u=1$, which is not allowed. Since $u+\\frac1u$ is increasing for $u\\ge1$, the minimum is at $u=\\sqrt2$, that is $x=0$, giving $\\sqrt2+\\frac{1}{\\sqrt2}=\\frac{3\\sqrt2}{2}$. Option C is the unattainable bound.<\/p>", "tags": ["ineq", "diff"], "rating": 7.2}, {"id": "F2-18", "paper": "F2", "n": 18, "q": "<p>A function $f$ satisfies $f(4-x)=f(x)$ and $f(-x)=-f(x)$ for every real $x$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$f(4)=0$<\/li><li>$f(x+8)=f(x)$ for every $x$<\/li><li>$f(2)=0$<\/li><li>$f(6)=-f(2)$<\/li><\/ol><\/p>", "opts": ["I and II only", "II only", "I, II, III and IV", "I, II and IV only", "II and IV only", "I and IV only"], "ans": "D", "sol": "<p>Oddness gives $f(0)=0$, and then $f(4)=f(4-0)=f(0)=0$: I. Next $f(x+4)=f(4-(x+4))=f(-x)=-f(x)$, and applying this twice gives $f(x+8)=f(x)$: II. IV: $f(6)=f(4-6)=f(-2)=-f(2)$. III fails: $f(x)=\\sin\\frac{\\pi x}{4}$ satisfies both conditions and has $f(2)=1$.<\/p>", "tags": ["sym"], "rating": 7.2}, {"id": "B1-7", "paper": "B1", "n": 7, "q": "<p>Find the value of \\[ \\sum_{n=1}^{\\infty} \\frac{n+2}{n(n+1)\\,2^{n}} . \\]<\/p>", "opts": ["$\\dfrac12$", "$\\dfrac34$", "$1$", "$\\dfrac54$", "$\\dfrac32$", "$2$"], "ans": "C", "sol": "<p>Partial fractions in $n$ alone go nowhere, because of the $2^n$. The trick is to split the numerator against the factor $2$ rather than against $n$ and $n+1$: write $n + 2 = 2(n+1) - n$, so \\[ \\frac{n+2}{n(n+1)2^n} = \\frac{2}{n\\,2^n} - \\frac{1}{(n+1)2^n} = \\frac{1}{n\\,2^{n-1}} - \\frac{1}{(n+1)\\,2^{n}} . \\] With $b_n = \\dfrac{1}{n\\,2^{n-1}}$ this is $b_n - b_{n+1}$, so the partial sum is $b_1 - b_{N+1} = 1 - \\dfrac{1}{(N+1)2^N}$, and the infinite sum is $1$. The first three partial sums are $\\tfrac34, \\tfrac{11}{12}, \\tfrac{31}{32}$, which is the pattern a candidate without the decomposition would have to guess from; option B is the first term on its own.<\/p><p><\/p>", "tags": ["tel", "ser"], "rating": 7.3}, {"id": "C2-15", "paper": "C2", "n": 15, "q": "<p>For a real number $x$, consider the five statements \\[ x>1,\\qquad x^2>1,\\qquad x^3>1,\\qquad x>-1,\\qquad x^2>x . \\] Find the complete set of real $x$ for which exactly two of these statements are true.<\/p>", "opts": ["$x&lt;-1$", "$-1&lt;x&lt;0$", "$x&lt;0$", "$x\\le 0$ and $x\\ne-1$", "$x&lt;0$ and $x\\ne-1$", "there is no such $x$"], "ans": "E", "sol": "<p>Count true statements region by region. For $x>1$ all five hold. For $-1&lt;x\\le1$, $x>-1$ holds, and $x^2>x$ holds only when $x&lt;0$; so two are true on $(-1,0)$ and one on $[0,1]$. At $x=-1$ only $x^2>x$ holds. For $x&lt;-1$, exactly $x^2>1$ and $x^2>x$ hold. So exactly two are true for $x&lt;-1$ and for $-1&lt;x&lt;0$, but not at $x=-1$ itself.<\/p><p><\/p>", "tags": ["log", "root"], "rating": 7.3}, {"id": "D2-17", "paper": "D2", "n": 17, "q": "<p>A student solves $x^4-3x^3+4x^2-3x+1=0$ over the real numbers.<\/p><p><br> (I) $x=0$ is not a solution, so divide by $x^2$: $x^2+\\dfrac1{x^2}-3\\left(x+\\dfrac1x\\right)+4=0$.<br> (II) With $t=x+\\dfrac1x$, we have $x^2+\\dfrac1{x^2}=t^2-2$, so $t^2-3t+2=0$ and $t=1$ or $t=2$.<br> (III) For every non-zero real $x$, $x+\\dfrac1x\\ge2$, so $t=1$ is impossible.<br> (IV) $t=2$ gives $x^2-2x+1=0$, so $x=1$.<br> (V) Hence the only real solution is $x=1$.<\/p><p><br> Which of the following is correct?<\/p>", "opts": ["The argument is correct.", "Line III is false, but the conclusion is correct.", "Line III is false, and the conclusion is wrong.", "Line II contains an algebraic error.", "Line IV is wrong: $x+\\frac1x=2$ has two real solutions.", "Line I is wrong, since $x=0$ must be checked separately."], "ans": "B", "sol": "<p>Line III is false as stated: for $x&lt;0$, $x+\\frac1x\\le-2$, for instance $-2$ at $x=-1$. The correct fact is $\\left|x+\\frac1x\\right|\\ge2$. That still rules out $t=1$, and directly, $x^2-x+1=0$ has no real roots. So the conclusion stands: the polynomial is $(x-1)^2(x^2-x+1)$, whose only real root is $1$. The answer is B.<\/p>", "tags": ["prf", "poly"], "rating": 7.3}, {"id": "E1-18", "paper": "E1", "n": 18, "q": "<p>Let $a>0$. For which values of $a$ is the greatest value of $f(x)=x^3-3a^2x$ on the interval $0\\le x\\le2$ equal to $0$?<\/p>", "opts": ["$a\\ge2$", "$a\\ge1$", "$a\\ge\\sqrt2$", "$0&lt;a\\le\\dfrac{2}{\\sqrt3}$", "$a\\ge\\dfrac43$", "$a\\ge\\dfrac{2}{\\sqrt3}$"], "ans": "F", "sol": "<p>$f'(x)=3(x^2-a^2)$, so $f$ decreases on $[0,a]$ and increases after $a$. On $[0,2]$ the maximum is therefore at an endpoint: it is $\\max\\left(f(0),f(2)\\right)=\\max\\left(0,\\,8-6a^2\\right)$. This equals $0$ exactly when $8-6a^2\\le0$, that is $a\\ge\\tfrac{2}{\\sqrt3}$. It holds even when $a>2$, since then $f$ decreases on the whole interval.<\/p>", "tags": ["diff"], "rating": 7.3}, {"id": "B2-13", "paper": "B2", "n": 13, "q": "<p>Let $f$ be a continuous function on $[0,1]$ with $0 \\le f(x) \\le 1$ for every $x$ in $[0,1]$. Consider: <ol class=\"stmts\" type=\"I\"><li>$\\displaystyle\\int_0^1 f(x)^2\\,dx \\le \\int_0^1 f(x)\\,dx$<\/li><li>$\\displaystyle\\int_0^1 f(x)^2\\,dx \\le \\left(\\int_0^1 f(x)\\,dx\\right)^{\\!2}$<\/li><li>If $\\displaystyle\\int_0^1 f(x)^2\\,dx = \\int_0^1 f(x)\\,dx$, then $f$ is constant on $[0,1]$.<\/li><\/ol> Which of these statements must be true?<\/p>", "opts": ["I only", "II only", "III only", "I and II only", "I and III only", "I, II and III"], "ans": "E", "sol": "<p>I holds because $0 \\le f \\le 1$ gives $f^2 \\le f$ pointwise, and integrating preserves the inequality. II is false: $f(x) = x$ gives $\\int f^2 = \\tfrac13$ and $(\\int f)^2 = \\tfrac14$. The true inequality runs the other way, and the neatest proof is worth knowing: with $m = \\int_0^1 f$, expanding $0 \\le \\int_0^1 (f - m)^2 = \\int f^2 - 2m^2 + m^2$ gives $\\int f^2 \\ge m^2$. For III, the hypothesis says $\\int_0^1 (f - f^2) = 0$ with $f - f^2 = f(1-f) \\ge 0$ continuous, so $f(1 - f)$ vanishes everywhere: every value of $f$ is $0$ or $1$. A continuous function taking only the values $0$ and $1$ cannot take both (it would have to pass through $\\tfrac12$), so $f$ is constant. The answer is I and III. Option D is the reader who assumes an inequality between $\\int f^2$ and $(\\int f)^2$ without checking which way it goes.<\/p><p><\/p>", "tags": ["fint", "ineq"], "rating": 7.4}, {"id": "D2-18", "paper": "D2", "n": 18, "q": "<p>The function $f(x)=x^3+ax^2+bx$ is called <em>increasing<\/em> if $f(x_1)&lt;f(x_2)$ whenever $x_1&lt;x_2$. Which condition on $a$ and $b$ is necessary and sufficient for $f$ to be increasing?<\/p>", "opts": ["$a^2&lt;3b$", "$b>0$", "$b\\ge0$", "$a^2\\le b$", "$a^2\\le3b$", "$a=0$ and $b\\ge0$"], "ans": "E", "sol": "<p>$f'(x)=3x^2+2ax+b$. If $a^2&lt;3b$, $f'>0$ everywhere. If $a^2=3b$, $f'$ vanishes at one point and is positive elsewhere, and $f$ is still increasing, just as $x^3$ is. If $a^2>3b$, $f'$ is negative between its roots, so $f$ decreases there. The condition is $a^2\\le3b$. Option A demands $f'>0$ everywhere, which is sufficient but not necessary.<\/p>", "tags": ["ns", "diff"], "rating": 7.4}, {"id": "E1-19", "paper": "E1", "n": 19, "q": "<p>Find the total area of the regions enclosed between the curve $y=\\dfrac{x-2}{\\sqrt x}$, the $x$-axis and the lines $x=1$ and $x=4$.<\/p>", "opts": ["$\\dfrac{16\\sqrt2-18}{3}$", "$\\dfrac23$", "$\\dfrac{8\\sqrt2-10}{3}$", "$\\dfrac{8\\sqrt2-8}{3}$", "$\\dfrac{16\\sqrt2-10}{3}$", "$\\dfrac{10}{3}$"], "ans": "A", "sol": "<p>The curve is below the axis on $[1,2)$ and above it on $(2,4]$. With $F(x)=\\tfrac23x^{3/2}-4x^{1/2}$: $F(1)=-\\tfrac{10}{3}$, $F(2)=-\\tfrac{8\\sqrt2}{3}$ and $F(4)=-\\tfrac83$. The two areas are $F(1)-F(2)=\\tfrac{8\\sqrt2-10}{3}$ and $F(4)-F(2)=\\tfrac{8\\sqrt2-8}{3}$, totalling $\\tfrac{16\\sqrt2-18}{3}$. The signed integral from $1$ to $4$ is $\\tfrac23$, option B.<\/p>", "tags": ["arint"], "rating": 7.4}, {"id": "E2-19", "paper": "E2", "n": 19, "q": "<p>An arithmetic progression $u_1,u_2,\\dots$ has non-zero common difference, and its partial sums satisfy $S_{10}=S_{20}$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$S_{30}=0$<\/li><li>$u_{15}+u_{16}=0$<\/li><li>$u_{15}=0$<\/li><li>$S_{15}$ is either the largest or the smallest of all the $S_n$.<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "II and IV only", "I, II, III and IV", "I and III only", "I, II and IV only"], "ans": "F", "sol": "<p>$S_n=An^2+Bn$ with $A\\neq0$. $S_{10}=S_{20}$ gives $300A+10B=0$, so $S_n=A(n^2-30n)$. I: $S_{30}=0$. IV: $n^2-30n$ is least at $n=15$, so $S_{15}$ is the extreme value. II: $u_{11}+\\dots+u_{20}=S_{20}-S_{10}=0$, and these ten terms pair up as five pairs each equal to $u_{15}+u_{16}$. III fails: in $u_n=31-2n$ we have $S_{10}=S_{20}=200$ but $u_{15}=1$.<\/p>", "tags": ["ser"], "rating": 7.4}, {"id": "F2-19", "paper": "F2", "n": 19, "q": "<p>For an integer $k$ with $-10\\le k\\le10$, let $P$ be the statement &ldquo;$x^2-kx+1=0$ has real roots&rdquo; and $Q$ the statement &ldquo;$x^2-x+k=0$ has real roots&rdquo;. For how many such $k$ is exactly one of $P$ and $Q$ true?<\/p>", "opts": ["$5$", "$7$", "$9$", "$10$", "$11$", "$13$"], "ans": "E", "sol": "<p>$P$ holds when $k^2\\ge4$, that is $k\\le-2$ or $k\\ge2$. $Q$ holds when $1-4k\\ge0$, that is $k\\le\\tfrac14$, so $k\\le0$ for integers. Exactly one holds when $P$ is true and $Q$ false, which is $k=2,\\dots,10$ (nine values), or $Q$ is true and $P$ false, which is $k=-1,0$ (two values). That is $11$. For $k\\le-2$ both hold, and for $k=1$ neither does.<\/p>", "tags": ["ns", "quad"], "rating": 7.4}, {"id": "B1-1", "paper": "B1", "n": 1, "q": "<p>Find the exact value of $\\cos\\dfrac{\\pi}{7}\\cos\\dfrac{2\\pi}{7}\\cos\\dfrac{3\\pi}{7}$.<\/p>", "opts": ["$\\dfrac1{16}$", "$\\dfrac18$", "$\\dfrac14$", "$\\dfrac{\\sqrt7}{8}$", "$-\\dfrac18$", "$\\dfrac12$"], "ans": "B", "sol": "<p>Let $P = \\cos\\frac{\\pi}{7}\\cos\\frac{2\\pi}{7}\\cos\\frac{4\\pi}{7}$ and multiply by $\\sin\\frac{\\pi}{7}$. Folding three times with $2\\sin\\theta\\cos\\theta = \\sin 2\\theta$, \\[ \\sin\\tfrac{\\pi}{7}\\,P = \\tfrac12\\sin\\tfrac{2\\pi}{7}\\cos\\tfrac{2\\pi}{7}\\cos\\tfrac{4\\pi}{7} = \\tfrac14\\sin\\tfrac{4\\pi}{7}\\cos\\tfrac{4\\pi}{7} = \\tfrac18\\sin\\tfrac{8\\pi}{7} = -\\tfrac18\\sin\\tfrac{\\pi}{7}, \\] so $P = -\\tfrac18$. Since $\\cos\\frac{3\\pi}{7} = -\\cos\\frac{4\\pi}{7}$, the required product is $\\tfrac18$. Option E is $P$ itself, the answer to the question that was not asked; the sign flip on the last cosine is the whole point.<\/p><p><\/p>", "tags": ["trg", "sym"], "rating": 7.5}, {"id": "C1-20", "paper": "C1", "n": 20, "q": "<p>Find \\[ \\lim_{n\\to\\infty}\\ \\sum_{k=1}^{n}\\frac{n}{(n+k)^2}\\, . \\]<\/p>", "opts": ["$2\\ln 2-1$", "$\\dfrac12$", "$\\ln 2$", "$\\dfrac{\\pi}{4}$", "$1$", "the limit does not exist"], "ans": "B", "sol": "<p>Factor out $\\frac1n$: the sum is $\\frac1n\\sum_{k=1}^n\\frac{1}{(1+k/n)^2}$, a Riemann sum for $\\int_0^1\\frac{dx}{(1+x)^2}$. As $n\\to\\infty$ it tends to \\[ \\left[-\\frac{1}{1+x}\\right]_0^1=1-\\frac12=\\frac12 . \\] The recognition is the question: once the sum is seen as rectangles of width $\\frac1n$ under a curve, the limit is an area.<\/p>", "tags": ["arint", "ser"], "rating": 7.5}, {"id": "B1-15", "paper": "B1", "n": 15, "q": "<p>Find the complete set of real values of $k$ for which the equation \\[ 4^x + 4^{-x} = k\\left(2^x + 2^{-x}\\right) - 4 \\] has exactly two real solutions in $x$.<\/p>", "opts": ["$k \\ge 2\\sqrt2$", "$k > 2\\sqrt2$", "$k \\ge 3$", "$k > 3$", "$|k| > 3$", "$k > 2$"], "ans": "D", "sol": "<p>Let $t = 2^x + 2^{-x}$, so $t \\ge 2$ by AM--GM, with $t = 2$ only at $x = 0$, and $4^x + 4^{-x} = t^2 - 2$. The equation becomes $t^2 - kt + 2 = 0$. Each root $t > 2$ gives two values of $x$ (symmetric under $x \\mapsto -x$), $t = 2$ gives one, and $t &lt; 2$ gives none. The roots multiply to $2$, so at most one of them can be $\\ge 2$. Hence exactly two solutions in $x$ needs exactly one root $t > 2$, i.e.\\ the quadratic $h(t) = t^2 - kt + 2$ satisfies $h(2) &lt; 0$, which is $6 - 2k &lt; 0$, so $k > 3$. At $k = 3$ the roots are $2$ and $1$, giving only $x = 0$. Option B is the discriminant condition and ignores the constraint $t \\ge 2$ entirely.<\/p><p><\/p>", "tags": ["sym", "root"], "rating": 7.6}, {"id": "C1-8", "paper": "C1", "n": 8, "q": "<p>Find the total length of the set of values of $x$ in $[0,2\\pi]$ for which \\[ \\sin x+\\sin 2x+\\sin 3x>0 . \\]<\/p>", "opts": ["$\\dfrac{\\pi}{2}$", "$\\dfrac{2\\pi}{3}$", "$\\dfrac{5\\pi}{6}$", "$\\pi$", "$\\dfrac{7\\pi}{6}$", "$\\dfrac{4\\pi}{3}$"], "ans": "D", "sol": "<p>Pair the outer terms: $\\sin x+\\sin3x=2\\sin2x\\cos x$, so the expression is $\\sin2x\\,(2\\cos x+1)$. On $[0,2\\pi]$, $\\sin2x$ changes sign at $\\frac\\pi2,\\pi,\\frac{3\\pi}2$, and $2\\cos x+1$ changes sign at $\\frac{2\\pi}3$ and $\\frac{4\\pi}3$. Checking signs on the six intervals, the product is positive on $(0,\\frac\\pi2)$, $(\\frac{2\\pi}3,\\pi)$ and $(\\frac{4\\pi}3,\\frac{3\\pi}2)$, of total length $\\frac\\pi2+\\frac\\pi3+\\frac\\pi6=\\pi$. If the sum-to-product step is unfamiliar, expand $\\sin3x=3\\sin x-4\\sin^3x$ and $\\sin 2x=2\\sin x\\cos x$ to reach the same factorisation.<\/p><p><\/p>", "tags": ["trg"], "rating": 7.6}, {"id": "C2-16", "paper": "C2", "n": 16, "q": "<p>Let $a$, $b$, $c$ be real numbers and $f(x)=ax^2+bx+c$. Consider the conditions \\[ (1)\\ a>0,\\qquad (2)\\ b^2&lt;4ac,\\qquad (3)\\ c>0,\\qquad (4)\\ f(x)>0\\text{ for every real } x . \\] Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>Conditions (1) and (2) together imply (3).<\/li><li>Condition (4) implies both (1) and (2).<\/li><li>Conditions (2) and (3) together imply (1).<\/li><\/ol><\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "II and III only", "I, II and III"], "ans": "D", "sol": "<p>I: $4ac>b^2\\ge0$ and $a>0$ force $c>0$. II fails: $a=b=0$, $c=1$ gives $f\\equiv1>0$, yet (1) fails. The question does not say $f$ is quadratic, and that is the whole trap. III: $4ac>b^2\\ge0$ with $c>0$ forces $a>0$. So I and III.<\/p><p><\/p>", "tags": ["ns", "poly"], "rating": 7.6}, {"id": "D1-18", "paper": "D1", "n": 18, "q": "<p>The line $y=kx$, where $0&lt;k&lt;4$, divides the finite region enclosed by the curve $y=x(4-x)$ and the $x$-axis into two parts of equal area. Find $k$.<\/p>", "opts": ["$4-2\\sqrt2$", "$4-2\\sqrt[3]{4}$", "$2$", "$4-\\sqrt[3]{16}$", "$\\dfrac83$", "$4-\\sqrt[3]{2}$"], "ans": "B", "sol": "<p>The whole region has area $\\int_0^4(4x-x^2)\\,dx=\\tfrac{32}{3}$. The line meets the curve again where $4-x=k$. The part between the curve and the line has area \\[\\int_0^{4-k}\\left((4-k)x-x^2\\right)dx=\\frac{(4-k)^3}{6},\\] the familiar $\\tfrac{w^3}{6}$ for the segment of $y=x(w-x)$. Setting this equal to $\\tfrac{16}{3}$ gives $(4-k)^3=32$, so $4-k=\\sqrt[3]{32}=2\\sqrt[3]4$ and $k=4-2\\sqrt[3]{4}$. Using a square root instead of a cube root gives option A.<\/p>", "tags": ["arint"], "rating": 7.6}, {"id": "C1-17", "paper": "C1", "n": 17, "q": "<p>Find the total length of the set of values of $x$ in $[0,2\\pi]$ for which \\[ |\\sin x|+|\\cos x|>\\sqrt{\\tfrac32}\\, . \\]<\/p>", "opts": ["$\\dfrac{\\pi}{3}$", "$\\dfrac{\\pi}{2}$", "$\\dfrac{2\\pi}{3}$", "$\\pi$", "$\\dfrac{7\\pi}{6}$", "$\\dfrac{4\\pi}{3}$"], "ans": "F", "sol": "<p>Both sides are positive, so squaring is reversible: $(|\\sin x|+|\\cos x|)^2=1+2|\\sin x\\cos x|=1+|\\sin2x|$. The inequality becomes $1+|\\sin2x|>\\frac32$, that is $|\\sin2x|>\\frac12$. As $x$ runs over $[0,2\\pi]$, $2x$ runs over $[0,4\\pi]$, two full periods, and in each period $|\\sin\\phi|>\\frac12$ on a set of length $\\frac{4\\pi}{3}$. So the set of $2x$ has length $\\frac{8\\pi}{3}$ and the set of $x$ has length $\\frac{4\\pi}{3}$. Forgetting to halve at the end gives $\\frac{8\\pi}{3}$; forgetting that there are two periods gives option C.<\/p><p><\/p>", "tags": ["trg"], "rating": 7.7}, {"id": "B2-6", "paper": "B2", "n": 6, "q": "<p>Let $f$ be a continuous function on $[0,2]$ with $\\displaystyle\\int_0^2 f(x)\\,dx = 0$. Consider: <ol class=\"stmts\" type=\"I\"><li>There is some $c$ with $0 &lt; c &lt; 2$ and $\\displaystyle\\int_0^c f(x)\\,dx = 0$.<\/li><li>There is some $c$ with $0 &lt; c &lt; 2$ and $f(c) = 0$.<\/li><li>There is some $c$ with $0 \\le c \\le 1$ and $\\displaystyle\\int_c^{c+1} f(x)\\,dx = 0$.<\/li><\/ol> Which of these statements must be true?<\/p>", "opts": ["I only", "II only", "III only", "I and II only", "II and III only", "I, II and III"], "ans": "E", "sol": "<p>Let $F(c) = \\int_0^c f$, so $F(0) = F(2) = 0$. For II, $F$ is differentiable with $F' = f$, and a function that starts and ends at $0$ must have zero derivative somewhere in between (if $F$ is not identically zero it has an interior maximum or minimum, where $F' = 0$; if it is identically zero then $f \\equiv 0$). So II holds. For III, let $g(c) = \\int_c^{c+1} f$ for $0 \\le c \\le 1$. Then $g(0) + g(1) = \\int_0^1 f + \\int_1^2 f = 0$, so $g(0)$ and $g(1)$ are of opposite sign or both zero, and since $g$ is continuous it vanishes somewhere on $[0,1]$. So III holds. I fails: $f(x) = 1 - x$ has $\\int_0^2 f = 0$ but $F(c) = c - \\tfrac12 c^2 = \\tfrac12 c(2-c) > 0$ for $0 &lt; c &lt; 2$. The answer is II and III. The idea in III, adding the two half-length integrals to force a sign change, is worth remembering; it is the reason there is always a unit-length interval on which $f$ has zero average.<\/p><p><\/p>", "tags": ["fint"], "rating": 7.8}, {"id": "D2-19", "paper": "D2", "n": 19, "q": "<p>Which of the following conditions on the real numbers $b$ and $c$ is necessary and sufficient for the equation $x^2+bx+c=0$ to have two distinct positive roots?<\/p>", "opts": ["$b&lt;0$ and $c>0$", "$b^2>4c$ and $c>0$", "$b&lt;0$ and $b^2>4c$", "$c>0$ and $b&lt;-2\\sqrt c$", "$b&lt;-2\\sqrt c$", "$b&lt;0$, $c>0$ and $b^2\\ge4c$"], "ans": "D", "sol": "<p>Two distinct positive roots means distinct real roots ($b^2>4c$), a positive product ($c>0$) and a positive sum ($-b>0$). With $c>0$, the pair $b&lt;0$ and $b^2>4c$ is the single condition $b&lt;-2\\sqrt c$, so D is exactly right. E alone allows $c=0$, which gives the roots $0$ and $-b$. A allows complex roots, B allows two negative roots, C allows $c&lt;0$ with roots of opposite signs, and F allows a repeated root.<\/p>", "tags": ["ns", "quad"], "rating": 7.8}, {"id": "C2-20", "paper": "C2", "n": 20, "q": "<p>For each positive integer $n$, $S(n)$ is a statement. It is known that $S(10)$ is true, and that for every positive integer $n$, \\[ \\text{if } S(n) \\text{ is true then } S(n+3) \\text{ is true,}\\qquad\\text{and}\\qquad \\text{if } S(n+2) \\text{ is true then } S(n) \\text{ is true.} \\] Which of the following is the set of positive integers $n$ for which $S(n)$ must be true?<\/p>", "opts": ["$\\{10\\}$", "$\\{2,4,6,8,10\\}$", "$\\{2,4,6,8,10\\}\\cup\\{13,16,19,\\dots\\}$", "$\\{1,2,\\dots,10\\}$", "$\\{10,11,12,\\dots\\}$", "all positive integers"], "ans": "F", "sol": "<p>From $S(10)$, the second rule gives $S(8),S(6),S(4),S(2)$. Now combine the rules: if $S(n)$ holds then $S(n+3)$ holds, and then the second rule gives $S(n+1)$. So each true statement makes the next one true, and once $S(1)$ is reached everything follows. It is: $S(2)\\Rightarrow S(5)$, then $S(5)\\Rightarrow S(3)\\Rightarrow S(1)$. So $S(n)$ is true for every positive integer $n$. Seeing that $+3$ followed by $-2$ is a step of $+1$ is the idea; tracking individual implications by hand, you tend to stop at one of the partial sets in the other options.<\/p>", "tags": ["log"], "rating": 7.9}, {"id": "B2-10", "paper": "B2", "n": 10, "q": "<p>$A$, $B$, $C$, $D$ are four points in the plane, no three of which are collinear, with $AB = CD$ and $AD = BC$. Consider: <ol class=\"stmts\" type=\"I\"><li>$ABCD$ is a parallelogram.<\/li><li>The segments $AC$ and $BD$ bisect each other.<\/li><li>Triangles $ABC$ and $CDA$ are congruent.<\/li><\/ol> Which of these statements must be true?<\/p>", "opts": ["I only", "II only", "III only", "I and II only", "I and III only", "I, II and III"], "ans": "C", "sol": "<p>Triangles $ABC$ and $CDA$ share the side $AC$ and have $AB = CD$, $BC = DA$, so they are congruent by SSS: III must hold. But congruence leaves two positions for $D$ relative to the fixed triangle $ABC$: the reflection of $B$ through the midpoint of $AC$, which makes $ABCD$ a parallelogram, and the reflection of $B$ in the perpendicular bisector of $AC$, which puts $D$ on the same side of $AC$ as $B$. In the second case $ABCD$ is a crossed quadrilateral (its &ldquo;sides&rdquo; $AB$ and $CD$ cross), $BD$ is parallel to $AC$, and neither I nor II holds. Only III must be true. The trap is that &ldquo;two pairs of equal opposite sides&rdquo; is a parallelogram criterion for convex quadrilaterals, and the question never said convex.<\/p><p><\/p>", "tags": ["circ", "log"], "rating": 8.0}, {"id": "D1-19", "paper": "D1", "n": 19, "q": "<p>Find the complete set of real values of $k$ for which both roots of \\[x^2-2kx+k+6=0\\] are real and lie strictly between $-3$ and $3$. (A repeated root counts as both roots.)<\/p>", "opts": ["no such $k$", "$-3&lt;k\\le-2$", "$-\\tfrac{15}{7}&lt;k&lt;-2$", "$k\\le-2$", "$-\\tfrac{15}{7}&lt;k\\le-2$", "$-\\tfrac{15}{7}&lt;k&lt;3$"], "ans": "E", "sol": "<p>Let $f(x)=x^2-2kx+k+6$. Both roots lie in $(-3,3)$ exactly when the roots are real, the vertex $x=k$ lies in $(-3,3)$, and $f(-3)>0$ and $f(3)>0$. Real roots: $k^2-k-6\\ge0$, so $k\\le-2$ or $k\\ge3$. Vertex: $-3&lt;k&lt;3$. $f(3)=15-5k>0$ gives $k&lt;3$, and $f(-3)=7k+15>0$ gives $k>-\\tfrac{15}{7}$. Intersecting, $-\\tfrac{15}{7}&lt;k\\le-2$. At $k=-2$ the repeated root $x=-2$ is inside the interval, so the endpoint is included. The condition $f(-3)>0$ is the one most often forgotten, and it is the only one that cuts the interval from below.<\/p>", "tags": ["quad"], "rating": 8.0}, {"id": "E2-20", "paper": "E2", "n": 20, "q": "<p>Real numbers $a$ and $b$ satisfy $0&lt;a&lt;b&lt;1$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$a^b&lt;b^a$<\/li><li>$a^a&lt;b^b$<\/li><li>$\\log_b a>1$<\/li><li>$a^b&lt;a^a$<\/li><\/ol><\/p>", "opts": ["I and III only", "III and IV only", "I, III and IV only", "I, II, III and IV", "I and IV only", "II, III and IV only"], "ans": "C", "sol": "<p>IV: for a base between $0$ and $1$, a larger exponent gives a smaller power, and $b>a$. I needs no calculus: $a^b&lt;b^b$, because raising to the positive power $b$ preserves $a&lt;b$, and $b^b&lt;b^a$ by the same fact as IV with base $b$. So $a^b&lt;b^b&lt;b^a$. III: $\\log_ba=\\frac{\\ln a}{\\ln b}$ is a ratio of two negative numbers, and $|\\ln a|>|\\ln b|$, so it exceeds $1$. II fails: $a=0.1$, $b=0.3$ gives $a^a\\approx0.794$ and $b^b\\approx0.697$. The function $x^x$ decreases before it increases, so no ordering is forced.<\/p>", "tags": ["exp", "ineq"], "rating": 8.0}, {"id": "F1-20", "paper": "F1", "n": 20, "q": "<p>For how many integers $c$ does the equation \\[x^3-6x^2+9x+c=0\\] have three distinct positive real roots?<\/p>", "opts": ["$1$", "$2$", "$3$", "$4$", "$5$", "$6$"], "ans": "C", "sol": "<p>$f'(x)=3(x-1)(x-3)$, with a local maximum $f(1)=4+c$ and a local minimum $f(3)=c$. Three distinct real roots need $f(1)>0>f(3)$, that is $-4&lt;c&lt;0$. They are all positive exactly when the smallest root is: since $f(0)=c&lt;0$ and $f(1)>0$, the smallest root lies in $(0,1)$. So $c\\in\\{-3,-2,-1\\}$, three integers. At $c=0$ one root is $0$, not positive, and at $c=-4$ a repeated root appears.<\/p>", "tags": ["root", "diff"], "rating": 8.0}, {"id": "B1-3", "paper": "B1", "n": 3, "q": "<p>A polynomial $p$ of degree $4$ satisfies $p(k) = 2^k$ for $k = 0, 1, 2, 3, 4$. Find $p(5)$.<\/p>", "opts": ["$16$", "$30$", "$31$", "$32$", "$33$", "$64$"], "ans": "C", "sol": "<p>The binomial coefficient $\\binom{x}{j} = \\frac{x(x-1)\\cdots(x-j+1)}{j!}$ is a polynomial in $x$ of degree $j$, and for a non-negative integer $k$ we have $2^k = \\sum_{j=0}^{k}\\binom{k}{j}$, where the terms with $j > k$ vanish. So $p(x) = \\sum_{j=0}^{4}\\binom{x}{j}$ is a quartic with $p(k) = 2^k$ for $k = 0,\\dots,4$, and it is the only one, two quartics agreeing at five points being equal. Then \\[ p(5) = \\sum_{j=0}^{4}\\binom{5}{j} = 2^5 - \\binom55 = 31. \\] The same answer comes from a difference table: the fourth differences of $1,2,4,8,16$ are constant, and extending the table one step gives $31$. The trap is $32$, which assumes a polynomial can imitate $2^x$ one step further than its degree allows.<\/p><p><\/p>", "tags": ["poly"], "rating": 8.2}, {"id": "B2-17", "paper": "B2", "n": 17, "q": "<p>A finite set $S$ of points in the plane has the property that every point of $S$ is the midpoint of the segment joining some two other points of $S$. Which of the following is true?<\/p>", "opts": ["$S$ must be empty.", "$S$ can be non-empty, and any such $S$ has at least $3$ points.", "$S$ can be non-empty, and any such $S$ has at least $4$ points.", "The four vertices of a parallelogram form such a set $S$.", "There is such a set $S$ with exactly $5$ points."], "ans": "A", "sol": "<p>Suppose $S$ is non-empty. Fix any point $O$ and, since $S$ is finite, choose $P \\in S$ furthest from $O$. If $P$ were the midpoint of $XY$ with $X, Y \\in S$ distinct, then $\\overrightarrow{OP} = \\tfrac12\\bigl(\\overrightarrow{OX} + \\overrightarrow{OY}\\bigr)$, and by the triangle inequality \\[ OP \\le \\tfrac12(OX + OY) \\le \\max(OX, OY), \\] with equality throughout only when $\\overrightarrow{OX} = \\overrightarrow{OY}$, i.e.\\ $X = Y$. Since $X \\ne Y$, one of $OX$, $OY$ is larger than $OP$, contradicting the choice of $P$. So no non-empty finite set has the property, and $S$ must be empty; the condition holds for the empty set vacuously. Options D and E fail for the same reason as everything else: in any finite set, the point furthest out is never a midpoint. Choosing an extreme element and showing it cannot satisfy the condition is the entire method.<\/p><p><\/p>", "tags": ["ext"], "rating": 8.2}, {"id": "D1-20", "paper": "D1", "n": 20, "q": "<p>For which values of the constant $c$ is the point of the curve $y=x^2$ that is closest to $(0,c)$ the origin?<\/p>", "opts": ["$c\\le0$", "$c&lt;\\tfrac12$", "$c\\le1$", "$c\\le2$", "$c&lt;1$", "$c\\le\\tfrac12$"], "ans": "F", "sol": "<p>The squared distance from $(x,x^2)$ to $(0,c)$ is $x^2+(x^2-c)^2=u^2+(1-2c)u+c^2$ with $u=x^2\\ge0$. This quadratic in $u$ has its vertex at $u=c-\\tfrac12$. If $c\\le\\tfrac12$ the vertex is at $u\\le0$, so the minimum over $u\\ge0$ is at $u=0$, the origin. If $c>\\tfrac12$ the minimum is at $u=c-\\tfrac12>0$, two points either side of the axis, strictly closer than the origin. So the answer is $c\\le\\tfrac12$. Intuition says the origin wins until $c$ is about the radius of curvature, and the radius of curvature of $y=x^2$ at the origin is exactly $\\tfrac12$.<\/p>", "tags": ["diff", "quad"], "rating": 8.2}, {"id": "F2-20", "paper": "F2", "n": 20, "q": "<p>Real numbers $a$, $b$ and $c$ satisfy $a+b+c=0$ and $a^2+b^2+c^2=6$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$ab+bc+ca=-3$<\/li><li>Each of $a$, $b$ and $c$ lies in the interval $[-2,2]$.<\/li><li>$abc\\le1$<\/li><li>$a^4+b^4+c^4=18$<\/li><\/ol><\/p>", "opts": ["I and II only", "I, II, III and IV", "I and IV only", "II and IV only", "I, II and IV only", "I, II and III only"], "ans": "E", "sol": "<p>I: $0=(a+b+c)^2=6+2(ab+bc+ca)$. II: substituting $c=-a-b$ gives $b^2+ab+a^2-3=0$, and for real $b$ the discriminant $a^2-4(a^2-3)=12-3a^2\\ge0$ forces $|a|\\le2$, and likewise for $b$ and $c$. IV: $\\sum a^2b^2=(ab+bc+ca)^2-2abc(a+b+c)=9$, so $\\sum a^4=36-2\\cdot9=18$. III fails: $a=2$, $b=c=-1$ satisfies both conditions and has $abc=2$.<\/p>", "tags": ["sym", "quad"], "rating": 8.2}, {"id": "B1-4", "paper": "B1", "n": 4, "q": "<p>Let $a$, $b$ and $c$ be the three real roots of $x^3 - 3x + 1 = 0$. Find the value of \\[ (a^2-2)(b^2-2)(c^2-2). \\]<\/p>", "opts": ["$-3$", "$-1$", "$0$", "$1$", "$3$", "$9$"], "ans": "B", "sol": "<p>Write $f(x) = x^3 - 3x + 1 = (x-a)(x-b)(x-c)$. Then $a^2 - 2 = (a-\\sqrt2)(a+\\sqrt2)$, and \\[ \\prod (a-\\sqrt2) = -f(\\sqrt2), \\qquad \\prod (a+\\sqrt2) = -f(-\\sqrt2), \\] so the required product is $f(\\sqrt2)f(-\\sqrt2) = (1-\\sqrt2)(1+\\sqrt2) = -1$. No root is ever found.<\/p><p>The trigonometric route explains the answer. Putting $x = 2\\cos\\theta$ turns $x^3 - 3x$ into $2\\cos 3\\theta$, so the roots are $2\\cos\\frac{2\\pi}{9}$, $2\\cos\\frac{4\\pi}{9}$, $2\\cos\\frac{8\\pi}{9}$, and the map $x \\mapsto x^2 - 2$ is $2\\cos\\theta \\mapsto 2\\cos 2\\theta$, which permutes the three roots. The product is therefore $abc = -1$ by Vieta.<\/p><p><\/p>", "tags": ["vie", "poly"], "rating": 8.3}, {"id": "E1-20", "paper": "E1", "n": 20, "q": "<p>The sequence $u_1,u_2,u_3,\\dots$ is defined by $u_{n+1}=u_n^2-2u_n+2$. For which values of $u_1$ does the sequence remain bounded?<\/p>", "opts": ["$0&lt;u_1&lt;2$", "$1\\le u_1\\le2$", "$-1\\le u_1\\le1$", "$0\\le u_1\\le2$", "$u_1\\le2$", "every real $u_1$"], "ans": "D", "sol": "<p>Complete the square: $u_{n+1}-1=(u_n-1)^2$. So with $v_n=u_n-1$ the recurrence is $v_{n+1}=v_n^{\\,2}$, giving $v_n=v_1^{\\,2^{n-1}}$. This stays bounded exactly when $|v_1|\\le1$, that is $0\\le u_1\\le2$: then $|v_n|\\le1$ throughout. The endpoints behave differently, since $u_1=0$ and $u_1=2$ both lead to the constant sequence $2$, but both are bounded. For $|v_1|>1$ the terms grow without limit.<\/p>", "tags": ["ser", "quad"], "rating": 8.3}, {"id": "C2-18", "paper": "C2", "n": 18, "q": "<p>The function $f$ is continuous and increasing on $[0,1]$. Which of the following must be true? <ol class=\"stmts\" type=\"I\"><li>$\\displaystyle\\int_0^1 f(x)\\,dx\\le f(1)$<\/li><li>$\\displaystyle\\int_0^1 x f(x)\\,dx\\ge \\frac12\\int_0^1 f(x)\\,dx$<\/li><li>$\\displaystyle\\int_0^{1/2} f(x)\\,dx\\le\\int_{1/2}^{1} f(x)\\,dx$<\/li><\/ol><\/p>", "opts": ["I only", "II only", "III only", "I and III only", "II and III only", "I, II and III"], "ans": "F", "sol": "<p>I: $f(x)\\le f(1)$ throughout, so the integral is at most $f(1)$. III: substituting $x\\mapsto x+\\frac12$ gives $\\int_{1/2}^1f=\\int_0^{1/2}f(x+\\frac12)\\,dx\\ge\\int_0^{1/2}f(x)\\,dx$. II is the one needing an idea. Since $\\int_0^1(x-\\frac12)\\,dx=0$, \\[ \\int_0^1\\left(x-\\tfrac12\\right)f(x)\\,dx=\\int_0^1\\left(x-\\tfrac12\\right)\\left(f(x)-f\\left(\\tfrac12\\right)\\right)dx\\ge0, \\] because both brackets are negative for $x&lt;\\frac12$ and non-negative for $x>\\frac12$. That rearranges to II. All three.<\/p><p><\/p>", "tags": ["fint", "ineq"], "rating": 8.4}, {"id": "D2-20", "paper": "D2", "n": 20, "q": "<p>The sequence $u_1,u_2,u_3,\\dots$ is defined by $u_1=1$ and $u_{n+1}=u_n+\\dfrac{2}{u_n}$. Which of the following are true? <ol class=\"stmts\" type=\"I\"><li>$u_{n+1}>u_n$ for every $n$.<\/li><li>$u_n^{\\,2}>4n-4$ for every $n\\ge2$.<\/li><li>$u_{100}>20$<\/li><li>$u_{100}>30$<\/li><\/ol><\/p>", "opts": ["I only", "I and II only", "I, II and IV only", "I and III only", "I, II and III only", "I, II, III and IV"], "ans": "E", "sol": "<p>Every $u_n$ is positive, so I holds. Squaring the recurrence gives $u_{n+1}^2=u_n^2+4+\\frac{4}{u_n^2}>u_n^2+4$, and adding these from $n=1$ gives II. II alone gives only $u_{100}^2>396$, not enough for III, so keep the error terms: $u_{100}^2=1+4\\cdot99+\\sum_{n=1}^{99}\\frac4{u_n^2}\\ge397+\\frac{4}{u_1^2}=401>400$, and III holds. For IV, each $\\frac4{u_n^2}\\le4$, so $u_{100}^2\\le1+99\\cdot8=793&lt;900$ and IV is false. (In fact $u_{100}\\approx20.1$.)<\/p>", "tags": ["ser", "ineq"], "rating": 8.4}, {"id": "B1-9", "paper": "B1", "n": 9, "q": "<p>A regular heptagon has side length $1$. Its diagonals take exactly two distinct lengths, $p &lt; q$. Find the value of $\\dfrac1p + \\dfrac1q$.<\/p>", "opts": ["$\\dfrac12$", "$\\dfrac{\\sqrt2}{2}$", "$1$", "$\\dfrac{\\sqrt7}{2}$", "$\\dfrac32$", "$2$"], "ans": "C", "sol": "<p>Label the heptagon $ABCDEFG$, with side $1$, short diagonal $p$ (two steps apart, e.g.\\ $AC$) and long diagonal $q$ (three steps apart, e.g.\\ $AD$). Every regular polygon is cyclic, so Ptolemy applies to any four vertices. On the quadrilateral $ABCE$ the sides are $AB = BC = 1$, $CE = p$, $EA = q$ and the diagonals are $AC = p$, $BE = q$, so Ptolemy gives \\[ AC\\cdot BE = AB\\cdot CE + BC\\cdot EA, \\qquad pq = p + q, \\] so $\\frac1p + \\frac1q = 1$ on dividing by $pq$. The lengths themselves are $p = 2\\cos\\frac{\\pi}{7}$ and $q = 1 + p - \\frac1p$, neither of which is needed. Ptolemy on $ABCD$ gives the companion identity $p^2 = 1 + q$.<\/p><p><\/p>", "tags": ["circ"], "rating": 8.6}, {"id": "C1-18", "paper": "C1", "n": 18, "q": "<p>Find the complete set of real values of $a$ for which \\[ a\\sin x+\\cos 2x\\le 1+a\\qquad\\text{for all real } x . \\]<\/p>", "opts": ["$0\\le a\\le 4$", "$0\\le a\\le 8$", "$-1\\le a\\le 8$", "$a\\ge -1$", "$a\\ge 0$", "all real $a$"], "ans": "E", "sol": "<p>With $s=\\sin x$ and $\\cos2x=1-2s^2$, the condition is $g(s)=2s^2-as+a\\ge0$ for all $s\\in[-1,1]$. The minimum of $g$ on $[-1,1]$ depends on where the vertex $s=\\frac a4$ lies. If $-4\\le a\\le4$, the minimum is $g(\\frac a4)=a-\\frac{a^2}{8}$, which is non-negative for $0\\le a\\le 8$, so here $0\\le a\\le4$. If $a>4$, the vertex is to the right of the interval and the minimum is $g(1)=2>0$, so every $a>4$ works. If $a&lt;-4$, the minimum is $g(-1)=2+2a&lt;0$. Altogether $a\\ge0$. Option B is the discriminant condition applied without restricting $s$ to $[-1,1]$: it wrongly throws away every $a>8$.<\/p><p><\/p>", "tags": ["trg", "ineq"], "rating": 8.7}, {"id": "B2-19", "paper": "B2", "n": 19, "q": "<p>The positive integer $n$ is such that $3n + 1$ and $4n + 1$ are both perfect squares. What is the largest integer that must divide $n$?<\/p>", "opts": ["$4$", "$8$", "$14$", "$28$", "$56$", "$112$"], "ans": "E", "sol": "<p>Write $3n + 1 = a^2$ and $4n + 1 = b^2$. Since $4n + 1$ is odd, $b$ is odd, so $b^2 \\equiv 1 \\pmod 8$ and $4n \\equiv 0 \\pmod 8$: $n$ is even. Then $3n + 1$ is odd, so $a$ is odd and $a^2 \\equiv 1 \\pmod 8$, giving $3n \\equiv 0 \\pmod 8$, so $8 \\mid n$. Now modulo $7$: squares are $0, 1, 2, 4$, and $a^2 + b^2 = 7n + 2 \\equiv 2$. The only way two squares sum to $2$ modulo $7$ is $1 + 1$, so $a^2 \\equiv 1$, hence $3n \\equiv 0 \\pmod 7$ and $7 \\mid n$. Therefore $56 \\mid n$. And $n = 56$ itself works: $169 = 13^2$ and $225 = 15^2$, so no larger divisor is forced. The answer is $56$. Option D is what one gets from the mod $7$ argument together with only a partial mod $8$ argument.<\/p><p><\/p>", "tags": ["mod"], "rating": 8.8}, {"id": "B2-18", "paper": "B2", "n": 18, "q": "<p>Let $f$ be a continuous function on $[0,1]$ satisfying \\[ \\int_0^1 f(x)\\,dx = 0 \\qquad\\text{and}\\qquad \\int_0^1 x f(x)\\,dx = 0 . \\] Consider: <ol class=\"stmts\" type=\"I\"><li>$f(c) = 0$ for at least one $c$ in $(0,1)$.<\/li><li>$f(c) = 0$ for at least two distinct values of $c$ in $(0,1)$.<\/li><li>$f(x) = 0$ for every $x$ in $[0,1]$.<\/li><\/ol> Which of these statements must be true?<\/p>", "opts": ["I only", "II only", "I and II only", "I and III only", "II and III only", "I, II and III"], "ans": "C", "sol": "<p>I: if $f$ were never zero on $(0,1)$ it would keep one sign there by continuity, and its integral could not be $0$. So $f$ changes sign, and has a zero. II: suppose $f$ changes sign at only one point $c$, so $f$ has one sign on $(0,c)$ and the opposite sign on $(c,1)$. Then $(x - c)f(x)$ has the same sign on both intervals and is not identically zero, so $\\int_0^1 (x-c)f(x)\\,dx \\ne 0$. But that integral equals $\\int_0^1 xf - c\\int_0^1 f = 0 - 0$, a contradiction. So $f$ changes sign at least twice, giving at least two zeros; and if $f \\equiv 0$ it has infinitely many. III fails: $f(x) = x^2 - x + \\tfrac16$ has $\\int_0^1 f = \\tfrac13 - \\tfrac12 + \\tfrac16 = 0$ and $\\int_0^1 xf = \\tfrac14 - \\tfrac13 + \\tfrac1{12} = 0$ without vanishing. The answer is I and II. The multiplier $(x - c)$ is the idea: it is a function of one sign built to be orthogonal to nothing but $f$.<\/p><p><\/p>", "tags": ["fint"], "rating": 9.0}];
/* Paper difficulty on the same 4.5 to 9 scale: the average of the mean question rating
   and the mean of the five hardest questions, so a harder final stretch counts for more. */
window.HU_PAPER_RATINGS=(function(){ var by={}, out={};
  window.HU_QUESTIONS.forEach(function(q){ (by[q.paper]=by[q.paper]||[]).push(q.rating); });
  Object.keys(by).forEach(function(p){ var r=by[p].slice().sort(function(a,b){return a-b;}), mean=r.reduce(function(s,x){return s+x;},0)/r.length,
    top=r.slice(-5).reduce(function(s,x){return s+x;},0)/5; out[p]={rating:Math.round((mean+top)/2*10)/10,mean:Math.round(mean*10)/10,top5:Math.round(top*10)/10,max:r[r.length-1]}; });
  return out; })();
